<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no">
<title>Dune II &mdash; The Battle for Arrakis</title>
<link rel="stylesheet" href="css/main.css">
<link rel="stylesheet" href="css/screens.css">
<link rel="stylesheet" href="css/hud.css">
</head>
<body>
<div id="app">

  <!-- ============================= TITLE ============================= -->
  <section id="screen-menu" class="screen active">
    <div class="starfield"></div>
    <div class="menu-wrap">
      <h1 class="game-title"><span class="t1">DUNE</span><span class="t2">II</span></h1>
      <p class="game-sub">THE BATTLE FOR ARRAKIS</p>
      <p class="game-tag">&ldquo;The spice must flow.&rdquo;</p>
      <div class="menu-buttons">
        <button class="dbtn big" id="mm-new">NEW CAMPAIGN</button>
        <button class="dbtn big" id="mm-continue">CONTINUE</button>
        <button class="dbtn big" id="mm-help">FIELD MANUAL</button>
      </div>
      <p class="menu-foot">An unofficial tribute build &mdash; vanilla HTML / CSS / JS, no network, no assets.</p>
    </div>
  </section>

  <!-- ========================== HOUSE SELECT ========================== -->
  <section id="screen-house" class="screen">
    <div class="hs-head">
      <h2>SELECT YOUR HOUSE</h2>
      <p>The Emperor has offered the governorship of Arrakis to whichever House produces the most spice. Three Houses accept. Only one will rule.</p>
    </div>
    <div class="house-cards" id="house-cards"></div>
    <div class="hs-foot"><button class="dbtn" id="hs-back">BACK</button></div>
  </section>

  <!-- ========================== CAMPAIGN MAP ========================== -->
  <section id="screen-map" class="screen">
    <div class="cm-head">
      <h2 id="cm-title">ARRAKIS</h2>
      <p id="cm-sub">Select your next target territory.</p>
    </div>
    <div class="cm-body">
      <div class="cm-canvas-wrap">
        <canvas id="campaign-canvas" width="900" height="560"></canvas>
      </div>
      <aside class="cm-side">
        <div class="cm-panel">
          <h3 id="cm-terr-name">&mdash;</h3>
          <div id="cm-terr-body" class="cm-terr-body">
            <p class="dim">Hover a highlighted territory to scout it.</p>
          </div>
        </div>
        <div class="cm-panel cm-progress">
          <h3>CAMPAIGN</h3>
          <div class="kv"><span>HOUSE</span><b id="cm-house">&mdash;</b></div>
          <div class="kv"><span>MISSION</span><b id="cm-mission">&mdash;</b></div>
          <div class="kv"><span>TERRITORIES</span><b id="cm-owned">0</b></div>
        </div>
        <button class="dbtn big" id="cm-attack" disabled>ATTACK</button>
        <button class="dbtn" id="cm-quit">ABANDON CAMPAIGN</button>
      </aside>
    </div>
  </section>

  <!-- ============================= MENTAT ============================= -->
  <section id="screen-mentat" class="screen">
    <div class="mentat-frame">
      <div class="mentat-left">
        <canvas id="mentat-canvas" width="320" height="380"></canvas>
        <div class="mentat-name" id="mentat-name">MENTAT</div>
      </div>
      <div class="mentat-right">
        <h2 id="mentat-title">MISSION BRIEFING</h2>
        <div class="mentat-text" id="mentat-text"></div>
        <div class="mentat-obj" id="mentat-obj"></div>
        <div class="mentat-buttons">
          <button class="dbtn" id="mentat-repeat">REPEAT</button>
          <button class="dbtn primary" id="mentat-proceed">PROCEED</button>
        </div>
      </div>
    </div>
  </section>

  <!-- ============================== GAME ============================== -->
  <section id="screen-game" class="screen">
    <header id="topbar">
      <div class="tb-left">
        <span id="house-crest" class="crest"></span>
        <span id="mission-name">MISSION</span>
      </div>
      <div class="tb-mid">
        <div class="readout credits"><label>CREDITS</label><span id="ro-credits">0</span></div>
        <div class="readout"><label>SPICE</label><div class="bar"><i id="ro-spicebar"></i></div><span id="ro-spicetext">0/0</span></div>
        <div class="readout"><label>POWER</label><div class="bar"><i id="ro-powerbar"></i></div><span id="ro-powertext">0/0</span></div>
        <div class="readout obj"><label>OBJECTIVE</label><span id="ro-objective">&mdash;</span></div>
      </div>
      <div class="tb-right">
        <button class="dbtn tiny" id="gb-mentat">MENTAT</button>
        <button class="dbtn tiny" id="gb-help">HELP</button>
        <button class="dbtn tiny" id="gb-sound">SOUND ON</button>
        <button class="dbtn tiny" id="gb-pause">PAUSE</button>
        <button class="dbtn tiny danger" id="gb-abort">ABORT</button>
      </div>
    </header>

    <div id="playfield">
      <canvas id="game-canvas"></canvas>
      <div id="alerts"></div>
      <div id="pause-veil"><span>PAUSED</span></div>
    </div>

    <aside id="sidebar">
      <div class="radar-box">
        <canvas id="minimap" width="212" height="212"></canvas>
        <div id="radar-off">RADAR<br>OFFLINE</div>
      </div>
      <div id="build-tabs">
        <button data-tab="structure" class="active">BUILD</button>
        <button data-tab="unit">UNITS</button>
      </div>
      <div id="build-list"></div>
      <div id="special-panel"></div>
    </aside>

    <footer id="bottombar">
      <div id="sel-info"><span class="dim">No selection.</span></div>
      <div id="order-buttons"></div>
    </footer>
  </section>

  <!-- ============================= RESULT ============================= -->
  <section id="screen-result" class="screen">
    <div class="result-wrap">
      <h2 id="res-title">MISSION COMPLETE</h2>
      <p id="res-sub"></p>
      <div class="res-stats" id="res-stats"></div>
      <div class="res-buttons">
        <button class="dbtn big" id="res-continue">CONTINUE</button>
        <button class="dbtn" id="res-retry">RETRY MISSION</button>
        <button class="dbtn" id="res-menu">MAIN MENU</button>
      </div>
    </div>
  </section>

  <!-- ============================== HELP ============================== -->
  <div id="help-overlay">
    <div class="help-box">
      <h2>FIELD MANUAL</h2>
      <div class="help-cols" id="help-body"></div>
      <button class="dbtn" id="help-close">CLOSE</button>
    </div>
  </div>

</div>

<script src="js/util/util.js"></script>
<script src="js/audio/sfx.js"></script>
<script src="js/data/config.js"></script>
<script src="js/data/houses.js"></script>
<script src="js/data/structures.js"></script>
<script src="js/data/units.js"></script>
<script src="js/data/campaign.js"></script>
<script src="js/world/map.js"></script>
<script src="js/world/pathfinder.js"></script>
<script src="js/world/fog.js"></script>
<script src="js/world/worm.js"></script>
<script src="js/entities/effects.js"></script>
<script src="js/entities/projectile.js"></script>
<script src="js/entities/structure.js"></script>
<script src="js/entities/unit.js"></script>
<script src="js/systems/combat.js"></script>
<script src="js/systems/faction.js"></script>
<script src="js/systems/ai.js"></script>
<script src="js/render/sprites.js"></script>
<script src="js/render/renderer.js"></script>
<script src="js/render/minimap.js"></script>
<script src="js/ui/mentat.js"></script>
<script src="js/ui/campaignmap.js"></script>
<script src="js/ui/sidebar.js"></script>
<script src="js/ui/hud.js"></script>
<script src="js/ui/input.js"></script>
<script src="js/game.js"></script>
<script src="js/main.js"></script>
</body>
</html>
"},{"path":"css/hud.css","type":"text/css","text":"/* ==========================================================================
   Dune II - in-mission HUD
   ========================================================================== */

#screen-game{display:none;background:#000;}
#screen-game.active{
  display:grid;
  grid-template-columns:1fr 232px;
  grid-template-rows:42px 1fr 86px;
  grid-template-areas:
    "top   top"
    "field side"
    "bot   side";
}

/* -------------------------------- topbar -------------------------------- */
#topbar{
  grid-area:top;display:flex;align-items:center;gap:14px;padding:0 10px;
  background:linear-gradient(180deg,#4a3419,#241808);
  border-bottom:2px solid #100b05;
  font-size:12px;
}
.tb-left{display:flex;align-items:center;gap:8px;min-width:210px;}
.crest{width:22px;height:22px;display:inline-block;border:1px solid #1a1108;}
#mission-name{font-weight:800;letter-spacing:.11em;color:var(--sand-7);font-size:12px;white-space:nowrap;}
.tb-mid{flex:1;display:flex;align-items:center;gap:18px;justify-content:center;}
.readout{display:flex;align-items:center;gap:7px;}
.readout label{font-size:9.5px;letter-spacing:.14em;color:#c8a05a;}
.readout span{font-family:var(--font-mono);font-size:13px;color:var(--sand-7);}
.readout.credits span{font-size:17px;color:var(--amber);text-shadow:0 0 8px rgba(240,169,46,.5);min-width:64px;display:inline-block;}
.readout.credits.flash span{color:#fff;}
.readout .bar{
  width:88px;height:11px;background:#191107;border:1px solid #6b4f27;position:relative;overflow:hidden;
}
.readout .bar i{position:absolute;left:0;top:0;bottom:0;width:0%;background:var(--ok);transition:width .25s linear;}
.readout .bar i.warn{background:var(--amber);}
.readout .bar i.crit{background:var(--danger);}
.readout.obj{max-width:330px;}
.readout.obj span{font-size:11px;color:#e0bd80;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:250px;display:inline-block;}
.tb-right{display:flex;gap:5px;}

/* ------------------------------- playfield ------------------------------ */
#playfield{grid-area:field;position:relative;overflow:hidden;background:#1a1208;}
#game-canvas{position:absolute;inset:0;width:100%;height:100%;cursor:default;}
#game-canvas.place{cursor:cell;}
#game-canvas.attack{cursor:crosshair;}

#alerts{position:absolute;left:10px;bottom:10px;display:flex;flex-direction:column-reverse;gap:5px;pointer-events:none;}
.alert{
  font-size:12px;letter-spacing:.06em;padding:5px 11px;
  background:rgba(20,13,6,.85);border-left:3px solid var(--amber);color:#f0d7a6;
  animation:alertIn .18s ease-out;
}
.alert.bad{border-left-color:var(--danger);color:#ffb9ac;}
.alert.good{border-left-color:var(--ok);color:#bff0c4;}
.alert.fade{opacity:0;transition:opacity .6s linear;}
@keyframes alertIn{from{transform:translateX(-18px);opacity:0}to{transform:none;opacity:1}}

#pause-veil{
  position:absolute;inset:0;display:none;align-items:center;justify-content:center;
  background:rgba(8,5,2,.6);z-index:5;
}
#pause-veil.show{display:flex;}
#pause-veil span{font-size:44px;letter-spacing:.35em;color:var(--amber);font-weight:800;}

/* -------------------------------- sidebar ------------------------------- */
#sidebar{
  grid-area:side;display:flex;flex-direction:column;min-height:0;
  background:linear-gradient(180deg,#3a2812,#1c1308);
  border-left:2px solid #100b05;
}
.radar-box{position:relative;width:100%;height:216px;flex:0 0 216px;background:#080502;border-bottom:2px solid #100b05;
  display:flex;align-items:center;justify-content:center;}
#minimap{width:212px;height:212px;cursor:crosshair;}
#radar-off{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  text-align:center;font-size:12px;letter-spacing:.15em;color:#7a5a2c;
  background:repeating-linear-gradient(45deg,#0d0904 0 6px,#120c06 6px 12px);
}
#radar-off.hide{display:none;}

#build-tabs{display:flex;flex:0 0 26px;}
#build-tabs button{
  flex:1;font-family:var(--font-ui);font-size:11px;font-weight:800;letter-spacing:.14em;
  background:#251a0c;color:#8a6a36;border:0;border-bottom:2px solid #100b05;cursor:pointer;
}
#build-tabs button.active{background:#5a4222;color:var(--amber);}

#build-list{flex:1;overflow-y:auto;overflow-x:hidden;padding:4px;min-height:0;}
.bitem{
  position:relative;display:flex;gap:7px;align-items:center;
  padding:4px;margin-bottom:3px;cursor:pointer;
  background:linear-gradient(180deg,#4a3419,#2b1e0e);
  border:1px solid #6b4f27;
  overflow:hidden;
}
.bitem:hover{filter:brightness(1.2);}
.bitem.locked{opacity:.36;cursor:not-allowed;filter:grayscale(.7);}
.bitem.cantafford .cost{color:var(--danger);}
.bitem.building{border-color:var(--amber);}
.bitem.ready{border-color:var(--ok);box-shadow:0 0 8px rgba(94,196,106,.4);}
.bitem canvas{flex:0 0 40px;width:40px;height:34px;background:#171009;border:1px solid #38270f;}
.bitem .meta{flex:1;min-width:0;}
.bitem .nm{font-size:11px;font-weight:700;letter-spacing:.04em;color:#f0d7a6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.bitem .cost{font-family:var(--font-mono);font-size:11px;color:var(--amber);}
.bitem .sub{font-size:9.5px;color:#9a7a48;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.bitem .qty{
  position:absolute;right:3px;top:3px;font-family:var(--font-mono);font-size:10px;
  background:#1a1108;border:1px solid #6b4f27;padding:0 3px;color:var(--amber);
}
.bitem .prog{
  position:absolute;left:0;bottom:0;height:3px;background:var(--amber);width:0%;
}
.bitem .veil{
  position:absolute;inset:0;background:rgba(10,7,3,.55);
  display:flex;align-items:center;justify-content:center;
  font-size:11px;font-weight:800;letter-spacing:.1em;color:#fff;
}
.bitem .veil.ready{background:rgba(20,80,24,.45);color:#bff0c4;animation:pulse 1s infinite;}
.bitem .veil.hold{background:rgba(80,20,10,.45);color:#ffb9ac;}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.5}}

#special-panel{flex:0 0 auto;padding:4px;border-top:2px solid #100b05;}
#special-panel:empty{display:none;}
.special-btn{
  width:100%;padding:7px;font-size:11px;font-weight:800;letter-spacing:.09em;
  background:linear-gradient(180deg,#7a3ea8,#3d1d55);border:1px solid #b06fe0;color:#f3dcff;
  cursor:pointer;position:relative;overflow:hidden;
}
.special-btn:disabled{filter:grayscale(.7);opacity:.6;cursor:not-allowed;}
.special-btn i{position:absolute;left:0;bottom:0;height:3px;background:#e0b3ff;}

/* ------------------------------- bottombar ------------------------------ */
#bottombar{
  grid-area:bot;display:flex;align-items:stretch;gap:10px;padding:5px 8px;
  background:linear-gradient(180deg,#3a2812,#1c1308);
  border-top:2px solid #100b05;
  min-height:0;
}
#sel-info{flex:1;min-width:0;overflow:hidden;font-size:11.5px;line-height:1.45;color:var(--sand-6);}
#sel-info .title{font-weight:800;letter-spacing:.09em;color:var(--amber);font-size:13px;}
#sel-info .row{display:flex;gap:14px;flex-wrap:wrap;margin-top:2px;}
#sel-info .chip{
  display:inline-flex;align-items:center;gap:5px;
  background:#2b1e0e;border:1px solid #6b4f27;padding:1px 6px;font-size:11px;
}
#sel-info .hpbar{width:70px;height:7px;background:#191107;border:1px solid #6b4f27;position:relative;}
#sel-info .hpbar i{position:absolute;inset:0;width:100%;background:var(--ok);}
#sel-info .grouplist{display:flex;flex-wrap:wrap;gap:3px;margin-top:3px;max-height:44px;overflow:auto;}
#sel-info .gtag{font-size:10px;background:#3a2812;border:1px solid #6b4f27;padding:1px 5px;}

#order-buttons{
  display:grid;grid-template-columns:repeat(4,86px);grid-auto-rows:34px;gap:4px;
  align-content:start;max-height:76px;overflow-y:auto;padding-right:2px;flex:0 0 auto;
}
.obtn{
  font-family:var(--font-ui);font-size:10.5px;font-weight:800;letter-spacing:.06em;
  background:linear-gradient(180deg,#5a4222,#2b1e0e);border:1px solid #8a6a36;color:#f0d7a6;
  cursor:pointer;padding:0 2px;
}
.obtn:hover:not(:disabled){filter:brightness(1.25);}
.obtn.on{background:linear-gradient(180deg,#c98a25,#7a4f10);color:#1b1105;border-color:#f3c064;}
.obtn:disabled{opacity:.35;cursor:not-allowed;}
.obtn.danger{border-color:#c8352a;color:#ffb9ac;}

/* --------------------------- responsive squeeze -------------------------- */
@media (max-width:1080px){
  #screen-game.active{grid-template-columns:1fr 196px;}
  #minimap{width:176px;height:176px;}
  .radar-box{height:180px;flex-basis:180px;}
  #order-buttons{grid-template-columns:repeat(3,80px);}
  .readout.obj{display:none;}
}
@media (max-height:700px){
  .radar-box{height:150px;flex-basis:150px;}
  #minimap{width:146px;height:146px;}
}
"},{"path":"css/main.css","type":"text/css","text":"/* ==========================================================================
   Dune II - base layout, palette and shared chrome
   ========================================================================== */

:root{
  --sand-0:#0d0906;
  --sand-1:#1a1209;
  --sand-2:#2a1d0f;
  --sand-3:#3d2c17;
  --sand-4:#5a4222;
  --sand-5:#8a6a36;
  --sand-6:#b89552;
  --sand-7:#e2c184;
  --ink:#0a0705;
  --amber:#f0a92e;
  --amber-dim:#a97218;
  --spice:#d8621f;
  --danger:#c8352a;
  --ok:#5ec46a;
  --atreides:#3f6fd8;
  --harkonnen:#c0231c;
  --ordos:#22a377;
  --sardaukar:#8d49c9;
  --font-ui:"Trebuchet MS","Lucida Grande",Verdana,sans-serif;
  --font-mono:"Consolas","DejaVu Sans Mono","Courier New",monospace;
}

*{box-sizing:border-box;}
html,body{height:100%;margin:0;padding:0;}
body{
  background:#000;
  color:var(--sand-7);
  font-family:var(--font-ui);
  overflow:hidden;
  user-select:none;
  -webkit-user-select:none;
  -webkit-tap-highlight-color:transparent;
}

#app{position:fixed;inset:0;overflow:hidden;}

.screen{
  position:absolute;inset:0;
  display:none;
  background:
    radial-gradient(120% 90% at 50% 0%, #2a1c0e 0%, #140d06 55%, #070503 100%);
}
.screen.active{display:block;}

.dim{color:var(--sand-5);}
.hi{color:var(--amber);}
.bad{color:var(--danger);}
.good{color:var(--ok);}

/* ------------------------------- buttons -------------------------------- */
.dbtn{
  font-family:var(--font-ui);
  font-weight:700;
  letter-spacing:.09em;
  font-size:13px;
  color:var(--sand-7);
  background:linear-gradient(180deg,#6b4f27 0%,#432f16 55%,#2d1f0e 100%);
  border:2px solid;
  border-color:#a2793c #241809 #241809 #a2793c;
  padding:9px 18px;
  cursor:pointer;
  text-transform:uppercase;
  box-shadow:0 2px 0 #140d05, inset 0 1px 0 rgba(255,220,160,.18);
  transition:filter .08s linear, transform .05s linear;
}
.dbtn:hover:not(:disabled){filter:brightness(1.25);}
.dbtn:active:not(:disabled){transform:translateY(2px);box-shadow:0 0 0 #140d05;}
.dbtn:disabled{opacity:.42;cursor:not-allowed;filter:grayscale(.5);}
.dbtn.big{font-size:17px;padding:13px 34px;min-width:260px;}
.dbtn.tiny{font-size:10.5px;padding:5px 9px;letter-spacing:.05em;}
.dbtn.primary{
  background:linear-gradient(180deg,#c98a25 0%,#8d5c12 55%,#5c3c0b 100%);
  border-color:#f3c064 #3a2607 #3a2607 #f3c064;
  color:#1b1105;
}
.dbtn.danger{
  background:linear-gradient(180deg,#8f2a22 0%,#5d1a15 55%,#3a100d 100%);
  border-color:#d4675c #2a0b09 #2a0b09 #d4675c;
}

/* ------------------------------- panels --------------------------------- */
.panel{
  background:linear-gradient(180deg,rgba(45,31,15,.95),rgba(23,16,8,.96));
  border:2px solid;
  border-color:#7a5a2c #1a1108 #1a1108 #7a5a2c;
  box-shadow:inset 0 0 22px rgba(0,0,0,.65);
}

h1,h2,h3{margin:0;font-weight:800;letter-spacing:.1em;text-transform:uppercase;}

/* -------------------------------- scroll -------------------------------- */
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-track{background:#1a1108;}
::-webkit-scrollbar-thumb{background:#6b4f27;border:2px solid #1a1108;}
::-webkit-scrollbar-thumb:hover{background:#8a6a36;}

/* ------------------------------ help modal ------------------------------ */
#help-overlay{
  position:absolute;inset:0;display:none;z-index:400;
  background:rgba(4,3,1,.88);
  padding:28px;
  overflow:auto;
}
#help-overlay.show{display:block;}
.help-box{
  max-width:1020px;margin:0 auto;padding:22px 26px 26px;
  background:linear-gradient(180deg,#2d1f0f,#160f07);
  border:2px solid;border-color:#9a7336 #1a1108 #1a1108 #9a7336;
}
.help-box h2{color:var(--amber);margin-bottom:14px;font-size:22px;}
.help-cols{
  columns:2;column-gap:32px;
  font-size:13px;line-height:1.55;color:var(--sand-6);
  margin-bottom:18px;
}
.help-cols h4{
  color:var(--amber);margin:0 0 4px;font-size:13px;letter-spacing:.08em;
  break-after:avoid;
}
.help-cols section{break-inside:avoid;margin-bottom:14px;}
.help-cols b{color:var(--sand-7);}
.help-cols kbd{
  font-family:var(--font-mono);font-size:11px;
  background:#4a3419;border:1px solid #7a5a2c;padding:0 4px;border-radius:2px;
  color:var(--sand-7);
}

/* ------------------------------ utilities ------------------------------- */
canvas{display:block;image-rendering:auto;}
.kv{display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px dotted #4a3419;}
.kv span{color:var(--sand-5);letter-spacing:.06em;}
.kv b{color:var(--sand-7);}
"},{"path":"css/screens.css","type":"text/css","text":"/* ==========================================================================
   Dune II - front-end screens: title, house select, campaign map, mentat
   ========================================================================== */

/* -------------------------------- title --------------------------------- */
.starfield{
  position:absolute;inset:0;
  background:
    radial-gradient(1px 1px at 20% 30%, rgba(255,230,190,.8), transparent 60%),
    radial-gradient(1px 1px at 68% 18%, rgba(255,230,190,.6), transparent 60%),
    radial-gradient(1px 1px at 82% 62%, rgba(255,230,190,.5), transparent 60%),
    radial-gradient(1px 1px at 35% 74%, rgba(255,230,190,.45), transparent 60%),
    radial-gradient(2px 2px at 12% 58%, rgba(255,210,150,.35), transparent 60%),
    radial-gradient(140% 70% at 50% 120%, #7a4a18 0%, #2a1a0a 45%, transparent 70%);
  opacity:.9;
}
.menu-wrap{
  position:relative;z-index:2;
  height:100%;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:6px;
  text-align:center;
}
.game-title{
  font-size:clamp(56px,11vw,132px);
  line-height:.92;
  letter-spacing:.14em;
  color:var(--amber);
  text-shadow:0 0 24px rgba(240,169,46,.45), 0 6px 0 #57390d, 0 10px 26px #000;
}
.game-title .t2{color:var(--spice);margin-left:.12em;}
.game-sub{
  margin:2px 0 0;font-size:clamp(13px,2.1vw,22px);letter-spacing:.42em;
  color:var(--sand-6);text-transform:uppercase;
}
.game-tag{margin:18px 0 26px;font-style:italic;color:var(--sand-5);letter-spacing:.06em;}
.menu-buttons{display:flex;flex-direction:column;gap:12px;}
.menu-foot{position:absolute;bottom:14px;font-size:11px;color:#6b5330;letter-spacing:.05em;}

/* ----------------------------- house select ----------------------------- */
#screen-house{display:none;}
#screen-house.active{display:flex;flex-direction:column;padding:26px 30px;}
.hs-head{text-align:center;margin-bottom:18px;}
.hs-head h2{font-size:26px;color:var(--amber);letter-spacing:.2em;}
.hs-head p{max-width:760px;margin:10px auto 0;color:var(--sand-5);font-size:13px;line-height:1.6;}
.house-cards{
  flex:1;display:grid;grid-template-columns:repeat(3,1fr);gap:20px;
  min-height:0;
}
.hcard{
  position:relative;
  display:flex;flex-direction:column;
  background:linear-gradient(180deg,rgba(40,28,14,.95),rgba(16,11,6,.98));
  border:2px solid;border-color:#7a5a2c #1a1108 #1a1108 #7a5a2c;
  padding:16px;cursor:pointer;overflow:hidden;
  transition:transform .12s ease, box-shadow .12s ease;
}
.hcard:hover{transform:translateY(-4px);}
.hcard.sel{box-shadow:0 0 0 3px var(--amber), 0 0 30px rgba(240,169,46,.35);}
.hcard canvas{margin:0 auto 10px;}
.hcard h3{text-align:center;font-size:20px;letter-spacing:.16em;}
.hcard .motto{text-align:center;font-style:italic;color:var(--sand-5);font-size:12px;margin:4px 0 10px;}
.hcard p.desc{font-size:12.5px;line-height:1.6;color:var(--sand-6);margin:0 0 10px;}
.hcard .traits{margin-top:auto;font-size:11.5px;}
.hcard .traits div{display:flex;justify-content:space-between;padding:2px 0;border-bottom:1px dotted #43301a;}
.hcard .traits span{color:var(--sand-5);}
.hcard .uniq{margin-top:8px;font-size:11.5px;color:var(--amber);letter-spacing:.05em;}
.hs-foot{margin-top:16px;display:flex;justify-content:center;gap:12px;}

/* ----------------------------- campaign map ----------------------------- */
#screen-map{display:none;}
#screen-map.active{display:flex;flex-direction:column;padding:16px 20px;}
.cm-head{text-align:center;margin-bottom:10px;}
.cm-head h2{font-size:24px;color:var(--amber);letter-spacing:.3em;}
.cm-head p{margin:6px 0 0;color:var(--sand-5);font-size:12.5px;}
.cm-body{flex:1;display:flex;gap:16px;min-height:0;}
.cm-canvas-wrap{
  flex:1;display:flex;align-items:center;justify-content:center;
  background:#0b0703;border:2px solid;border-color:#7a5a2c #1a1108 #1a1108 #7a5a2c;
  overflow:hidden;
}
#campaign-canvas{max-width:100%;max-height:100%;cursor:crosshair;}
.cm-side{width:290px;display:flex;flex-direction:column;gap:12px;}
.cm-panel{
  background:linear-gradient(180deg,rgba(45,31,15,.95),rgba(23,16,8,.96));
  border:2px solid;border-color:#7a5a2c #1a1108 #1a1108 #7a5a2c;
  padding:12px 14px;
}
.cm-panel h3{font-size:14px;color:var(--amber);margin-bottom:8px;letter-spacing:.14em;}
.cm-terr-body{font-size:12.5px;line-height:1.6;color:var(--sand-6);min-height:180px;}
.cm-terr-body .tag{
  display:inline-block;padding:2px 7px;margin:0 6px 6px 0;font-size:10.5px;
  border:1px solid #7a5a2c;letter-spacing:.07em;text-transform:uppercase;
}
.cm-progress{font-size:12px;}
.cm-side .dbtn{width:100%;}

/* -------------------------------- mentat -------------------------------- */
#screen-mentat{display:none;}
#screen-mentat.active{display:flex;align-items:center;justify-content:center;padding:24px;}
.mentat-frame{
  display:flex;gap:26px;max-width:1080px;width:100%;
  background:linear-gradient(180deg,rgba(44,30,15,.96),rgba(18,12,6,.98));
  border:3px solid;border-color:#9a7336 #1a1108 #1a1108 #9a7336;
  padding:22px;
  box-shadow:0 0 60px rgba(0,0,0,.8), inset 0 0 40px rgba(0,0,0,.5);
}
.mentat-left{flex:0 0 320px;text-align:center;}
#mentat-canvas{
  border:2px solid #56401f;background:#120c06;
}
.mentat-name{
  margin-top:8px;font-weight:800;letter-spacing:.2em;color:var(--amber);font-size:14px;
}
.mentat-right{flex:1;display:flex;flex-direction:column;min-width:0;}
.mentat-right h2{font-size:20px;color:var(--amber);letter-spacing:.18em;margin-bottom:12px;}
.mentat-text{
  flex:1;font-family:var(--font-mono);font-size:14px;line-height:1.75;
  color:var(--sand-7);white-space:pre-wrap;min-height:230px;
  background:rgba(0,0,0,.28);border:1px solid #43301a;padding:14px 16px;
  overflow:auto;
}
.mentat-text .cursor{color:var(--amber);}
.mentat-obj{
  margin-top:12px;padding:10px 14px;border-left:4px solid var(--spice);
  background:rgba(216,98,31,.1);font-size:13px;line-height:1.6;
}
.mentat-obj b{color:var(--amber);letter-spacing:.1em;}
.mentat-buttons{margin-top:14px;display:flex;gap:10px;justify-content:flex-end;}

/* -------------------------------- result -------------------------------- */
#screen-result{display:none;}
#screen-result.active{display:flex;align-items:center;justify-content:center;}
.result-wrap{text-align:center;max-width:620px;padding:34px 40px;
  background:linear-gradient(180deg,rgba(44,30,15,.96),rgba(18,12,6,.98));
  border:3px solid;border-color:#9a7336 #1a1108 #1a1108 #9a7336;}
#res-title{font-size:34px;letter-spacing:.2em;color:var(--amber);}
#res-title.lose{color:var(--danger);}
#res-sub{color:var(--sand-6);margin:12px 0 18px;font-size:14px;line-height:1.6;}
.res-stats{display:grid;grid-template-columns:1fr 1fr;gap:4px 22px;margin-bottom:22px;text-align:left;}
.res-buttons{display:flex;flex-direction:column;gap:10px;align-items:center;}
"},{"path":"js/game.js","type":"text/javascript","text":"/* =============================================================================
   game.js - the world (one mission) and the campaign controller around it.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  var CELL = CFG.TILE * 4;

  /* ========================================================================
     WORLD - everything that exists during a mission
     ===================================================================== */
  function World(setup) {
    this.setup = setup;
    this.state = 'playing';
    this.time = 0;
    this.nextId = 1;
    this.byId = {};

    this.map = new DUNE.GameMap({
      seed: setup.seed,
      spice: setup.spice,
      rock: setup.rock,
      starts: 1 + setup.enemies.length
    });
    this.pathfinder = new DUNE.Pathfinder(this.map);
    this.effects = new DUNE.Effects(this);

    this.units = [];
    this.structures = [];
    this.projectiles = [];
    this.worms = [];
    this.factions = [];
    this.selection = [];
    this.groups = {};

    this.placement = null;
    this.orderMode = null;
    this.targetingSpecial = false;
    this.missionName = setup.name;

    this.stats = { wormKills: 0, unitsLost: 0, unitsKilled: 0, buildingsLost: 0, buildingsKilled: 0 };

    this.gw = Math.ceil(this.map.w * CFG.TILE / CELL);
    this.gh = Math.ceil(this.map.h * CFG.TILE / CELL);
    this.cells = new Array(this.gw * this.gh);
    for (var i = 0; i < this.cells.length; i++) this.cells[i] = [];
    this._queryStamp = 0;
    this._stamps = {};

    this.buildFactions();
    this.buildWorms();
  }

  /* ------------------------------- setup --------------------------------- */
  World.prototype.buildFactions = function () {
    var s = this.setup;
    var starts = this.map.starts;

    var player = new DUNE.Faction(this, {
      index: 0, house: s.house, isPlayer: true,
      credits: s.credits, tech: s.tech
    });
    this.factions.push(player);
    this.playerFaction = player;

    for (var i = 0; i < s.enemies.length; i++) {
      var f = new DUNE.Faction(this, {
        index: i + 1, house: s.enemies[i], isPlayer: false,
        credits: s.enemyCredits, tech: s.tech
      });
      f.ai = new DUNE.AI(this, f, {
        aggr: s.aiAggr, eco: s.aiEco, seed: s.seed + i * 977
      });
      this.factions.push(f);
    }
    // Nobody on Arrakis has friends. Rival Houses fight each other as readily
    // as they fight you, which is what keeps a three-way map survivable.

    this.playerFog = new DUNE.Fog(this.map, s.fog !== false);

    // --- bases -----------------------------------------------------------
    this.foundBase(player, starts[0], s.playerBase);
    for (var e = 0; e < s.enemies.length; e++) {
      if (!starts[e + 1]) continue;
      this.foundBase(this.factions[e + 1], starts[e + 1], s.enemyBase);
    }

    // starting escort
    this.spawnSquad(player, starts[0], s.playerUnits);
    for (var k = 0; k < s.enemies.length; k++) {
      if (!starts[k + 1]) continue;
      this.spawnSquad(this.factions[k + 1], starts[k + 1], s.enemyUnits);
    }

    this.playerFog.reveal(starts[0].x, starts[0].y, 11);
    player.recount();
  };

  /** Pours a concrete pad and raises the starting buildings. */
  World.prototype.foundBase = function (faction, start, plan) {
    var map = this.map;
    var self = this;
    if (!plan || !plan.length) return;      // a patrol, not a base
    // pad
    for (var y = start.y - 3; y <= start.y + 3; y++) {
      for (var x = start.x - 3; x <= start.x + 3; x++) {
        if (!map.inBounds(x, y)) continue;
        if (U.dist(x, y, start.x, start.y) <= 3.2) map.setConcrete(x, y, faction.index + 1);
      }
    }
    var placed = [];
    function put(id, dx, dy) {
      var def = DUNE.STRUCTS[id];
      var tx = start.x + dx, ty = start.y + dy;
      for (var yy = 0; yy < def.h; yy++) {
        for (var xx = 0; xx < def.w; xx++) {
          if (!map.inBounds(tx + xx, ty + yy)) return null;
          map.setConcrete(tx + xx, ty + yy, faction.index + 1);
          if (map.terrainAt(tx + xx, ty + yy) === DUNE.T.MOUNTAIN) {
            map.setTerrain(tx + xx, ty + yy, DUNE.T.ROCK);
          }
        }
      }
      var res = DUNE.Structure.checkPlacement(self, id, faction, tx, ty);
      if (!res.ok && res.reason !== 'Must adjoin your base') return null;
      var s = self.createStructure(id, faction, tx, ty);
      if (s) { s.building = false; s.riseT = s.riseTime; placed.push(s); }
      return s;
    }

    var layout = [
      ['construction', -1, -1],
      ['windtrap', 1, -1],
      ['refinery', -2, 1],
      ['lightfactory', 1, 1],
      ['heavyfactory', -2, 3],
      ['radar', 1, 3],
      ['turret', 3, 0],
      ['turret', -3, 0]
    ];
    var made = 0;
    for (var i = 0; i < layout.length && made < plan.length; i++) {
      var want = plan[made];
      if (layout[i][0] !== want) continue;
      if (put(layout[i][0], layout[i][1], layout[i][2])) made++;
    }
    // anything in the plan that had no slot in the layout
    for (var j = made; j < plan.length; j++) {
      var spot = this.findNearbyBuildSite(faction, plan[j], start);
      if (spot) {
        var def2 = DUNE.STRUCTS[plan[j]];
        for (var yy2 = 0; yy2 < def2.h; yy2++) {
          for (var xx2 = 0; xx2 < def2.w; xx2++) map.setConcrete(spot.x + xx2, spot.y + yy2, faction.index + 1);
        }
        var st = this.createStructure(plan[j], faction, spot.x, spot.y);
        if (st) { st.building = false; st.riseT = st.riseTime; }
      }
    }

    // a refinery always arrives with its harvester
    var refs = faction.structures.filter(function (s2) { return s2.def.id === 'refinery'; });
    for (var r = 0; r < refs.length; r++) {
      var exit = refs[r].exitTile();
      if (exit) {
        var h = this.createUnit('harvester', faction, exit.x, exit.y);
        if (h) h.hstate = 'idle';
      }
    }
    faction.recount();
  };

  World.prototype.findNearbyBuildSite = function (faction, defId, start) {
    var self = this;
    return this.map.spiral(start.x, start.y, 10, function (x, y) {
      var res = DUNE.Structure.checkPlacement(self, defId, faction, x, y);
      return (res.ok || res.reason === 'Must adjoin your base') ? { x: x, y: y } : null;
    });
  };

  World.prototype.spawnSquad = function (faction, start, list) {
    for (var i = 0; i < list.length; i++) {
      var id = list[i];
      if (!DUNE.houseAllowsUnit(DUNE.UNITS[id], faction.houseId)) {
        id = faction.houseId === 'harkonnen' ? 'quad' : (faction.houseId === 'ordos' ? 'raider' : 'trike');
      }
      var spot = this.map.findFreeTile(
        start.x + Math.round((Math.random() - 0.5) * 8),
        start.y + Math.round((Math.random() - 0.5) * 8),
        DUNE.UNITS[id].move, 9, -1);
      if (spot) this.createUnit(id, faction, spot.x, spot.y);
    }
  };

  World.prototype.buildWorms = function () {
    var map = this.map;
    var open = 0;
    for (var i = 0; i < map.n; i++) if (DUNE.isOpenSand(map.terrain[i])) open++;
    var frac = open / map.n;
    var count = U.clamp(Math.round(frac * 6), 1, 4) + (this.setup.extraWorms || 0);
    var rnd = U.rng(this.setup.seed ^ 0x7777);
    for (var w = 0; w < count; w++) {
      for (var tries = 0; tries < 200; tries++) {
        var tx = Math.floor(rnd() * map.w), ty = Math.floor(rnd() * map.h);
        if (!DUNE.isOpenSand(map.terrainAt(tx, ty))) continue;
        var far = true;
        for (var s = 0; s < map.starts.length; s++) {
          if (U.dist(tx, ty, map.starts[s].x, map.starts[s].y) < 14) { far = false; break; }
        }
        if (!far) continue;
        this.worms.push(new DUNE.Worm(this, tx, ty, (rnd() * 1e9) | 0));
        break;
      }
    }
  };

  /* --------------------------- entity factory ----------------------------- */
  World.prototype.createUnit = function (defId, faction, tx, ty) {
    if (!DUNE.UNITS[defId]) return null;
    var map = this.map;
    if (!map.inBounds(tx, ty)) return null;
    if (DUNE.UNITS[defId].move !== 'air' && !map.stepFree(tx, ty, DUNE.UNITS[defId].move, -1)) {
      var free = map.findFreeTile(tx, ty, DUNE.UNITS[defId].move, 8, -1);
      if (!free) return null;
      tx = free.x; ty = free.y;
    }
    var u = new DUNE.Unit(this, defId, faction, tx, ty);
    this.units.push(u);
    this.byId[u.id] = u;
    faction.addUnit(u);
    return u;
  };

  World.prototype.createStructure = function (defId, faction, tx, ty) {
    var s = new DUNE.Structure(this, defId, faction, tx, ty);
    this.structures.push(s);
    this.byId[s.id] = s;
    faction.addStructure(s);
    // shove any unit standing on the footprint out of the way
    for (var y = 0; y < s.h; y++) {
      for (var x = 0; x < s.w; x++) {
        var occ = this.map.unit[(ty + y) * this.map.w + (tx + x)];
        if (occ && this.byId[occ]) {
          var u = this.byId[occ];
          u.releaseAll();
          var free = this.map.findFreeTile(tx + x, ty + y, u.def.move, 8, u.id);
          if (free) {
            u.tx = free.x; u.ty = free.y;
            u.x = this.map.cx(free.x); u.y = this.map.cy(free.y);
            u.claim(free.x, free.y);
            u.stopMoving();
          }
        }
      }
    }
    return s;
  };

  /** Player/AI placement entry point: handles concrete slabs too. */
  World.prototype.placeStructure = function (defId, faction, tx, ty) {
    var def = DUNE.STRUCTS[defId];
    var res = DUNE.Structure.checkPlacement(this, defId, faction, tx, ty);
    if (!res.ok) return null;

    if (def.foundation) {
      for (var i = 0; i < res.tiles.length; i++) {
        this.map.setConcrete(res.tiles[i][0], res.tiles[i][1], faction.index + 1);
      }
      // buildings already standing on those tiles stop rotting
      for (var s = 0; s < faction.structures.length; s++) faction.structures[s].recountConcrete();
      DUNE.Sfx.play('place', 0.8, this.audioDist(this.map.cx(tx), this.map.cy(ty)));
      this.effects.dust(this.map.cx(tx), this.map.cy(ty), 6);
      return true;
    }

    var st = this.createStructure(defId, faction, tx, ty);
    if (st) {
      DUNE.Sfx.play('place', 1, this.audioDist(st.x, st.y));
      this.effects.sandBurst(st.x, st.y, 12);
      // a Refinery always arrives with a Harvester aboard
      if (def.freeUnit) {
        var spot = st.exitTile();
        if (spot) {
          var fu = this.createUnit(def.freeUnit, faction, spot.x, spot.y);
          if (fu) {
            fu.hstate = 'idle';
            if (faction.isPlayer) this.notify('Harvester delivered', 'good');
          }
        }
      }
    }
    return st;
  };

  /** Called by the sidebar when the player clicks the map in placement mode. */
  World.prototype.tryPlace = function (tileX, tileY) {
    if (!this.placement) return;
    var f = this.playerFaction;
    var defId = this.placement.defId;
    var def = DUNE.STRUCTS[defId];
    var tx = U.clamp(tileX - ((def.w / 2) | 0), 0, this.map.w - def.w);
    var ty = U.clamp(tileY - ((def.h / 2) | 0), 0, this.map.h - def.h);

    var res = DUNE.Structure.checkPlacement(this, defId, f, tx, ty);
    if (!res.ok) {
      this.notify('Cannot build here: ' + res.reason, 'bad', 'cantbuild');
      DUNE.Sfx.play('deny', 0.8);
      return;
    }

    var q = f.queue('structure');
    var head = q.items.length ? q.items[0] : null;
    if (!head || head.id !== defId || head.state !== 'ready') {
      this.notify('That structure is not ready yet', 'bad');
      DUNE.Sfx.play('deny', 0.8);
      return;
    }

    var out = this.placeStructure(defId, f, tx, ty);
    if (!out) return;
    U.remove(q.items, head);

    if (out !== true && res.concrete < res.total) {
      this.notify('Founded on open sand — it will decay until you slab it', 'bad');
    }
    DUNE.UI.Sidebar.cancelPlacement();
    DUNE.UI.Sidebar.rebuild();
  };

  World.prototype.spawnProjectile = function (o) {
    var p = new DUNE.Projectile(o);
    this.projectiles.push(p);
    return p;
  };

  World.prototype.areaDamage = function (x, y, r, dmg, warhead, source) {
    var list = this.entitiesInRadius(x, y, r);
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (e === source) continue;
      var f = U.clamp(1 - U.dist(x, y, e.x, e.y) / r, 0.1, 1);
      DUNE.Combat.applyDamage(e, dmg * f, warhead, source, this);
    }
  };

  /* --------------------------- entity removal ----------------------------- */
  World.prototype.onUnitDestroyed = function (u, cause) {
    U.remove(this.units, u);
    delete this.byId[u.id];
    if (u.faction) u.faction.removeUnit(u);
    if (u.homeFaction && u.homeFaction !== u.faction) u.homeFaction.removeUnit(u);
    U.remove(this.selection, u);
    for (var g in this.groups) U.remove(this.groups[g], u);
    if (cause === 'deployed') return;
    if (u.faction === this.playerFaction) {
      this.stats.unitsLost++;
      this.playerFaction.stats.lost++;
    } else {
      this.stats.unitsKilled++;
    }
  };

  World.prototype.onStructureDestroyed = function (s, cause) {
    U.remove(this.structures, s);
    delete this.byId[s.id];
    if (s.faction) s.faction.removeStructure(s);
    U.remove(this.selection, s);
    if (s.faction === this.playerFaction) {
      this.stats.buildingsLost++;
      if (cause !== 'sold') this.notify(s.def.name + ' destroyed!', 'bad');
    } else {
      this.stats.buildingsKilled++;
    }
    if (this.placement && s.faction === this.playerFaction) DUNE.UI.Sidebar.rebuild();
  };

  World.prototype.changeUnitFaction = function (u, toFaction) {
    if (u.faction === toFaction) return;
    u.faction.removeUnit(u);
    u.faction = toFaction;
    toFaction.addUnit(u);
    u.target = null;
  };

  /* --------------------------- spatial queries ---------------------------- */
  World.prototype.rebuildGrid = function () {
    var i;
    for (i = 0; i < this.cells.length; i++) this.cells[i].length = 0;
    for (i = 0; i < this.units.length; i++) {
      var u = this.units[i];
      if (!u.alive || u.hidden || u.carriedBy) continue;
      this.insertCell(u, u.x, u.y, u.x, u.y);
    }
    for (i = 0; i < this.structures.length; i++) {
      var s = this.structures[i];
      if (!s.alive) continue;
      this.insertCell(s, s.tx * CFG.TILE, s.ty * CFG.TILE,
                      (s.tx + s.w) * CFG.TILE, (s.ty + s.h) * CFG.TILE);
    }
  };

  World.prototype.insertCell = function (e, x0, y0, x1, y1) {
    var cx0 = U.clamp(Math.floor(x0 / CELL), 0, this.gw - 1);
    var cy0 = U.clamp(Math.floor(y0 / CELL), 0, this.gh - 1);
    var cx1 = U.clamp(Math.floor(x1 / CELL), 0, this.gw - 1);
    var cy1 = U.clamp(Math.floor(y1 / CELL), 0, this.gh - 1);
    for (var cy = cy0; cy <= cy1; cy++) {
      for (var cx = cx0; cx <= cx1; cx++) this.cells[cy * this.gw + cx].push(e);
    }
  };

  World.prototype.entitiesInRadius = function (x, y, r) {
    var out = [];
    var stamp = ++this._queryStamp;
    var cx0 = U.clamp(Math.floor((x - r) / CELL), 0, this.gw - 1);
    var cy0 = U.clamp(Math.floor((y - r) / CELL), 0, this.gh - 1);
    var cx1 = U.clamp(Math.floor((x + r) / CELL), 0, this.gw - 1);
    var cy1 = U.clamp(Math.floor((y + r) / CELL), 0, this.gh - 1);
    var r2 = r * r;
    for (var cy = cy0; cy <= cy1; cy++) {
      for (var cx = cx0; cx <= cx1; cx++) {
        var list = this.cells[cy * this.gw + cx];
        for (var i = 0; i < list.length; i++) {
          var e = list[i];
          if (e._qs === stamp) continue;
          e._qs = stamp;
          if (!e.alive) continue;
          var dx, dy;
          if (e.kind === 'structure') {
            var ex = U.clamp(x, e.tx * CFG.TILE, (e.tx + e.w) * CFG.TILE);
            var ey = U.clamp(y, e.ty * CFG.TILE, (e.ty + e.h) * CFG.TILE);
            dx = x - ex; dy = y - ey;
          } else {
            dx = x - e.x; dy = y - e.y;
          }
          if (dx * dx + dy * dy <= r2) out.push(e);
        }
      }
    }
    return out;
  };

  World.prototype.unitsInRadius = function (x, y, r) {
    return this.entitiesInRadius(x, y, r).filter(function (e) { return e.kind === 'unit'; });
  };

  World.prototype.entityAt = function (wx, wy) {
    var tx = Math.floor(wx / CFG.TILE), ty = Math.floor(wy / CFG.TILE);
    // units first - they sit on top
    var near = this.entitiesInRadius(wx, wy, CFG.TILE * 0.75);
    var bestU = null, bestD = Infinity;
    for (var i = 0; i < near.length; i++) {
      var e = near[i];
      if (e.kind !== 'unit' || e.hidden || e.carriedBy) continue;
      if (this.playerFog && this.playerFog.enabled && !e.faction.isPlayer &&
          !this.playerFog.isVisible(e.tx, e.ty)) continue;
      var d = U.dist2(wx, wy, e.x, e.y);
      if (d < bestD) { bestD = d; bestU = e; }
    }
    if (bestU) return bestU;
    return this.entityAtTile(tx, ty);
  };

  World.prototype.entityAtTile = function (tx, ty) {
    if (!this.map.inBounds(tx, ty)) return null;
    var bid = this.map.building[ty * this.map.w + tx];
    if (bid && this.byId[bid]) {
      var s = this.byId[bid];
      if (this.playerFog && this.playerFog.enabled && !this.playerFog.isExplored(tx, ty)) return null;
      return s;
    }
    var uid = this.map.unit[ty * this.map.w + tx];
    if (uid && this.byId[uid]) {
      var u = this.byId[uid];
      if (u.hidden) return null;
      if (this.playerFog && this.playerFog.enabled && !u.faction.isPlayer &&
          !this.playerFog.isVisible(tx, ty)) return null;
      return u;
    }
    return null;
  };

  World.prototype.nearestEnemyBase = function (faction) {
    var best = null, bestD = Infinity;
    var c = faction.baseCentre();
    if (!c) return null;
    var cx = c.x * CFG.TILE, cy = c.y * CFG.TILE;
    for (var i = 0; i < this.structures.length; i++) {
      var s = this.structures[i];
      if (!s.alive || s.faction === faction || !faction.isEnemyOf(s.faction)) continue;
      var d = U.dist2(cx, cy, s.x, s.y);
      if (d < bestD) { bestD = d; best = s; }
    }
    return best;
  };

  /* ------------------------------ selection ------------------------------- */
  World.prototype.setSelection = function (list) {
    for (var i = 0; i < this.selection.length; i++) this.selection[i].selected = false;
    this.selection = list.slice(0, 60);
    for (var j = 0; j < this.selection.length; j++) this.selection[j].selected = true;
    this.orderMode = null;
    DUNE.UI.Hud.refresh();
  };
  World.prototype.select = function (e, add) {
    if (!add) return this.setSelection([e]);
    if (this.selection.indexOf(e) < 0) { this.selection.push(e); e.selected = true; }
    DUNE.UI.Hud.refresh();
  };
  World.prototype.deselect = function (e) {
    U.remove(this.selection, e);
    e.selected = false;
    DUNE.UI.Hud.refresh();
  };
  World.prototype.clearSelection = function () { this.setSelection([]); };

  /* ------------------------------ feedback -------------------------------- */
  World.prototype.notify = function (msg, type, key) {
    if (DUNE.UI.Hud) DUNE.UI.Hud.notify(msg, type, key);
  };
  World.prototype.audioDist = function (x, y) {
    if (!this.renderer) return 0;
    var v = this.renderer.viewRect();
    var cx = v.x + v.w / 2, cy = v.y + v.h / 2;
    var d = U.dist(x, y, cx, cy);
    return U.clamp(d / (Math.max(v.w, v.h) * 1.1), 0, 1);
  };
  World.prototype.flashOnMinimap = function (x, y) {
    if (this.minimap) this.minimap.flash(x, y);
  };
  World.prototype.onEnemyWave = function (faction, size) {
    this.notify('Enemy strike force inbound (' + size + ' units)', 'bad');
    DUNE.Sfx.play('alarm', 1);
  };

  /* --------------------------- palace weapons ----------------------------- */
  World.prototype.fireSpecial = function (faction, id, tx, ty) {
    var palace = faction.nearestStructure('palace', 0, 0);
    if (!palace) return false;

    if (id === 'fremen') {
      if (tx == null) return false;
      var made = 0;
      for (var i = 0; i < 3; i++) {
        var spot = this.map.findFreeTile(tx + (i - 1), ty, 'foot', 6, -1);
        if (!spot) continue;
        var u = this.createUnit('fremen', faction, spot.x, spot.y);
        if (u) {
          u.setOrder({ t: 'amove', x: tx, y: ty });
          this.effects.sandBurst(u.x, u.y, 14);
          made++;
        }
      }
      if (made) {
        this.notify('Fremen have joined the battle', 'good');
        DUNE.Sfx.play('deploy', 1);
      }
      return made > 0;
    }

    if (id === 'saboteur') {
      var exit = palace.exitTile();
      if (!exit) return false;
      var sab = this.createUnit('saboteur', faction, exit.x, exit.y);
      if (!sab) return false;
      sab.setOrder({ t: 'sabotage', target: null });
      this.notify('Saboteur deployed', 'good');
      DUNE.Sfx.play('deploy', 0.9);
      return true;
    }

    if (id === 'deathhand') {
      if (tx == null) return false;
      this.spawnProjectile({
        world: this, x: palace.x, y: palace.y - 10,
        tx: this.map.cx(tx), ty: this.map.cy(ty),
        weapon: DUNE.WEAPONS.deathhand, owner: palace, faction: faction,
        dmg: DUNE.WEAPONS.deathhand.dmg
      });
      this.notify('DEATH HAND LAUNCHED', 'bad');
      DUNE.Sfx.play('rocket', 1);
      return true;
    }
    return false;
  };

  /* ------------------------------- update --------------------------------- */
  World.prototype.update = function (dt) {
    this.time += dt;
    this.pathfinder.beginFrame();
    this.rebuildGrid();

    var i;
    for (i = 0; i < this.factions.length; i++) {
      var f = this.factions[i];
      f.update(dt);
      if (f.ai) f.ai.update(dt);
    }

    for (i = this.units.length - 1; i >= 0; i--) {
      var u = this.units[i];
      if (u.alive) u.update(dt);
    }
    for (i = this.structures.length - 1; i >= 0; i--) {
      var s = this.structures[i];
      if (s.alive) s.update(dt);
    }
    for (i = this.projectiles.length - 1; i >= 0; i--) {
      var p = this.projectiles[i];
      p.update(dt);
      if (!p.alive) this.projectiles.splice(i, 1);
    }
    for (i = 0; i < this.worms.length; i++) this.worms[i].update(dt);

    this.map.updateSpice(dt);
    this.effects.update(dt);
    this.playerFog.update(dt, this.playerFaction);

    this.checkObjectives(dt);
  };

  /* ------------------------------ objectives ------------------------------ */
  World.prototype.objectiveText = function () {
    var s = this.setup;
    if (s.objective === 'harvest') {
      return 'Harvest ' + s.amount + ' spice — ' +
             Math.floor(this.playerFaction.spiceHarvested) + '/' + s.amount;
    }
    var left = 0;
    for (var i = 1; i < this.factions.length; i++) {
      if (!this.factions[i].defeated) left += this.factions[i].structures.length;
    }
    return 'Destroy all enemy structures — ' + left + ' remaining';
  };

  World.prototype.checkObjectives = function (dt) {
    if (this.state !== 'playing') return;
    this._objT = (this._objT || 0) - dt;
    if (this._objT > 0) return;
    this._objT = 0.5;

    var i, f;
    for (i = 1; i < this.factions.length; i++) {
      f = this.factions[i];
      if (!f.defeated && f.isEliminated()) {
        f.defeated = true;
        this.notify(f.house.name + ' has been wiped out', 'good');
      }
    }

    // defeat: nothing left to build with
    var p = this.playerFaction;
    var hasBuildings = p.structures.some(function (s) { return s.alive; });
    var hasMcv = p.units.some(function (u) { return u.alive && u.def.deploy; });
    if (!hasBuildings && !hasMcv) {
      this.finish(false);
      return;
    }

    if (this.setup.objective === 'harvest') {
      if (p.spiceHarvested >= this.setup.amount) { this.finish(true); return; }
    } else {
      var alive = false;
      for (i = 1; i < this.factions.length; i++) {
        if (!this.factions[i].defeated) { alive = true; break; }
      }
      if (!alive) { this.finish(true); return; }
    }
  };

  World.prototype.finish = function (won) {
    if (this.state !== 'playing') return;
    this.state = won ? 'won' : 'lost';
    DUNE.Game.endMission(won);
  };

  World.prototype.togglePause = function () {
    if (this.state === 'playing') {
      this.state = 'paused';
      U.$('#pause-veil').classList.add('show');
    } else if (this.state === 'paused') {
      this.state = 'playing';
      U.$('#pause-veil').classList.remove('show');
    }
  };

  DUNE.World = World;

  /* ========================================================================
     GAME - screens, campaign state, main loop
     ===================================================================== */
  var Game = DUNE.Game = {
    world: null,
    campaign: null,
    raf: 0,
    lastTs: 0,

    /* ------------------------------ screens ------------------------------ */
    showScreen: function (id) {
      U.$$('.screen').forEach(function (s) { s.classList.remove('active'); });
      var el = U.$('#' + id);
      if (el) el.classList.add('active');
      Game.screen = id;
    },

    /* ----------------------------- campaign ------------------------------ */
    newCampaign: function (houseId) {
      Game.campaign = {
        house: houseId,
        mission: 1,
        owned: [],
        holders: {},
        history: []
      };
      // seed a few rival-held territories for flavour
      var rivals = DUNE.rivals(houseId);
      var rnd = U.rng(U.stringSeed(houseId + 'start'));
      DUNE.CAMPAIGN.TERRITORIES.forEach(function (t) {
        if (rnd() < 0.35) Game.campaign.holders[t.id] = rivals[Math.floor(rnd() * rivals.length)];
      });
      Game.save();
      Game.toMap();
    },

    loadCampaign: function () {
      var s = U.load();
      if (!s || !s.campaign) return false;
      Game.campaign = s.campaign;
      return true;
    },

    save: function () {
      U.save({ campaign: Game.campaign, v: 1 });
    },

    toMap: function () {
      DUNE.Sfx.stopAmbient();
      Game.showScreen('screen-map');
      DUNE.UI.CampaignMap.show(Game.campaign, function (terr) {
        Game.chosen = terr;
        Game.toBriefing(terr);
      });
    },

    toBriefing: function (terr) {
      var c = Game.campaign;
      var enemies = DUNE.CAMPAIGN.enemiesFor(c.mission, terr.id, c.house);
      Game.pendingEnemies = enemies;
      var brief = DUNE.CAMPAIGN.brief(c.house, c.mission, terr.id, enemies);
      U.$('#mentat-proceed').textContent = 'PROCEED';
      Game.showScreen('screen-mentat');
      DUNE.UI.Mentat.show(brief, function () {
        Game.startMission(terr, enemies);
      });
    },

    /* ----------------------------- missions ------------------------------ */
    startMission: function (terr, enemies) {
      var c = Game.campaign;
      var m = DUNE.CAMPAIGN.mission(c.mission);
      var seed = U.stringSeed(terr.id + c.house + c.mission) >>> 0;

      // You always start from a Construction Yard; as the campaign goes on the
      // Guild drops a little more of your base in with you, because the
      // opposition gets a lot bigger.
      var playerBase = ['construction'];
      if (c.mission >= 2) playerBase.push('windtrap');
      if (c.mission >= 4) playerBase.push('refinery');
      if (c.mission >= 6) playerBase.push('lightfactory');
      if (c.mission >= 8) playerBase.push('radar', 'turret');

      var enemyBase = m.skirmish ? [] : ['construction', 'windtrap', 'refinery'];
      if (!m.skirmish) {
        if (c.mission >= 2) { enemyBase.push('lightfactory'); }
        if (c.mission >= 3) { enemyBase.push('radar'); enemyBase.push('turret'); }
        if (c.mission >= 5) { enemyBase.push('heavyfactory'); enemyBase.push('turret'); }
      }

      var playerUnits = [];
      if (c.mission >= 2) playerUnits = ['trike', 'trike', 'quad'];
      if (c.mission >= 4) playerUnits.push('tank');
      if (c.mission >= 6) playerUnits.push('tank', 'quad');

      var enemyUnits = [];
      if (m.skirmish) {
        enemyUnits = ['trike', 'trike', 'quad'];
      } else {
        var eu = Math.min(7, 1 + c.mission);
        for (var i = 0; i < eu; i++) enemyUnits.push(i % 3 === 0 ? 'quad' : 'trike');
        if (c.mission >= 4) enemyUnits.push('tank');
        if (c.mission >= 6) enemyUnits.push('tank', 'tank');
      }

      var setup = {
        name: 'MISSION ' + c.mission + ' — ' + terr.name.toUpperCase(),
        seed: seed,
        house: c.house,
        enemies: enemies,
        tech: m.tech,
        credits: m.credits + (terr.spice - 2) * 150,
        enemyCredits: 1500 + c.mission * 260,
        spice: terr.spice,
        rock: terr.rock,
        objective: m.objective,
        amount: m.amount,
        aiAggr: m.aiAggr * (0.85 + terr.risk * 0.12),
        aiEco: m.aiEco,
        playerBase: playerBase,
        enemyBase: enemyBase,
        playerUnits: playerUnits,
        enemyUnits: enemyUnits,
        extraWorms: terr.rock <= 1 ? 2 : 0,
        fog: true
      };

      Game.world = new World(setup);
      var w = Game.world;
      w.renderer = new DUNE.Renderer(U.$('#game-canvas'), w);
      w.minimap = new DUNE.Minimap(U.$('#minimap'), w);

      Game.showScreen('screen-game');
      w.renderer.resize();
      var start = w.map.starts[0];
      w.renderer.centreOn(w.map.cx(start.x), w.map.cy(start.y));

      DUNE.UI.Hud.init(w);
      DUNE.UI.Sidebar.init(w);
      DUNE.UI.Input.init(w);
      U.$('#pause-veil').classList.remove('show');
      U.$('#radar-off').classList.remove('hide');

      DUNE.Sfx.init();
      DUNE.Sfx.startAmbient();
      w.notify('Mission begins. Build your base.', 'good');
      Game.startLoop();
    },

    retry: function () {
      if (!Game.chosen) return Game.toMap();
      Game.toBriefing(Game.chosen);
    },

    abort: function () {
      if (!Game.world) return;
      Game.world.state = 'aborted';
      Game.stopLoop();
      DUNE.Sfx.stopAmbient();
      Game.toMap();
    },

    endMission: function (won) {
      Game.stopLoop();
      DUNE.Sfx.stopAmbient();
      DUNE.Sfx.play(won ? 'victory' : 'defeat', 1);
      var c = Game.campaign, w = Game.world;

      if (won) {
        if (c.owned.indexOf(Game.chosen.id) < 0) c.owned.push(Game.chosen.id);
        delete c.holders[Game.chosen.id];
        c.mission = Math.min(DUNE.CAMPAIGN.count + 1, c.mission + 1);
        Game.save();
      }

      var final = won && c.mission > DUNE.CAMPAIGN.count;
      var title = U.$('#res-title');
      title.textContent = final ? 'ARRAKIS IS YOURS' : (won ? 'MISSION COMPLETE' : 'MISSION FAILED');
      title.className = won ? '' : 'lose';
      U.$('#res-sub').textContent = DUNE.CAMPAIGN.debrief(c.house, won, c.mission);

      var st = w.stats, pf = w.playerFaction;
      var rows = [
        ['Spice harvested', Math.round(pf.spiceHarvested)],
        ['Spice lost to overflow', Math.round(pf.spiceLost)],
        ['Units built', pf.stats.built],
        ['Units lost', st.unitsLost],
        ['Enemy units destroyed', st.unitsKilled],
        ['Enemy buildings destroyed', st.buildingsKilled],
        ['Buildings lost', st.buildingsLost],
        ['Swallowed by Shai-Hulud', st.wormKills],
        ['Map explored', Math.round(w.playerFog.exploredFraction() * 100) + '%'],
        ['Mission time', U.mmss(w.time)]
      ];
      var html = '';
      rows.forEach(function (r) {
        html += '<div class="kv"><span>' + r[0] + '</span><b>' + r[1] + '</b></div>';
      });
      U.$('#res-stats').innerHTML = html;

      U.$('#res-continue').textContent = final ? 'RETURN TO TITLE' : (won ? 'CONTINUE CAMPAIGN' : 'BACK TO MAP');
      U.$('#res-retry').style.display = won ? 'none' : '';
      Game.finalWin = final;
      Game.showScreen('screen-result');
    },

    /* ------------------------------- loop -------------------------------- */
    startLoop: function () {
      Game.stopLoop();
      Game.lastTs = 0;
      Game.raf = requestAnimationFrame(Game.frame);
    },
    stopLoop: function () {
      if (Game.raf) cancelAnimationFrame(Game.raf);
      Game.raf = 0;
    },

    frame: function (ts) {
      Game.raf = requestAnimationFrame(Game.frame);
      var w = Game.world;
      if (!w) return;
      if (!Game.lastTs) Game.lastTs = ts;
      var dt = Math.min(CFG.MAX_DT, (ts - Game.lastTs) / 1000);
      Game.lastTs = ts;

      DUNE.UI.Input.update(dt);

      if (w.state === 'playing') w.update(dt);
      else if (w.state === 'paused') w.effects.update(dt * 0.2);

      w.renderer.draw(dt);
      w.minimap.draw(dt);
      U.$('#radar-off').classList.toggle('hide', w.minimap.online);
      DUNE.UI.Hud.update(dt);
      DUNE.UI.Sidebar.update(dt);
    }
  };
})();
"},{"path":"js/main.js","type":"text/javascript","text":"/* =============================================================================
   main.js - bootstrap: title screen, House selection, field manual, and the
   wiring between the front-end screens and the campaign controller.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE;
  var U = DUNE.util;
  var Game = DUNE.Game;

  var selectedHouse = null;

  /* ---------------------------- house select ----------------------------- */
  function buildHouseCards() {
    var wrap = U.$('#house-cards');
    wrap.innerHTML = '';
    DUNE.PLAYABLE_HOUSES.forEach(function (id) {
      var h = DUNE.HOUSES[id];
      var card = U.el('div', 'hcard');
      card.style.borderColor = h.colour;

      var cv = document.createElement('canvas');
      cv.width = 96; cv.height = 96;
      DUNE.Sprites.crest(cv.getContext('2d'), id, 96);
      card.appendChild(cv);

      var title = U.el('h3', null, h.full);
      title.style.color = h.colourLight;
      card.appendChild(title);
      card.appendChild(U.el('div', 'motto', '“' + h.motto + '”'));
      card.appendChild(U.el('p', 'desc', h.desc));

      var traits = U.el('div', 'traits');
      h.traits.forEach(function (t) {
        var row = U.el('div');
        row.appendChild(U.el('span', null, t[0]));
        row.appendChild(U.el('b', null, t[1]));
        traits.appendChild(row);
      });
      card.appendChild(traits);
      card.appendChild(U.el('div', 'uniq', 'UNIQUE: ' + h.unique.join(' · ')));

      card.addEventListener('click', function () {
        U.$$('.hcard').forEach(function (c) { c.classList.remove('sel'); });
        card.classList.add('sel');
        selectedHouse = id;
        DUNE.Sfx.play('select', 1);
        setTimeout(function () { Game.newCampaign(id); }, 220);
      });
      wrap.appendChild(card);
    });
  }

  /* ------------------------------ field manual ---------------------------- */
  var MANUAL = [
    ['The spice must flow',
     'Everything is paid for with spice. A <b>Harvester</b> drives to a spice field, fills its ' +
     'hopper, drives back and docks at a <b>Refinery</b>, and only then does the load become ' +
     'credits. Lose your harvesters and your economy stops dead — they are the single most ' +
     'important thing you own.'],
    ['Storage',
     'Your Construction Yard bunkers 2500 units of spice, a Refinery adds 1000 and each <b>Silo</b> ' +
     'another 1000. Harvest past your storage and the surplus blows away. Watch the SPICE bar in ' +
     'the top bar.'],
    ['Shai-Hulud',
     'Sandworms swim through open sand and feel machinery moving on it. They cannot cross rock or ' +
     'concrete. A worm surfaces, swallows whatever it reaches and sinks again. Shooting one will ' +
     'drive it off but not kill it. Keep an eye on the ripple in the sand.'],
    ['Building',
     'Buy a structure from the <b>BUILD</b> list. When it finishes it says <b>PLACE IT</b> — click ' +
     'it, then click the map. The site must touch your existing base or your poured concrete.'],
    ['Concrete',
     'Pour <b>Concrete Slabs</b> before you build. A structure raised on bare sand starts at about ' +
     'half strength and is slowly ground away by the desert until you slab or repair it. The ' +
     'dashed orange outline marks buildings that are rotting.'],
    ['Power',
     '<b>Windtraps</b> feed the grid; everything else draws from it. Run short and construction ' +
     'slows, turrets traverse sluggishly and your radar goes dark. The POWER bar turns amber then ' +
     'red — build another Windtrap before it does.'],
    ['Tech tree',
     'Structures unlock structures. Windtrap opens the Refinery; the Refinery opens the Light ' +
     'Factory and Radar Outpost; those open the Heavy Factory, and so on up to House IX and the ' +
     'Palace. Locked items stay on the list and tell you what they need.'],
    ['Houses',
     '<b>Atreides</b> see furthest and field the Sonic Tank and Ornithopter. <b>Harkonnen</b> are ' +
     'slow, expensive, and hit like a dropped building — Devastators and the Death Hand, with ' +
     'rocket Troopers instead of riflemen. <b>Ordos</b> are cheap and fast, with the Raider Trike, ' +
     'the Deviator that steals enemy tanks, and the Saboteur.'],
    ['Orders',
     'Left-click or drag to select. Right-click to give a contextual order. The buttons along the ' +
     'bottom give explicit orders: <b>Move</b>, <b>Attack</b>, <b>Guard</b>, <b>Harvest</b>, ' +
     '<b>Repair</b>, <b>Deploy</b>, <b>Scatter</b> and <b>Stop</b>. Buildings can be set to repair ' +
     'themselves, sold, or given a rally point.'],
    ['Firing arcs',
     'Turrets — on buildings and on tanks — rotate slowly and can only fire when the gun is lined ' +
     'up. Flank a Gun Turret and it will still be traversing when you are past it. Select a turret ' +
     'to see its arc and range; press <kbd>Tab</kbd> to show ranges for units too.'],
    ['Repair and the Starport',
     'A <b>Repair Facility</b> takes damaged vehicles for a fee. A <b>Starport</b> lets you order ' +
     'hardware from the Guild at a discount, delivered by frigate after a delay.'],
    ['The campaign',
     'Between missions you pick which territory of Arrakis to invade next. Rich spice, thin rock ' +
     'and a dug-in defender all change how the battle plays. Nine territories stand between you ' +
     'and Arrakeen.'],
    ['Controls',
     '<kbd>Arrows</kbd> or screen edge scroll · <kbd>Wheel</kbd> zoom · <kbd>A</kbd> attack-move · ' +
     '<kbd>G</kbd> guard · <kbd>S</kbd> stop · <kbd>H</kbd> harvest · <kbd>R</kbd> repair · ' +
     '<kbd>D</kbd> deploy · <kbd>F</kbd> next harvester · <kbd>B</kbd> jump to base · ' +
     '<kbd>Ctrl</kbd>+<kbd>1..9</kbd> make group · <kbd>1..9</kbd> recall · <kbd>Space</kbd> pause · ' +
     '<kbd>Esc</kbd> cancel · <kbd>Shift</kbd>+click a build item queues five.']
  ];

  function buildManual() {
    var body = U.$('#help-body');
    body.innerHTML = '';
    MANUAL.forEach(function (m) {
      var sec = U.el('section');
      sec.appendChild(U.el('h4', null, m[0]));
      var p = U.el('p');
      p.innerHTML = m[1];
      sec.appendChild(p);
      body.appendChild(sec);
    });
  }

  function showHelp(show) {
    U.$('#help-overlay').classList.toggle('show', show);
  }

  /* -------------------------------- wiring -------------------------------- */
  function wire() {
    U.on('#mm-new', 'click', function () {
      DUNE.Sfx.init();
      DUNE.Sfx.play('order', 1);
      Game.showScreen('screen-house');
    });

    var hasSave = !!U.load();
    U.$('#mm-continue').disabled = !hasSave;
    U.on('#mm-continue', 'click', function () {
      if (Game.loadCampaign()) {
        DUNE.Sfx.play('order', 1);
        Game.toMap();
      }
    });

    U.on('#mm-help', 'click', function () { showHelp(true); });
    U.on('#help-close', 'click', function () { showHelp(false); });
    U.on('#hs-back', 'click', function () { Game.showScreen('screen-menu'); });

    U.on('#cm-quit', 'click', function () {
      if (confirm('Abandon this campaign and return to the title screen?')) {
        DUNE.UI.CampaignMap.hide();
        Game.showScreen('screen-menu');
      }
    });

    /* --- in-mission chrome --- */
    U.on('#gb-pause', 'click', function () { if (Game.world) Game.world.togglePause(); });
    U.on('#gb-help', 'click', function () { showHelp(true); });
    U.on('#gb-mentat', 'click', function () {
      if (!Game.world || !Game.chosen) return;
      Game.world.state = 'paused';
      U.$('#pause-veil').classList.add('show');
      var c = Game.campaign;
      var brief = DUNE.CAMPAIGN.brief(c.house, c.mission, Game.chosen.id, Game.pendingEnemies || []);
      U.$('#mentat-proceed').textContent = 'RESUME';
      Game.showScreen('screen-mentat');
      DUNE.UI.Mentat.show(brief, function () {
        Game.showScreen('screen-game');
        Game.world.state = 'playing';
        U.$('#pause-veil').classList.remove('show');
        Game.world.renderer.resize();
      });
    });
    U.on('#gb-sound', 'click', function (e) {
      var on = DUNE.Sfx.toggle();
      e.currentTarget.textContent = on ? 'SOUND ON' : 'SOUND OFF';
      if (on && Game.world && Game.world.state === 'playing') DUNE.Sfx.startAmbient();
    });
    U.on('#gb-abort', 'click', function () {
      if (confirm('Abort the mission and withdraw from this territory?')) Game.abort();
    });

    /* --- results --- */
    U.on('#res-continue', 'click', function () {
      DUNE.Sfx.play('select', 1);
      if (Game.finalWin) {
        U.clearSave();
        U.$('#mm-continue').disabled = true;
        Game.showScreen('screen-menu');
      } else {
        Game.toMap();
      }
    });
    U.on('#res-retry', 'click', function () { Game.retry(); });
    U.on('#res-menu', 'click', function () { Game.showScreen('screen-menu'); });

    /* --- window --- */
    window.addEventListener('resize', function () {
      if (Game.world && Game.world.renderer && Game.screen === 'screen-game') {
        Game.world.renderer.resize();
      }
    });
    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && U.$('#help-overlay').classList.contains('show')) {
        showHelp(false);
      }
      // stop the page scrolling under the game
      if ([' ', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(e.key) >= 0 &&
          Game.screen === 'screen-game') {
        e.preventDefault();
      }
    });
  }

  /* -------------------------------- start --------------------------------- */
  function boot() {
    buildHouseCards();
    buildManual();
    wire();
    Game.showScreen('screen-menu');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
"},{"path":"js/audio/sfx.js","type":"text/javascript","text":"/* =============================================================================
   sfx.js - every sound in the game is synthesised at runtime with WebAudio.
   No audio files, so the project stays portable and offline.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util;

  var ctx = null, master = null, noiseBuf = null;
  var enabled = true, ready = false;
  var lastPlay = {};          // rate limiting per sound name
  var ambientNodes = null;

  function init() {
    if (ready) return true;
    var AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return false;
    try { ctx = new AC(); } catch (e) { return false; }
    master = ctx.createGain();
    master.gain.value = 0.55;
    master.connect(ctx.destination);
    // 2 seconds of white noise, reused by every noise-based effect
    noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    var d = noiseBuf.getChannelData(0);
    for (var i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    ready = true;
    return true;
  }

  function resume() {
    if (ctx && ctx.state === 'suspended') ctx.resume();
  }

  function now() { return ctx.currentTime; }

  /* ------------------------------ primitives ----------------------------- */
  function tone(opts) {
    var t0 = now() + (opts.delay || 0);
    var osc = ctx.createOscillator();
    var g = ctx.createGain();
    osc.type = opts.type || 'sine';
    osc.frequency.setValueAtTime(opts.f0, t0);
    if (opts.f1 != null) osc.frequency.exponentialRampToValueAtTime(Math.max(1, opts.f1), t0 + opts.dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, opts.vol || 0.2), t0 + (opts.atk || 0.005));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + opts.dur);
    osc.connect(g);
    (opts.dest || g).connect ? g.connect(opts.dest || master) : g.connect(master);
    osc.start(t0);
    osc.stop(t0 + opts.dur + 0.02);
    return osc;
  }

  function noise(opts) {
    var t0 = now() + (opts.delay || 0);
    var src = ctx.createBufferSource();
    src.buffer = noiseBuf;
    src.loop = true;
    var filt = ctx.createBiquadFilter();
    filt.type = opts.filter || 'bandpass';
    filt.frequency.setValueAtTime(opts.f0, t0);
    if (opts.f1 != null) filt.frequency.exponentialRampToValueAtTime(Math.max(20, opts.f1), t0 + opts.dur);
    filt.Q.value = opts.q == null ? 1 : opts.q;
    var g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, opts.vol || 0.2), t0 + (opts.atk || 0.004));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + opts.dur);
    src.connect(filt); filt.connect(g); g.connect(opts.dest || master);
    src.start(t0);
    src.stop(t0 + opts.dur + 0.02);
    return src;
  }

  /* -------------------------------- voices ------------------------------- */
  var VOICES = {
    select:   function (v) { tone({ type: 'square', f0: 620, f1: 900, dur: 0.06, vol: 0.07 * v }); },
    order:    function (v) { tone({ type: 'square', f0: 420, f1: 640, dur: 0.07, vol: 0.07 * v }); },
    deny:     function (v) { tone({ type: 'square', f0: 220, f1: 110, dur: 0.14, vol: 0.09 * v }); },
    place:    function (v) { noise({ f0: 260, f1: 90, dur: 0.28, vol: 0.18 * v, filter: 'lowpass', q: 0.8 });
                             tone({ type: 'triangle', f0: 110, f1: 55, dur: 0.22, vol: 0.12 * v }); },
    build:    function (v) { tone({ type: 'square', f0: 330, dur: 0.07, vol: 0.06 * v });
                             tone({ type: 'square', f0: 494, dur: 0.09, vol: 0.06 * v, delay: 0.08 });
                             tone({ type: 'square', f0: 660, dur: 0.14, vol: 0.06 * v, delay: 0.17 }); },
    ready:    function (v) { tone({ type: 'sine', f0: 880, dur: 0.1, vol: 0.09 * v });
                             tone({ type: 'sine', f0: 1320, dur: 0.14, vol: 0.07 * v, delay: 0.1 }); },
    rifle:    function (v) { noise({ f0: 2600, f1: 900, dur: 0.06, vol: 0.09 * v, q: 0.9 }); },
    cannon:   function (v) { noise({ f0: 900, f1: 120, dur: 0.18, vol: 0.2 * v, filter: 'lowpass', q: 1 });
                             tone({ type: 'triangle', f0: 180, f1: 50, dur: 0.16, vol: 0.14 * v }); },
    rocket:   function (v) { noise({ f0: 400, f1: 2400, dur: 0.35, vol: 0.12 * v, q: 0.6 }); },
    sonic:    function (v) { tone({ type: 'sawtooth', f0: 1400, f1: 90, dur: 0.5, vol: 0.13 * v }); },
    explode:  function (v) { noise({ f0: 700, f1: 60, dur: 0.55, vol: 0.28 * v, filter: 'lowpass', q: 1.2 });
                             tone({ type: 'triangle', f0: 120, f1: 32, dur: 0.45, vol: 0.2 * v }); },
    bigboom:  function (v) { noise({ f0: 500, f1: 35, dur: 1.1, vol: 0.38 * v, filter: 'lowpass', q: 1.4 });
                             tone({ type: 'sine', f0: 80, f1: 22, dur: 0.9, vol: 0.3 * v }); },
    worm:     function (v) { tone({ type: 'sawtooth', f0: 62, f1: 26, dur: 1.5, vol: 0.3 * v });
                             noise({ f0: 220, f1: 60, dur: 1.6, vol: 0.2 * v, filter: 'lowpass', q: 0.7 }); },
    wormeat:  function (v) { noise({ f0: 900, f1: 90, dur: 0.8, vol: 0.3 * v, filter: 'lowpass' });
                             tone({ type: 'sawtooth', f0: 140, f1: 40, dur: 0.7, vol: 0.2 * v }); },
    harvest:  function (v) { noise({ f0: 320, f1: 260, dur: 0.5, vol: 0.06 * v, filter: 'bandpass', q: 3 }); },
    credit:   function (v) { tone({ type: 'square', f0: 1200, dur: 0.035, vol: 0.035 * v }); },
    alarm:    function (v) { tone({ type: 'square', f0: 740, dur: 0.12, vol: 0.1 * v });
                             tone({ type: 'square', f0: 560, dur: 0.16, vol: 0.1 * v, delay: 0.14 }); },
    victory:  function (v) { [523, 659, 784, 1047].forEach(function (f, i) {
                               tone({ type: 'triangle', f0: f, dur: 0.4, vol: 0.12 * v, delay: i * 0.16 }); }); },
    defeat:   function (v) { [392, 330, 262, 196].forEach(function (f, i) {
                               tone({ type: 'sawtooth', f0: f, dur: 0.5, vol: 0.11 * v, delay: i * 0.22 }); }); },
    deploy:   function (v) { noise({ f0: 160, f1: 700, dur: 0.5, vol: 0.14 * v, filter: 'lowpass' }); },
    repair:   function (v) { tone({ type: 'square', f0: 300, f1: 900, dur: 0.12, vol: 0.05 * v }); },
    zap:      function (v) { tone({ type: 'sawtooth', f0: 2000, f1: 200, dur: 0.25, vol: 0.12 * v }); },
    frigate:  function (v) { tone({ type: 'sawtooth', f0: 90, f1: 150, dur: 1.4, vol: 0.14 * v });
                             noise({ f0: 300, f1: 800, dur: 1.4, vol: 0.1 * v, filter: 'lowpass' }); }
  };

  var LIMIT = {                 // minimum seconds between repeats
    rifle: 0.05, cannon: 0.07, explode: 0.06, credit: 0.09,
    harvest: 0.5, rocket: 0.08, select: 0.05
  };

  var Sfx = DUNE.Sfx = {
    init: function () { return init(); },
    resume: resume,
    isEnabled: function () { return enabled; },
    setEnabled: function (v) {
      enabled = !!v;
      if (master) master.gain.value = enabled ? 0.55 : 0;
      if (!enabled) Sfx.stopAmbient();
    },
    toggle: function () { Sfx.setEnabled(!enabled); return enabled; },

    /**
     * Play a named voice. `vol` scales it; pass `dist` (0..1, 1 = far) to
     * attenuate sounds happening off the edge of the viewport.
     */
    play: function (name, vol, dist) {
      if (!enabled || !ready) return;
      if (ctx.state === 'suspended') return;
      var fn = VOICES[name];
      if (!fn) return;
      var t = ctx.currentTime, lim = LIMIT[name];
      if (lim) {
        if (lastPlay[name] && t - lastPlay[name] < lim) return;
        lastPlay[name] = t;
      }
      var v = (vol == null ? 1 : vol);
      if (dist != null) v *= U.clamp(1 - dist, 0, 1);
      if (v <= 0.02) return;
      try { fn(v); } catch (e) { /* audio hiccup - never break the game */ }
    },

    /** Desert wind + a low sietch drone while a mission is running. */
    startAmbient: function () {
      if (!enabled || !ready || ambientNodes) return;
      try {
        var src = ctx.createBufferSource();
        src.buffer = noiseBuf; src.loop = true;
        var f = ctx.createBiquadFilter();
        f.type = 'lowpass'; f.frequency.value = 420; f.Q.value = 0.6;
        var g = ctx.createGain(); g.gain.value = 0.035;
        // slow LFO so the wind breathes
        var lfo = ctx.createOscillator(); lfo.frequency.value = 0.08;
        var lfoGain = ctx.createGain(); lfoGain.gain.value = 0.022;
        lfo.connect(lfoGain); lfoGain.connect(g.gain);
        src.connect(f); f.connect(g); g.connect(master);
        var drone = ctx.createOscillator();
        drone.type = 'sine'; drone.frequency.value = 47;
        var dg = ctx.createGain(); dg.gain.value = 0.028;
        drone.connect(dg); dg.connect(master);
        src.start(); lfo.start(); drone.start();
        ambientNodes = [src, lfo, drone, g, dg];
      } catch (e) { ambientNodes = null; }
    },
    stopAmbient: function () {
      if (!ambientNodes) return;
      try {
        ambientNodes[0].stop(); ambientNodes[1].stop(); ambientNodes[2].stop();
      } catch (e) { /* already stopped */ }
      ambientNodes = null;
    }
  };

  // Browsers gate audio behind a gesture; wake it on the first interaction.
  ['pointerdown', 'keydown'].forEach(function (ev) {
    window.addEventListener(ev, function once() {
      init(); resume();
      window.removeEventListener(ev, once);
    });
  });
})();
"},{"path":"js/data/campaign.js","type":"text/javascript","text":"/* =============================================================================
   campaign.js - the map of Arrakis, the mission table, and the Mentat's words.

   The campaign is not a fixed list of levels: each mission offers two or three
   territories and the player picks which one to invade. The territory decides
   the terrain, how rich the spice is, how much rock there is to build on, and
   which House is already dug in there.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util;

  /* --------------------------- territory table -------------------------- */
  /* x,y are canvas coordinates on the 900x560 campaign map.
     spice 1..3 = how much melange the surveys promise.
     rock  1..3 = how much solid ground there is to found a base on.
     risk  1..3 = how hard the defender will be dug in.                     */
  function T(id, name, x, y, spice, rock, risk, note) {
    return { id: id, name: name, x: x, y: y, spice: spice, rock: rock, risk: risk, note: note };
  }

  var TERRS = [
    T('polarsink',  'Polar Sink',          120,  86, 1, 3, 1, 'The lowest point on Arrakis. Cold, wind-scoured rock — easy to build on, almost no spice.'),
    T('cavebirds',  'Cave of Birds',       282,  92, 2, 3, 1, 'Sheltered rock galleries. A defensible pocket with workable spice on the approaches.'),
    T('rimwallw',   'Rimwall West',        444,  84, 2, 2, 2, 'The western lip of the Shield Wall. Broken stone and sudden drops.'),
    T('falsewalln', 'False Wall North',    604,  90, 2, 2, 2, 'A ridge that looks like the Shield Wall and is not. Good sightlines, poor cover.'),
    T('brokenland', 'Broken Land',         762,  96, 3, 1, 3, 'Shattered pan, heavy spice, almost no rock. Worm country.'),

    T('windpass',   'Wind Pass',            86, 194, 1, 3, 1, 'A gap in the northern rimwall. Whoever holds it holds the northern trade.'),
    T('sihaya',     'Sihaya Ridge',        222, 186, 2, 3, 2, 'A long spine of rock above rich sand. The textbook place to put a base.'),
    T('carthag',    'Carthag',             382, 182, 2, 3, 3, 'The Harkonnen city. Whoever sits here is never short of rockcrete.'),
    T('shieldwall', 'Shield Wall',         544, 176, 1, 3, 3, 'The great barrier. Enormous rock, thin spice, and every approach is a killing ground.'),
    T('haggabasin', 'Hagga Basin',         702, 188, 3, 2, 2, 'A wide bowl of drift sand over a genuine spice bloom.'),
    T('oldgap',     'Old Gap',             842, 196, 2, 2, 2, 'An eroded pass in the eastern wall. Exposed, but the sand beyond is thick.'),

    T('plaster',    'Plaster Basin',       142, 300, 2, 2, 2, 'Pale salt flats. The glare hides movement until it is close.'),
    T('arrakeen',   'Arrakeen',            302, 296, 2, 3, 3, 'The seat of government. The Residency stands on the largest slab of rock on the planet.'),
    T('sietchtabr', 'Sietch Tabr',         462, 292, 3, 2, 2, 'Fremen ground. They will not help you, but they will not stop you either.'),
    T('hargpass',   'Harg Pass',           624, 300, 2, 2, 2, 'A narrow rock corridor. Armour funnels through one at a time.'),
    T('garakulon',  'Gara Kulon',          782, 304, 2, 2, 3, 'Old mining claims, half-buried. Still bleeding spice after two centuries.'),

    T('funeral',    'Funeral Plain',       202, 408, 3, 1, 3, 'Named for a harvester crew that lingered. Superb spice. Superb worms.'),
    T('greatflat',  'The Great Flat',      382, 414, 3, 1, 3, 'Open sand from horizon to horizon. Nothing to hide behind, nothing to build on.'),
    T('habbanya',   'Habbanya Erg',        544, 406, 3, 2, 2, 'Dune sea with rock islands. Rich, but every convoy is a gamble.'),
    T('redchasm',   'Red Chasm',           704, 412, 2, 3, 3, 'A rust-coloured rift. Sheer walls make it a fortress for whoever gets there first.'),

    T('cielago',    'Cielago Depression',  302, 496, 2, 2, 2, 'A shallow sink in the southern desert. Quiet, until it is not.'),
    T('bight',      'Bight of the Chasm',  562, 500, 2, 2, 3, 'Where the chasm opens onto the southern sea of sand.'),
    T('tuono',      'Tuono Basin',         762, 502, 3, 2, 3, 'The deep south. Far from everything, and the last place a rival expects you.')
  ];

  var BY_ID = {};
  TERRS.forEach(function (t) { BY_ID[t.id] = t; });

  /* Give every territory an irregular but deterministic outline so the map
     reads as a real planetary chart rather than a grid of dots. */
  TERRS.forEach(function (t) {
    var rnd = U.rng(U.stringSeed(t.id));
    var pts = [], n = 9;
    for (var i = 0; i < n; i++) {
      var a = (i / n) * U.TAU + rnd() * 0.18;
      var r = 52 + rnd() * 26;
      pts.push([t.x + Math.cos(a) * r * 1.18, t.y + Math.sin(a) * r * 0.86]);
    }
    t.poly = pts;
  });

  /* ---------------------------- mission table --------------------------- */
  /* choices: territory ids the player may pick from at this stage.
     enemies: how many rival Houses are already established.
     tech:    highest structure/unit tech level available this mission.     */
  var MISSIONS = [
    /* Mission 1 has no enemy base at all - just a rival patrol wandering the
       sand - so the opening is purely about getting the spice flowing. */
    { n: 1, tech: 1, credits: 2200, enemies: 1, skirmish: true, objective: 'harvest', amount: 1000,
      choices: ['polarsink', 'cavebirds'], aiAggr: 0.25, aiEco: 0.6 },

    { n: 2, tech: 2, credits: 2000, enemies: 1, objective: 'destroy',
      choices: ['windpass', 'sihaya', 'rimwallw'], aiAggr: 0.35, aiEco: 0.8 },

    { n: 3, tech: 3, credits: 1900, enemies: 1, objective: 'destroy',
      choices: ['plaster', 'falsewalln', 'haggabasin'], aiAggr: 0.5, aiEco: 1.0 },

    { n: 4, tech: 4, credits: 1800, enemies: 1, objective: 'destroy',
      choices: ['hargpass', 'sietchtabr', 'oldgap'], aiAggr: 0.65, aiEco: 1.1 },

    { n: 5, tech: 5, credits: 1800, enemies: 2, objective: 'destroy',
      choices: ['habbanya', 'cielago', 'garakulon'], aiAggr: 0.75, aiEco: 1.15 },

    { n: 6, tech: 6, credits: 1700, enemies: 2, objective: 'destroy',
      choices: ['funeral', 'redchasm', 'bight'], aiAggr: 0.85, aiEco: 1.25 },

    { n: 7, tech: 7, credits: 1700, enemies: 2, imperial: true, objective: 'destroy',
      choices: ['greatflat', 'brokenland', 'tuono'], aiAggr: 0.95, aiEco: 1.35 },

    { n: 8, tech: 8, credits: 1600, enemies: 2, imperial: true, objective: 'destroy',
      choices: ['shieldwall', 'carthag'], aiAggr: 1.05, aiEco: 1.45 },

    { n: 9, tech: 9, credits: 1600, enemies: 2, imperial: true, final: true, objective: 'destroy',
      choices: ['arrakeen'], aiAggr: 1.2, aiEco: 1.6 }
  ];

  /* ------------------------------ briefings ----------------------------- */
  /* Mentat voice per House. Each mission body is written once; the House
     framing around it is what makes Cyril, Radnor and Ammon sound different. */
  var VOICE = {
    atreides: {
      greet: ['My Duke.', 'My Lord.', 'Sire.'],
      sign: 'We fight cleanly, and we fight to hold. Cyril out.',
      colour: 'The Emperor watches. So does every House in the Landsraad. Win this the right way.'
    },
    harkonnen: {
      greet: ['Baron.', 'My Baron.', 'Na-Baron.'],
      sign: 'Take it. Break whatever will not be taken. Ammon out.',
      colour: 'Casualties are an accounting problem, not a moral one. Spend them.'
    },
    ordos: {
      greet: ['Executive.', 'Honoured Executive.', 'Director.'],
      sign: 'Cheaply, quickly, and preferably with somebody else’s equipment. Radnor out.',
      colour: 'We have already priced this territory. It is worth more than the army we will lose taking it.'
    }
  };

  /** Mission narrative. Returns an array of paragraphs. */
  function missionBody(m, terr, house, enemyHouses) {
    var enemyNames = enemyHouses.map(function (h) { return DUNE.HOUSES[h].full; });
    var enemyText = enemyNames.length === 0 ? 'no organised opposition'
      : enemyNames.length === 1 ? enemyNames[0]
      : enemyNames.slice(0, -1).join(', ') + ' and ' + enemyNames[enemyNames.length - 1];

    var spiceWord = ['thin', 'workable', 'rich'][terr.spice - 1];
    var rockWord = ['almost no rock — you will be pouring a great deal of concrete',
                    'scattered rock shelves',
                    'broad rock plateaus'][terr.rock - 1];

    var body = [];
    body.push(terr.name + '. ' + terr.note);
    body.push('Survey reads the spice as ' + spiceWord + ', and the ground gives you ' + rockWord + '.');

    switch (m.n) {
      case 1:
        body.push('You have a Construction Yard and nothing else. Lay Concrete Slabs, raise a ' +
                  'Windtrap, then a Refinery, and put the Harvester it brings onto the nearest ' +
                  'spice bloom. The Emperor has set a quota before he will recognise your claim.');
        body.push('There is no enemy base here — only a rival patrol on the sand. But the desert ' +
                  'itself is hostile: Shai-Hulud comes to anything that lingers on open ground, ' +
                  'and a building founded off the concrete will be eaten away.');
        break;
      case 2:
        body.push(enemyText + ' has put down a forward post here. It is small. It will not stay small.');
        body.push('Build your economy first — without spice there is no army — then level every ' +
                  'structure they own.');
        break;
      case 3:
        body.push(enemyText + ' has a full base on this ground, with a Refinery of their own and ' +
                  'harvesters working the field. Kill their economy and the base dies with it.');
        body.push('Get a Radar Outpost up. Fighting this territory blind will cost you the mission.');
        break;
      case 4:
        body.push(enemyText + ' has armour here, and they have learned to mass it before they come. ' +
                  'Expect organised waves rather than probes.');
        body.push('Gun Turrets traverse slowly. Two of them covering each other’s blind arc will hold ' +
                  'a line that one of them cannot.');
        break;
      case 5:
        body.push('Two rivals share this territory and neither will wait politely for you to finish with ' +
                  'the other: ' + enemyText + '.');
        body.push('You will need more than one Refinery and more than one field. If they kill your ' +
                  'harvesters, your guns fall silent within minutes.');
        break;
      case 6:
        body.push(enemyText + ' are fortified and expanding. Their commanders will send Construction ' +
                  'Vehicles out to found second bases the moment their first field runs dry.');
        body.push('A Repair Facility pays for itself here. So does a Starport, if you would rather buy ' +
                  'hardware than build it.');
        break;
      case 7:
        body.push('Imperial Sardaukar have been “observing” this territory. They are not observing. ' +
                  'Alongside them: ' + enemyText + '.');
        body.push('House IX will release your House’s own weapon once the research building stands. ' +
                  'You are going to need it.');
        break;
      case 8:
        body.push('This is the last territory before the Residency. ' + enemyText + ' have concentrated ' +
                  'everything here, with Imperial support.');
        body.push('Raise the Palace. Nothing you can field from a factory will settle this on its own.');
        break;
      case 9:
        body.push('Arrakeen. The Residency, the landing field, and the governorship of the planet.');
        body.push(enemyText + ' hold it, with Imperial legions behind the walls. There will be no ' +
                  'second attempt and no orderly withdrawal.');
        body.push('Take the city and Arrakis is yours. The spice must flow — and it will flow to us.');
        break;
    }
    return body;
  }

  function objectiveText(m) {
    if (m.objective === 'harvest') {
      return ['Harvest ' + m.amount + ' credits worth of spice.',
              'Do not lose your entire base.'];
    }
    return ['Destroy every enemy structure in the territory.',
            'Do not lose your entire base.'];
  }

  var CAMP = DUNE.CAMPAIGN = {
    TERRITORIES: TERRS,
    byId: function (id) { return BY_ID[id]; },
    MISSIONS: MISSIONS,
    count: MISSIONS.length,

    mission: function (n) { return MISSIONS[U.clamp(n - 1, 0, MISSIONS.length - 1)]; },

    /** Territories offered at mission `n`, skipping any already conquered. */
    choicesFor: function (n, owned) {
      var m = CAMP.mission(n);
      var list = m.choices.filter(function (id) { return owned.indexOf(id) < 0; });
      if (!list.length) list = m.choices.slice();
      return list.map(function (id) { return BY_ID[id]; });
    },

    /** Which Houses defend `terr` at mission `n`, deterministically. */
    enemiesFor: function (n, terrId, playerHouse) {
      var m = CAMP.mission(n);
      if (m.enemies === 0) return [];
      var rivals = DUNE.rivals(playerHouse);
      var rnd = U.rng(U.stringSeed(terrId + playerHouse + n));
      var pool = U.shuffle(rivals.slice(), rnd);
      var out = pool.slice(0, Math.min(m.enemies, pool.length));
      if (m.final) {
        // the last stand: both rivals and the Emperor's own legion
        out = pool.slice();
        out.push('sardaukar');
      } else if (m.imperial && out.length >= 2) {
        out[out.length - 1] = 'sardaukar';   // the Emperor lends a legion
      }
      while (out.length < m.enemies) out.push('sardaukar');
      return out;
    },

    /** Everything the Mentat screen needs. */
    brief: function (houseId, n, terrId, enemyHouses) {
      var m = CAMP.mission(n);
      var terr = BY_ID[terrId];
      var v = VOICE[houseId] || VOICE.atreides;
      var rnd = U.rng(U.stringSeed(houseId + terrId + n));
      var greet = v.greet[Math.floor(rnd() * v.greet.length)];

      var paras = [];
      paras.push(greet + ' Mission ' + n + ' of ' + MISSIONS.length + '.');
      paras = paras.concat(missionBody(m, terr, houseId, enemyHouses));
      paras.push(v.colour);
      paras.push(v.sign);

      return {
        title: 'Operation — ' + terr.name,
        mentat: DUNE.HOUSES[houseId].mentat,
        house: houseId,
        text: paras.join('\n\n'),
        objectives: objectiveText(m),
        mission: m,
        territory: terr
      };
    },

    /** Post-mission Mentat line. */
    debrief: function (houseId, won, n) {
      var h = DUNE.HOUSES[houseId];
      if (won) {
        if (n >= MISSIONS.length) {
          return 'Arrakis is ours. The Guild recognises ' + h.full + ' as governors of Dune, ' +
                 'and the spice flows through our hands alone.';
        }
        return 'The territory is secured. The Emperor has noted the delivery figures. ' +
               'Choose where we go next.';
      }
      return 'We have lost the territory. Our forces there no longer exist. ' +
             'We can refit and try again — the Emperor is patient, but not endlessly.';
    }
  };
})();
"},{"path":"js/data/config.js","type":"text/javascript","text":"/* =============================================================================
   config.js - tuning constants, terrain table and the damage matrix.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};

  DUNE.CFG = {
    TILE: 24,
    MAP_W: 64,
    MAP_H: 64,

    /* --- economy ------------------------------------------------------- */
    HARVEST_RATE: 34,          // spice units drawn per second while harvesting
    UNLOAD_RATE: 120,          // spice units pushed into the silo per second
    HARVESTER_CAP: 700,
    SPICE_TO_CREDITS: 1,       // conversion on unload
    REFINERY_STORAGE: 1000,
    SILO_STORAGE: 1000,
    BASE_STORAGE: 1000,        // what a Construction Yard alone can hold
    TILE_SPICE: 240,           // spice in a normal spice tile
    TILE_SPICE_THICK: 560,     // spice in a thick spice tile
    SPICE_REGROW: 0.55,        // spice units regenerated per second per seeded tile
    REPAIR_COST_PER_HP: 0.30,
    REPAIR_RATE: 26,           // hp/sec when repairing a structure
    UNIT_REPAIR_RATE: 40,      // hp/sec inside a repair facility
    UNIT_REPAIR_COST: 0.22,
    REFUND_RATE: 0.5,          // credits back when selling a structure

    /* --- construction -------------------------------------------------- */
    BUILD_SECONDS_PER_CREDIT: 0.028,
    MIN_BUILD_SECONDS: 3,
    PLACEMENT_RANGE: 1,        // tiles of adjacency required to existing base
    CONCRETE_START_HP: 1.0,    // fraction of max hp when fully on concrete
    SAND_START_HP: 0.52,       // fraction of max hp with no concrete at all
    SAND_DECAY: 1.25,          // hp lost per second per uncovered footprint tile
    SAND_DECAY_FLOOR: 0.20,    // decay will not push a building below this
    MAX_QUEUE: 9,

    /* --- power --------------------------------------------------------- */
    MIN_POWER_RATIO: 0.25,     // worst-case efficiency during a brown-out
    POWER_WARN: 0.95,

    /* --- combat -------------------------------------------------------- */
    VETERANCY_KILLS: 3,        // kills needed for a veteran chevron
    VETERAN_BONUS: 0.22,
    GUARD_RANGE_BONUS: 1.5,    // tiles a guarding unit will stray to engage
    SCATTER_RANGE: 3,

    /* --- worms --------------------------------------------------------- */
    /* A worm is a little faster than a Harvester, so a crew that notices it
       early can still reach rock. Fast enough to be terrifying, slow enough
       that reacting is a real decision. */
    WORM_SPEED: 1.55,          // tiles/sec while submerged and hunting
    WORM_SENSE: 10,            // tiles: how far a worm feels rhythmic movement
    WORM_EAT_RANGE: 0.75,
    WORM_MEALS: 2,             // meals before the worm sinks back into the deep
    WORM_REST: 45,             // seconds spent dormant after a feeding run
    WORM_STRIKE_TIME: 1.1,

    /* --- vision -------------------------------------------------------- */
    FOG_UPDATE: 0.22,          // seconds between visibility recomputes

    /* --- view ---------------------------------------------------------- */
    SCROLL_SPEED: 720,         // px/sec keyboard scroll
    EDGE_SCROLL: 22,           // px band at the window edge that scrolls
    MIN_ZOOM: 0.6,
    MAX_ZOOM: 1.9,

    /* --- misc ---------------------------------------------------------- */
    MAX_DT: 0.05,
    AI_THINK: 1.1,
    STARPORT_DISCOUNT: 0.75,
    STARPORT_DELAY: 9
  };

  /* ------------------------------- terrain ------------------------------ */
  var T = DUNE.T = {
    SAND: 0,
    DUNES: 1,
    ROCK: 2,
    MOUNTAIN: 3,
    SPICE: 4,
    SPICE2: 5
  };

  /**
   * moveCost per movement class. Infinity = impassable.
   * foot  - infantry, can scale mountains
   * wheel - trikes / quads, fast on rock, bogged down in dunes
   * track - tanks and harvesters
   * air   - ignores everything
   */
  DUNE.TERRAIN = {};
  DUNE.TERRAIN[T.SAND]     = { name: 'Sand',       open: true,  foot: 1.35, wheel: 1.25, track: 1.15 };
  DUNE.TERRAIN[T.DUNES]    = { name: 'Dunes',      open: true,  foot: 1.75, wheel: 1.85, track: 1.35 };
  DUNE.TERRAIN[T.ROCK]     = { name: 'Rock',       open: false, foot: 1.00, wheel: 1.00, track: 1.00 };
  DUNE.TERRAIN[T.MOUNTAIN] = { name: 'Mountain',   open: false, foot: 2.60, wheel: Infinity, track: Infinity };
  DUNE.TERRAIN[T.SPICE]    = { name: 'Spice',      open: true,  foot: 1.45, wheel: 1.45, track: 1.25 };
  DUNE.TERRAIN[T.SPICE2]   = { name: 'Thick Spice',open: true,  foot: 1.70, wheel: 1.70, track: 1.40 };

  /** `open` marks sand-like ground: worms swim here, buildings rot here. */
  DUNE.isOpenSand = function (t) { return DUNE.TERRAIN[t].open; };
  DUNE.isSpice = function (t) { return t === T.SPICE || t === T.SPICE2; };

  /* --------------------------- damage matrix ---------------------------- */
  /* Armour classes */
  DUNE.ARMOUR = { NONE: 'none', LIGHT: 'light', HEAVY: 'heavy', BUILDING: 'building', AIR: 'air' };

  /* warhead -> armour multiplier. Small arms shred infantry and bounce off
     tanks; shells flatten buildings; sonic waves ignore the difference. */
  DUNE.WARHEADS = {
    small:  { none: 1.00, light: 0.38, heavy: 0.14, building: 0.18, air: 0.55 },
    ap:     { none: 0.45, light: 1.00, heavy: 1.00, building: 0.70, air: 0.35 },
    he:     { none: 1.05, light: 0.85, heavy: 0.62, building: 1.30, air: 0.15 },
    rocket: { none: 0.70, light: 1.15, heavy: 1.25, building: 1.05, air: 1.30 },
    sonic:  { none: 1.45, light: 1.00, heavy: 0.90, building: 0.55, air: 0.40 },
    flame:  { none: 1.60, light: 0.75, heavy: 0.40, building: 0.95, air: 0.10 },
    crush:  { none: 3.00, light: 0.10, heavy: 0.05, building: 0.10, air: 0.00 },
    nuke:   { none: 2.00, light: 1.80, heavy: 1.60, building: 2.20, air: 1.00 }
  };

  DUNE.damageMultiplier = function (warhead, armour) {
    var w = DUNE.WARHEADS[warhead] || DUNE.WARHEADS.ap;
    var m = w[armour];
    return m == null ? 1 : m;
  };
})();
"},{"path":"js/data/houses.js","type":"text/javascript","text":"/* =============================================================================
   houses.js - the three great Houses (plus the Emperor's Sardaukar as a late
   enemy). Houses differ in three ways at once: stat modifiers, which buildings
   they are allowed to raise, and a unique unit line topped by a Palace weapon.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};

  DUNE.HOUSES = {

    atreides: {
      id: 'atreides',
      name: 'Atreides',
      full: 'House Atreides',
      home: 'Caladan',
      colour: '#3f6fd8',
      colourLight: '#8fb4ff',
      colourDark: '#1d3576',
      trim: '#e8e2d0',
      mentat: 'Cyril',
      mentatMood: 'earnest',
      motto: 'Honour, loyalty, and the desert wind.',
      crest: 'hawk',
      desc: 'Disciplined and beloved. Atreides forces are balanced and see further ' +
            'than anyone on Arrakis, and their Ornithopters own the sky. They win ' +
            'slowly, by never wasting a soldier.',
      /* stat modifiers applied to every unit and structure of the house */
      mods: { hp: 1.00, dmg: 1.00, speed: 1.06, range: 1.12, cost: 1.00, build: 1.00, sight: 1.20 },
      traits: [
        ['Vision', 'Excellent'],
        ['Armour', 'Average'],
        ['Firepower', 'Average'],
        ['Speed', 'Good']
      ],
      unique: ['Sonic Tank', 'Ornithopter', 'Fremen allies'],
      /* infantry doctrine: Atreides train riflemen, never rocket troopers */
      barracks: 'barracks',
      palace: {
        id: 'fremen',
        name: 'Summon Fremen',
        desc: 'Three Fremen warriors emerge from the deep desert at a point of your choosing.',
        cooldown: 150
      }
    },

    harkonnen: {
      id: 'harkonnen',
      name: 'Harkonnen',
      full: 'House Harkonnen',
      home: 'Giedi Prime',
      colour: '#c0231c',
      colourLight: '#ff7a63',
      colourDark: '#6d0f0b',
      trim: '#241a12',
      mentat: 'Ammon',
      mentatMood: 'cruel',
      motto: 'Fear is the only currency.',
      crest: 'ram',
      desc: 'Brutal, armoured and slow. Every Harkonnen machine carries more plate ' +
            'and a bigger gun than its rivals, and costs more to field. They have ' +
            'no riflemen — only rocket Troopers out of the WOR — and they finish ' +
            'arguments with the Death Hand.',
      mods: { hp: 1.25, dmg: 1.18, speed: 0.88, range: 1.00, cost: 1.10, build: 1.10, sight: 0.95 },
      traits: [
        ['Vision', 'Poor'],
        ['Armour', 'Superb'],
        ['Firepower', 'Superb'],
        ['Speed', 'Poor']
      ],
      unique: ['Devastator', 'Death Hand missile', 'Trooper infantry'],
      barracks: 'wor',
      palace: {
        id: 'deathhand',
        name: 'Death Hand',
        desc: 'An atomic-tipped missile is lobbed at any point on the map. Nothing under it survives.',
        cooldown: 210
      }
    },

    ordos: {
      id: 'ordos',
      name: 'Ordos',
      full: 'House Ordos',
      home: 'Draconis IV',
      colour: '#22a377',
      colourLight: '#6ef0bb',
      colourDark: '#0d5a41',
      trim: '#0b1c16',
      mentat: 'Radnor',
      mentatMood: 'sly',
      motto: 'Buy what you cannot take. Take what you cannot buy.',
      crest: 'coil',
      desc: 'A cartel, not a family. Ordos machines are cheap, fast and flimsy. ' +
            'They field Raider Trikes, subvert enemy tanks with the Deviator, and ' +
            'send Saboteurs to do what an army would cost too much to do.',
      mods: { hp: 0.86, dmg: 0.94, speed: 1.18, range: 1.00, cost: 0.82, build: 0.86, sight: 1.05 },
      traits: [
        ['Vision', 'Good'],
        ['Armour', 'Poor'],
        ['Firepower', 'Fair'],
        ['Speed', 'Superb']
      ],
      unique: ['Deviator', 'Raider Trike', 'Saboteur'],
      barracks: 'both',     // Ordos will train anything that will take a wage
      palace: {
        id: 'saboteur',
        name: 'Deploy Saboteur',
        desc: 'A cloaked infiltrator is released from the Palace. One touch levels a building.',
        cooldown: 120
      }
    },

    /* Enemy-only. The Emperor's own, thrown in when the campaign turns. */
    sardaukar: {
      id: 'sardaukar',
      name: 'Sardaukar',
      full: 'Imperial Sardaukar',
      home: 'Salusa Secundus',
      colour: '#8d49c9',
      colourLight: '#cfa1ff',
      colourDark: '#4a2170',
      trim: '#1a1020',
      mentat: 'Imperial Herald',
      mentatMood: 'cold',
      motto: 'The Emperor is watching.',
      crest: 'crown',
      desc: 'Imperial shock legions on loan to whoever displeases the Padishah least.',
      mods: { hp: 1.30, dmg: 1.25, speed: 1.00, range: 1.05, cost: 1.00, build: 0.90, sight: 1.10 },
      traits: [['Vision', 'Good'], ['Armour', 'Superb'], ['Firepower', 'Superb'], ['Speed', 'Average']],
      unique: ['Imperial armour'],
      barracks: 'wor',
      playable: false,
      palace: null
    }
  };

  DUNE.PLAYABLE_HOUSES = ['atreides', 'ordos', 'harkonnen'];

  DUNE.house = function (id) { return DUNE.HOUSES[id] || DUNE.HOUSES.atreides; };

  /** Colour set handed to the sprite renderer. */
  DUNE.houseColours = function (id) {
    var h = DUNE.house(id);
    return {
      main: h.colour,
      light: h.colourLight,
      dark: h.colourDark,
      trim: h.trim
    };
  };

  /** Rival houses of `id`, in the order the campaign likes to throw them at you. */
  DUNE.rivals = function (id) {
    return DUNE.PLAYABLE_HOUSES.filter(function (h) { return h !== id; });
  };
})();
"},{"path":"js/data/structures.js","type":"text/javascript","text":"/* =============================================================================
   structures.js - every building, and the tech tree that chains them together.

   `requires` lists structure ids that must already stand (and still stand) in
   your base before the item appears on the Construction Yard list. `tech` is
   the minimum mission tech level, so the tree also opens up as the campaign
   advances. `houses` restricts a building to particular Houses.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var A = DUNE.ARMOUR;

  /* shorthand: every structure is armour class BUILDING unless stated */
  function S(def) {
    def.kind = 'structure';
    if (!def.armour) def.armour = A.BUILDING;
    if (def.sight == null) def.sight = 4;
    if (def.power == null) def.power = 0;
    if (!def.requires) def.requires = [];
    if (def.tech == null) def.tech = 1;
    if (def.buildTime == null) def.buildTime = null;   // derived from cost
    return def;
  }

  DUNE.STRUCTS = {

    /* ------------------------------ ground ----------------------------- */
    concrete: S({
      id: 'concrete', name: 'Concrete Slab', short: 'SLAB',
      w: 1, h: 1, cost: 5, hp: 400, tech: 1,
      requires: ['construction'],
      foundation: true, sight: 0,
      desc: 'Prepared rockcrete. Buildings raised on slabs come up at full strength; ' +
            'anything founded on open sand is eaten by the desert.'
    }),

    concrete4: S({
      id: 'concrete4', name: 'Concrete Slab (4)', short: 'SLAB4',
      w: 2, h: 2, cost: 16, hp: 400, tech: 3,
      requires: ['construction'],
      foundation: true, sight: 0,
      desc: 'Four slabs poured at once. Lay these before every serious structure.'
    }),

    /* ---------------------------- core base ---------------------------- */
    construction: S({
      id: 'construction', name: 'Construction Yard', short: 'CONYARD',
      /* Draws no power: a lone Construction Yard has to be able to raise its
         first Windtrap at full speed. */
      w: 2, h: 2, cost: 600, hp: 1800, power: 0, sight: 6, tech: 1,
      primary: true,
      produces: 'structure',
      storage: 1500,          // the yard's own spice bunker
      desc: 'The heart of any base. Everything you will ever build is ordered here, ' +
            'then placed by hand on the sand.'
    }),

    windtrap: S({
      id: 'windtrap', name: 'Windtrap', short: 'WINDTRAP',
      w: 2, h: 2, cost: 300, hp: 900, power: 110, tech: 1,
      requires: ['construction'],
      desc: 'Condenses moisture and drives turbines. Every other structure draws ' +
            'from the grid — run short and the whole base slows to a crawl.'
    }),

    refinery: S({
      id: 'refinery', name: 'Spice Refinery', short: 'REFINERY',
      w: 3, h: 2, cost: 400, hp: 1500, power: -35, sight: 5, tech: 1,
      requires: ['windtrap'],
      storage: 1000,
      dock: { x: 1, y: 2 },           // tile (relative) a harvester backs into
      freeUnit: 'harvester',
      desc: 'Cracks raw melange into credits. Arrives with a Harvester. Adds 1000 ' +
            'units of spice storage.'
    }),

    silo: S({
      id: 'silo', name: 'Spice Silo', short: 'SILO',
      w: 2, h: 2, cost: 150, hp: 800, power: -10, tech: 2,
      requires: ['refinery'],
      storage: 1000,
      desc: 'Holds 1000 more units of spice. Harvest beyond your storage and the ' +
            'overflow blows away.'
    }),

    /* ---------------------------- infantry ----------------------------- */
    barracks: S({
      id: 'barracks', name: 'Barracks', short: 'BARRACKS',
      w: 2, h: 2, cost: 300, hp: 1000, power: -12, tech: 1,
      requires: ['windtrap'],
      houses: ['atreides', 'ordos'],
      produces: 'barracks',
      exit: { x: 2, y: 1 },
      desc: 'Trains light infantry. House Harkonnen has no use for riflemen.'
    }),

    wor: S({
      id: 'wor', name: 'WOR Trooper Facility', short: 'WOR',
      w: 2, h: 2, cost: 400, hp: 1000, power: -20, tech: 2,
      requires: ['windtrap'],
      houses: ['harkonnen', 'ordos', 'sardaukar'],
      produces: 'wor',
      exit: { x: 2, y: 1 },
      desc: 'Drills rocket Troopers. Slow, but they open tanks like ration tins.'
    }),

    /* ---------------------------- factories ---------------------------- */
    lightfactory: S({
      id: 'lightfactory', name: 'Light Factory', short: 'LIGHT FAC',
      w: 2, h: 2, cost: 400, hp: 1000, power: -20, tech: 2,
      requires: ['refinery'],
      produces: 'lightfactory',
      exit: { x: 2, y: 1 },
      desc: 'Builds wheeled vehicles — scouts and raiders.'
    }),

    radar: S({
      id: 'radar', name: 'Radar Outpost', short: 'OUTPOST',
      w: 2, h: 2, cost: 400, hp: 1000, power: -30, sight: 9, tech: 3,
      requires: ['refinery'],
      radar: true,
      desc: 'Brings the battlefield radar online — but only while the grid holds. ' +
            'Cut the power and you are blind.'
    }),

    heavyfactory: S({
      id: 'heavyfactory', name: 'Heavy Factory', short: 'HEAVY FAC',
      w: 3, h: 2, cost: 600, hp: 1300, power: -35, tech: 4,
      requires: ['lightfactory', 'radar'],
      produces: 'heavyfactory',
      exit: { x: 3, y: 1 },
      desc: 'Tracked hulls: harvesters, combat tanks and everything heavier.'
    }),

    repair: S({
      id: 'repair', name: 'Repair Facility', short: 'REPAIR',
      w: 3, h: 2, cost: 700, hp: 1400, power: -30, tech: 5,
      requires: ['heavyfactory'],
      dock: { x: 1, y: 2 },
      desc: 'Damaged vehicles drive in and come out whole, for a price in credits.'
    }),

    hightech: S({
      id: 'hightech', name: 'High-Tech Factory', short: 'HI-TECH',
      w: 2, h: 2, cost: 500, hp: 1100, power: -35, tech: 5,
      requires: ['radar', 'heavyfactory'],
      produces: 'hightech',
      exit: { x: 1, y: 2 },
      air: true,
      desc: 'Aircraft assembly. Carryalls to keep the spice flowing, and for the ' +
            'Atreides, Ornithopters.'
    }),

    starport: S({
      id: 'starport', name: 'Starport', short: 'STARPORT',
      w: 3, h: 3, cost: 500, hp: 1200, power: -45, sight: 6, tech: 6,
      requires: ['refinery', 'heavyfactory'],
      produces: 'starport',
      exit: { x: 1, y: 3 },
      discount: true,
      desc: 'Order hardware direct from the Guild. Cheaper than building it, but ' +
            'the frigate takes its time.'
    }),

    ix: S({
      id: 'ix', name: 'House IX Research', short: 'IX',
      w: 2, h: 2, cost: 500, hp: 1000, power: -40, tech: 7,
      requires: ['hightech', 'repair'],
      desc: 'Ixian technicians unlock your House’s forbidden weapon.'
    }),

    palace: S({
      id: 'palace', name: 'Palace', short: 'PALACE',
      w: 3, h: 3, cost: 999, hp: 2200, power: -60, sight: 7, tech: 8,
      requires: ['ix'],
      unique: true,
      desc: 'The seat of your House on Arrakis. Grants a recharging weapon that ' +
            'no rival can answer.'
    }),

    /* ---------------------------- defences ----------------------------- */
    turret: S({
      id: 'turret', name: 'Gun Turret', short: 'GUN TURRET',
      w: 1, h: 1, cost: 125, hp: 800, power: -12, sight: 7, tech: 3,
      requires: ['radar'],
      weapon: 'turretgun',
      turret: true, traverse: 1.15,
      desc: 'A slow-traversing cannon. Deadly in front of it, useless behind it — ' +
            'cover its blind arc with a second turret.'
    }),

    rturret: S({
      id: 'rturret', name: 'Rocket Turret', short: 'RKT TURRET',
      w: 1, h: 1, cost: 250, hp: 900, power: -25, sight: 9, tech: 5,
      requires: ['radar', 'heavyfactory'],
      weapon: 'turretrocket',
      turret: true, traverse: 0.85, needsPower: true,
      desc: 'Long-ranged rockets that also reach aircraft. Needs real power behind ' +
            'it — in a brown-out it barely turns.'
    })
  };

  /* Display order on the Construction Yard list. */
  DUNE.STRUCT_ORDER = [
    'concrete', 'concrete4', 'windtrap', 'refinery', 'silo',
    'barracks', 'wor', 'lightfactory', 'radar', 'turret',
    'heavyfactory', 'rturret', 'repair', 'hightech', 'starport',
    'ix', 'palace', 'construction'
  ];

  /** Footprint tiles of a structure def placed at tx,ty. */
  DUNE.footprint = function (def, tx, ty, out) {
    out = out || [];
    out.length = 0;
    for (var y = 0; y < def.h; y++) {
      for (var x = 0; x < def.w; x++) out.push([tx + x, ty + y]);
    }
    return out;
  };

  /** True if `house` is permitted to raise `def`. */
  DUNE.houseAllowsStruct = function (def, houseId) {
    if (!def.houses) return true;
    return def.houses.indexOf(houseId) >= 0;
  };

  /** Human readable prerequisite line for the sidebar tooltip. */
  DUNE.structRequirementText = function (def) {
    if (!def.requires.length) return '';
    return def.requires.map(function (r) {
      return DUNE.STRUCTS[r] ? DUNE.STRUCTS[r].name : r;
    }).join(' + ');
  };
})();
"},{"path":"js/data/units.js","type":"text/javascript","text":"/* =============================================================================
   units.js - weapons and the per-House unit rosters.

   `from` is the structure that builds it, `requires` are extra structures that
   must be standing, `houses` restricts the unit. The three playable Houses end
   up with genuinely different armies, not recoloured copies.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var A = DUNE.ARMOUR;

  /* ------------------------------- weapons ------------------------------ */
  /* range is in tiles; rof is seconds between shots; arc is the firing
     tolerance in radians (the turret must be lined up this closely). */
  DUNE.WEAPONS = {
    rifle:        { name: 'Assault Rifle', dmg: 9,   range: 3.6, rof: 0.75, warhead: 'small',  proj: 'bullet', pspeed: 640, arc: 0.45, traverse: 7,   sfx: 'rifle', burst: 2, air: true },
    smg:          { name: 'Sub-machinegun',dmg: 7,   range: 3.2, rof: 0.55, warhead: 'small',  proj: 'bullet', pspeed: 640, arc: 0.5,  traverse: 7,   sfx: 'rifle', burst: 3, air: true },
    fremenrifle:  { name: 'Maula Pistol',  dmg: 14,  range: 4.2, rof: 0.8,  warhead: 'small',  proj: 'bullet', pspeed: 680, arc: 0.45, traverse: 7,   sfx: 'rifle', burst: 2, air: true },
    troopRocket:  { name: 'Shoulder Rocket',dmg: 28, range: 5.0, rof: 2.0,  warhead: 'rocket', proj: 'rocket', pspeed: 250, arc: 0.3,  traverse: 4,   sfx: 'rocket', air: true },
    mg:           { name: 'Heavy MG',      dmg: 11,  range: 4.0, rof: 0.4,  warhead: 'small',  proj: 'bullet', pspeed: 700, arc: 0.4,  traverse: 6,   sfx: 'rifle', air: true },
    quadcannon:   { name: 'Twin Cannon',   dmg: 18,  range: 4.4, rof: 0.9,  warhead: 'ap',     proj: 'bullet', pspeed: 620, arc: 0.3,  traverse: 4.5, sfx: 'rifle', burst: 2 },
    tankgun:      { name: '90mm Cannon',   dmg: 46,  range: 5.0, rof: 1.7,  warhead: 'ap',     proj: 'shell',  pspeed: 430, arc: 0.12, traverse: 1.9, sfx: 'cannon', splash: 0.4 },
    siegegun:     { name: '155mm Howitzer',dmg: 72,  range: 6.6, rof: 2.6,  warhead: 'he',     proj: 'shell',  pspeed: 320, arc: 0.09, traverse: 1.1, sfx: 'cannon', splash: 1.3, minRange: 1.6 },
    launcher:     { name: 'Rocket Pod',    dmg: 58,  range: 8.2, rof: 2.9,  warhead: 'rocket', proj: 'rocket', pspeed: 260, arc: 0.14, traverse: 1.5, sfx: 'rocket', splash: 1.1, minRange: 2.2, air: true },
    devcannon:    { name: 'Twin 120mm',    dmg: 62,  range: 5.2, rof: 2.1,  warhead: 'he',     proj: 'shell',  pspeed: 380, arc: 0.11, traverse: 1.0, sfx: 'cannon', splash: 1.0, burst: 2 },
    sonic:        { name: 'Sonic Blast',   dmg: 44,  range: 6.0, rof: 2.2,  warhead: 'sonic',  proj: 'sonic',  pspeed: 520, arc: 0.1,  traverse: 1.6, sfx: 'sonic', beam: true },
    deviate:      { name: 'Deviator Gas',  dmg: 0,   range: 6.0, rof: 4.5,  warhead: 'ap',     proj: 'gas',    pspeed: 300, arc: 0.14, traverse: 1.6, sfx: 'zap', deviate: 22, splash: 0.8 },
    orniRocket:   { name: 'Air-to-Ground', dmg: 34,  range: 4.6, rof: 1.5,  warhead: 'rocket', proj: 'rocket', pspeed: 380, arc: 0.6,  traverse: 9,   sfx: 'rocket' },
    turretgun:    { name: 'Turret Cannon', dmg: 52,  range: 6.0, rof: 1.6,  warhead: 'ap',     proj: 'shell',  pspeed: 460, arc: 0.10, traverse: 1.15, sfx: 'cannon', splash: 0.4 },
    turretrocket: { name: 'Turret Rockets',dmg: 55,  range: 8.5, rof: 2.4,  warhead: 'rocket', proj: 'rocket', pspeed: 300, arc: 0.13, traverse: 0.85, sfx: 'rocket', splash: 0.9, air: true },
    deathhand:    { name: 'Death Hand',    dmg: 900, range: 999, rof: 999,  warhead: 'nuke',   proj: 'nuke',   pspeed: 150, arc: 6.3,  traverse: 9,   sfx: 'bigboom', splash: 5.5 }
  };

  /* -------------------------------- units ------------------------------- */
  function U(def) {
    def.kind = 'unit';
    if (def.sight == null) def.sight = 5;
    if (!def.requires) def.requires = [];
    if (def.tech == null) def.tech = 1;
    if (def.armour == null) def.armour = A.LIGHT;
    if (def.move == null) def.move = 'track';
    if (def.turret == null) def.turret = false;
    return def;
  }

  DUNE.UNITS = {

    /* ----------------------------- infantry ---------------------------- */
    infantry: U({
      id: 'infantry', name: 'Light Infantry', short: 'INFANTRY',
      cost: 60, hp: 55, speed: 0.95, armour: A.NONE, move: 'foot', sight: 5,
      from: 'barracks', weapon: 'rifle', squad: 3, tech: 1,
      houses: ['atreides', 'ordos'],
      desc: 'Cheap riflemen. Useless against armour, murderous against other infantry, ' +
            'and the only troops that can climb the rock spines.'
    }),

    trooper: U({
      id: 'trooper', name: 'Trooper', short: 'TROOPER',
      cost: 100, hp: 75, speed: 0.80, armour: A.NONE, move: 'foot', sight: 5,
      from: 'wor', weapon: 'troopRocket', squad: 2, tech: 2,
      houses: ['harkonnen', 'ordos', 'sardaukar'],
      desc: 'Shoulder-launched rockets. Slow, fragile, and the cheapest answer to a ' +
            'tank column you will ever find.'
    }),

    fremen: U({
      id: 'fremen', name: 'Fremen', short: 'FREMEN',
      cost: 0, hp: 110, speed: 1.35, armour: A.NONE, move: 'foot', sight: 8,
      weapon: 'fremenrifle', squad: 3, noBuild: true, houses: ['atreides'],
      wormSafe: true,
      desc: 'Desert people. They ride the worms rather than fear them.'
    }),

    saboteur: U({
      id: 'saboteur', name: 'Saboteur', short: 'SABOTEUR',
      cost: 0, hp: 60, speed: 1.6, armour: A.NONE, move: 'foot', sight: 6,
      noBuild: true, houses: ['ordos'], stealth: true, suicide: true,
      desc: 'Walks up to a building and stops existing. So does the building.'
    }),

    /* ------------------------------ wheeled ---------------------------- */
    trike: U({
      id: 'trike', name: 'Trike', short: 'TRIKE',
      cost: 150, hp: 110, speed: 3.0, armour: A.LIGHT, move: 'wheel', sight: 7,
      from: 'lightfactory', weapon: 'mg', tech: 2, crush: true,
      houses: ['atreides', 'harkonnen', 'sardaukar'],
      desc: 'Fast three-wheeled scout with a pintle gun. Runs infantry down.'
    }),

    raider: U({
      id: 'raider', name: 'Raider Trike', short: 'RAIDER',
      cost: 150, hp: 90, speed: 3.9, armour: A.LIGHT, move: 'wheel', sight: 8,
      from: 'lightfactory', weapon: 'mg', tech: 2, crush: true,
      houses: ['ordos'],
      desc: 'Ordos-tuned Trike. Faster than anything else with wheels, and made of ' +
            'about as much armour as a rumour.'
    }),

    quad: U({
      id: 'quad', name: 'Quad', short: 'QUAD',
      cost: 200, hp: 145, speed: 2.2, armour: A.LIGHT, move: 'wheel', sight: 6,
      from: 'lightfactory', weapon: 'quadcannon', tech: 2, crush: true,
      desc: 'Four-wheeled gun platform. Slower than a Trike, hits far harder.'
    }),

    /* ------------------------------ tracked ---------------------------- */
    harvester: U({
      id: 'harvester', name: 'Harvester', short: 'HARVESTER',
      cost: 300, hp: 900, speed: 1.15, armour: A.HEAVY, move: 'track', sight: 5,
      from: 'heavyfactory', tech: 1, harvester: true, crush: true,
      desc: 'Drives onto a spice field, fills its hopper, and drives the load back ' +
            'to a Refinery. It is your entire economy on four treads.'
    }),

    tank: U({
      id: 'tank', name: 'Combat Tank', short: 'TANK',
      cost: 300, hp: 320, speed: 1.55, armour: A.HEAVY, move: 'track', sight: 6,
      from: 'heavyfactory', weapon: 'tankgun', turret: true, tech: 4, crush: true,
      desc: 'The line of battle. Turret traverses slowly — flank it and it cannot ' +
            'answer you in time.'
    }),

    siege: U({
      id: 'siege', name: 'Siege Tank', short: 'SIEGE',
      cost: 450, hp: 420, speed: 1.15, armour: A.HEAVY, move: 'track', sight: 7,
      from: 'heavyfactory', weapon: 'siegegun', turret: true, tech: 5, crush: true,
      requires: ['hightech'],
      desc: 'Outranges everything short of rockets and flattens buildings, but it ' +
            'cannot depress its gun onto anything close.'
    }),

    rocketlauncher: U({
      id: 'rocketlauncher', name: 'Missile Launcher', short: 'LAUNCHER',
      cost: 450, hp: 260, speed: 1.35, armour: A.LIGHT, move: 'track', sight: 8,
      from: 'heavyfactory', weapon: 'launcher', turret: true, tech: 6,
      requires: ['hightech'],
      desc: 'Enormous reach, paper armour, and it cannot defend itself up close. ' +
            'Keep tanks in front of it.'
    }),

    mcv: U({
      id: 'mcv', name: 'MCV', short: 'MCV',
      cost: 900, hp: 550, speed: 0.95, armour: A.HEAVY, move: 'track', sight: 6,
      from: 'heavyfactory', tech: 6, deploy: 'construction',
      requires: ['repair'],
      desc: 'Mobile Construction Vehicle. Deploy it beside a fresh spice field to ' +
            'found a second base.'
    }),

    /* ----------------------------- House unique ------------------------ */
    sonictank: U({
      id: 'sonictank', name: 'Sonic Tank', short: 'SONIC',
      cost: 600, hp: 400, speed: 1.35, armour: A.HEAVY, move: 'track', sight: 7,
      from: 'heavyfactory', weapon: 'sonic', turret: true, tech: 7,
      requires: ['ix'], houses: ['atreides'],
      desc: 'Atreides sound weapon. The beam carries straight through everything in ' +
            'its path — including your own troops.'
    }),

    devastator: U({
      id: 'devastator', name: 'Devastator', short: 'DEVASTATOR',
      cost: 800, hp: 700, speed: 0.85, armour: A.HEAVY, move: 'track', sight: 6,
      from: 'heavyfactory', weapon: 'devcannon', turret: true, tech: 7,
      requires: ['ix'], houses: ['harkonnen'], crush: true, selfDestruct: true,
      desc: 'Harkonnen siege armour with twin 120mm guns. Can be ordered to detonate ' +
            'its atomic core rather than be captured.'
    }),

    deviator: U({
      id: 'deviator', name: 'Deviator', short: 'DEVIATOR',
      cost: 750, hp: 340, speed: 1.45, armour: A.LIGHT, move: 'track', sight: 7,
      from: 'heavyfactory', weapon: 'deviate', turret: true, tech: 7,
      requires: ['ix'], houses: ['ordos'],
      desc: 'Fires a nerve gas that turns an enemy vehicle to your side for a while. ' +
            'Ordos never pay for what they can borrow.'
    }),

    /* -------------------------------- air ------------------------------ */
    carryall: U({
      id: 'carryall', name: 'Carryall', short: 'CARRYALL',
      cost: 800, hp: 220, speed: 4.6, armour: A.AIR, move: 'air', sight: 8,
      from: 'hightech', tech: 5, carrier: true,
      desc: 'Lifts full Harvesters straight back to the Refinery and returns them to ' +
            'the field. Doubles the throughput of a distant spice patch.'
    }),

    ornithopter: U({
      id: 'ornithopter', name: 'Ornithopter', short: 'THOPTER',
      cost: 600, hp: 160, speed: 6.0, armour: A.AIR, move: 'air', sight: 9,
      from: 'hightech', weapon: 'orniRocket', tech: 7,
      requires: ['ix'], houses: ['atreides'],
      desc: 'Atreides strike flyer. Makes a pass, empties its racks, and goes home ' +
            'to rearm. Nothing on the ground is safe and nothing it meets is fast enough.'
    })
  };

  /* Order shown on the units list. */
  DUNE.UNIT_ORDER = [
    'infantry', 'trooper', 'trike', 'raider', 'quad',
    'harvester', 'tank', 'siege', 'rocketlauncher',
    'sonictank', 'devastator', 'deviator',
    'carryall', 'ornithopter', 'mcv'
  ];

  /* Items the Starport stocks, in delivery-menu order. */
  DUNE.STARPORT_STOCK = [
    'infantry', 'trooper', 'trike', 'raider', 'quad',
    'harvester', 'tank', 'siege', 'rocketlauncher', 'carryall'
  ];

  DUNE.houseAllowsUnit = function (def, houseId) {
    if (def.noBuild) return false;
    if (!def.houses) return true;
    return def.houses.indexOf(houseId) >= 0;
  };

  /** Defensive/offensive value used by the AI when sizing an attack wave. */
  DUNE.combatValue = function (def) {
    if (!def.weapon) return 0;
    var w = DUNE.WEAPONS[def.weapon];
    return (def.hp / 100) + (w.dmg / w.rof) / 12;
  };

  DUNE.def = function (id) { return DUNE.UNITS[id] || DUNE.STRUCTS[id]; };
})();
"},{"path":"js/entities/effects.js","type":"text/javascript","text":"/* =============================================================================
   effects.js - explosions, sand plumes, smoke, tracers and floating text.
   Pure particles; the renderer just walks the list.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util;

  function Effects(world) {
    this.world = world;
    this.parts = [];
    this.texts = [];
    this.beams = [];
    this.scorch = [];       // long-lived ground marks
    this.shake = 0;
  }

  Effects.prototype.clear = function () {
    this.parts.length = 0; this.texts.length = 0;
    this.beams.length = 0; this.scorch.length = 0;
    this.shake = 0;
  };

  Effects.prototype._p = function (p) {
    if (this.parts.length > 1400) this.parts.shift();
    this.parts.push(p);
  };

  /* ------------------------------ explosions ---------------------------- */
  Effects.prototype.explosion = function (x, y, size, colour) {
    size = size || 1;
    var n = Math.round(8 + size * 9);
    for (var i = 0; i < n; i++) {
      var a = Math.random() * U.TAU;
      var sp = (30 + Math.random() * 120) * size;
      this._p({
        type: 'fire', x: x, y: y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: 0.28 + Math.random() * 0.4 * size, max: 0.28 + 0.4 * size,
        r: (3 + Math.random() * 6) * size,
        c: colour || null, drag: 2.6
      });
    }
    for (var s = 0; s < Math.round(3 + size * 3); s++) {
      var aa = Math.random() * U.TAU;
      this._p({
        type: 'smoke', x: x, y: y,
        vx: Math.cos(aa) * 18 * size, vy: Math.sin(aa) * 18 * size - 12,
        life: 0.9 + Math.random() * 1.1, max: 2,
        r: (5 + Math.random() * 8) * size, drag: 1.2
      });
    }
    this.shake = Math.min(14, this.shake + size * 2.4);
    if (size > 1.2) this.scorchMark(x, y, size * 7);
  };

  Effects.prototype.scorchMark = function (x, y, r) {
    if (this.scorch.length > 220) this.scorch.shift();
    this.scorch.push({ x: x, y: y, r: r, a: 0.42 });
  };

  Effects.prototype.sandBurst = function (x, y, size) {
    size = size || 14;
    for (var i = 0; i < size; i++) {
      var a = Math.random() * U.TAU;
      var sp = 20 + Math.random() * 90;
      this._p({
        type: 'sand', x: x, y: y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30,
        life: 0.5 + Math.random() * 0.6, max: 1.1,
        r: 2 + Math.random() * 4, drag: 1.8
      });
    }
  };

  Effects.prototype.dust = function (x, y, n) {
    for (var i = 0; i < (n || 1); i++) {
      this._p({
        type: 'dust', x: x + (Math.random() - 0.5) * 6, y: y + (Math.random() - 0.5) * 6,
        vx: (Math.random() - 0.5) * 14, vy: (Math.random() - 0.5) * 14 - 6,
        life: 0.4 + Math.random() * 0.5, max: 0.9,
        r: 2 + Math.random() * 3, drag: 1.4
      });
    }
  };

  Effects.prototype.smokeTrail = function (x, y) {
    this._p({
      type: 'smoke', x: x, y: y,
      vx: (Math.random() - 0.5) * 10, vy: -8 - Math.random() * 10,
      life: 0.45 + Math.random() * 0.5, max: 0.95,
      r: 2 + Math.random() * 3, drag: 1.0
    });
  };

  /** Continuous damage smoke from a hurt building or vehicle. */
  Effects.prototype.damageSmoke = function (x, y, intensity) {
    if (Math.random() > intensity * 0.6) return;
    this._p({
      type: 'smoke', x: x + (Math.random() - 0.5) * 10, y: y + (Math.random() - 0.5) * 8,
      vx: (Math.random() - 0.5) * 8, vy: -16 - Math.random() * 14,
      life: 1.0 + Math.random() * 1.0, max: 2.0,
      r: 3 + Math.random() * 4, drag: 0.7
    });
  };

  Effects.prototype.muzzle = function (x, y, angle, size) {
    this._p({
      type: 'flash', x: x, y: y, a: angle,
      life: 0.07, max: 0.07, r: (size || 1) * 6
    });
  };

  Effects.prototype.spark = function (x, y, n) {
    for (var i = 0; i < (n || 4); i++) {
      var a = Math.random() * U.TAU;
      this._p({
        type: 'spark', x: x, y: y,
        vx: Math.cos(a) * (40 + Math.random() * 90), vy: Math.sin(a) * (40 + Math.random() * 90),
        life: 0.12 + Math.random() * 0.18, max: 0.3, r: 1.4, drag: 3
      });
    }
  };

  /* -------------------------------- beams -------------------------------- */
  Effects.prototype.beam = function (x1, y1, x2, y2, colour, width, dur) {
    this.beams.push({
      x1: x1, y1: y1, x2: x2, y2: y2,
      c: colour || '#9fe8ff', w: width || 4,
      life: dur || 0.22, max: dur || 0.22
    });
  };

  /* ------------------------------ float text ----------------------------- */
  Effects.prototype.text = function (x, y, str, colour) {
    if (this.texts.length > 40) this.texts.shift();
    this.texts.push({ x: x, y: y, s: str, c: colour || '#f0d7a6', life: 1.4, max: 1.4 });
  };

  /* -------------------------------- update ------------------------------- */
  Effects.prototype.update = function (dt) {
    var p, i;
    for (i = this.parts.length - 1; i >= 0; i--) {
      p = this.parts[i];
      p.life -= dt;
      if (p.life <= 0) { this.parts.splice(i, 1); continue; }
      p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.drag) {
        var f = Math.max(0, 1 - p.drag * dt);
        p.vx *= f; p.vy *= f;
      }
      if (p.type === 'smoke') p.vy -= 6 * dt;
      if (p.type === 'sand') p.vy += 60 * dt;
    }
    for (i = this.texts.length - 1; i >= 0; i--) {
      var t = this.texts[i];
      t.life -= dt; t.y -= 22 * dt;
      if (t.life <= 0) this.texts.splice(i, 1);
    }
    for (i = this.beams.length - 1; i >= 0; i--) {
      var b = this.beams[i];
      b.life -= dt;
      if (b.life <= 0) this.beams.splice(i, 1);
    }
    for (i = this.scorch.length - 1; i >= 0; i--) {
      var s = this.scorch[i];
      s.a -= dt * 0.012;
      if (s.a <= 0.02) this.scorch.splice(i, 1);
    }
    if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 22);
  };

  DUNE.Effects = Effects;
})();
"},{"path":"js/entities/projectile.js","type":"text/javascript","text":"/* =============================================================================
   projectile.js - bullets, shells, rockets, sonic waves, deviator gas and the
   Death Hand. Rockets track their target; shells fly ballistically and can
   miss a mover; sonic waves cut straight through everything in the line.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  /**
   * @param {object} o {world, x, y, target, tx, ty, weapon, owner, faction, dmg}
   */
  function Projectile(o) {
    this.world = o.world;
    this.x = o.x; this.y = o.y;
    this.z = o.z || 0;
    this.weapon = o.weapon;
    this.kind = o.weapon.proj;
    this.owner = o.owner;
    this.faction = o.faction;
    this.target = o.target || null;
    this.dmg = o.dmg != null ? o.dmg : o.weapon.dmg;
    this.alive = true;
    this.life = 6;
    this.trail = [];

    var gx = this.target ? this.target.x : o.tx;
    var gy = this.target ? this.target.y : o.ty;
    this.gx = gx; this.gy = gy;
    this.angle = U.angleTo(this.x, this.y, gx, gy);
    this.speed = o.weapon.pspeed;

    if (this.kind === 'shell' || this.kind === 'nuke') {
      // ballistic: lock the impact point at launch, so movers can dodge
      this.gx = gx; this.gy = gy;
      this.startX = this.x; this.startY = this.y;
      this.dist = U.dist(this.x, this.y, gx, gy);
      this.travelled = 0;
      this.arc = this.kind === 'nuke' ? 130 : Math.min(26, this.dist * 0.12);
      if (this.kind === 'nuke') this.speed = o.weapon.pspeed;
    }
    if (this.kind === 'sonic') {
      this.life = 0.9;
      this.maxRange = o.weapon.range * CFG.TILE;
      this.hitSet = [];
    }
  }

  Projectile.prototype.update = function (dt) {
    this.life -= dt;
    if (this.life <= 0) { this.detonate(); return; }

    switch (this.kind) {
      case 'bullet':   this.stepDirect(dt, 0); break;
      case 'rocket':   this.stepDirect(dt, 4.2); break;
      case 'gas':      this.stepDirect(dt, 3.0); break;
      case 'shell':    this.stepBallistic(dt); break;
      case 'nuke':     this.stepBallistic(dt); break;
      case 'sonic':    this.stepSonic(dt); break;
      default:         this.stepDirect(dt, 0); break;
    }
  };

  /** Straight or homing flight. `turn` > 0 makes it track the target. */
  Projectile.prototype.stepDirect = function (dt, turn) {
    if (turn > 0 && this.target && this.target.alive) {
      var want = U.angleTo(this.x, this.y, this.target.x, this.target.y);
      this.angle = U.rotToward(this.angle, want, turn * dt);
    }
    var dx = Math.cos(this.angle) * this.speed * dt;
    var dy = Math.sin(this.angle) * this.speed * dt;
    this.x += dx; this.y += dy;

    if (this.kind === 'rocket' || this.kind === 'gas') {
      this.world.effects.smokeTrail(this.x, this.y);
    }

    // hit test against the intended victim first, then anything in the way
    var hit = this.checkHit();
    if (hit) { this.target = hit; this.detonate(); return; }

    if (this.target && this.target.alive) {
      if (U.dist(this.x, this.y, this.target.x, this.target.y) < 5) this.detonate();
    } else if (U.dist(this.x, this.y, this.gx, this.gy) < 7) {
      this.detonate();
    }
    if (this.outOfBounds()) { this.alive = false; }
  };

  Projectile.prototype.stepBallistic = function (dt) {
    var step = this.speed * dt;
    this.travelled += step;
    var t = this.dist <= 0 ? 1 : U.clamp(this.travelled / this.dist, 0, 1);
    this.x = U.lerp(this.startX, this.gx, t);
    this.y = U.lerp(this.startY, this.gy, t);
    this.z = Math.sin(t * Math.PI) * this.arc;
    if (this.kind === 'nuke') this.world.effects.smokeTrail(this.x, this.y + this.z * 0.2);
    if (t >= 1) this.detonate();
  };

  /** The sonic wave damages everything it passes over, friend or foe. */
  Projectile.prototype.stepSonic = function (dt) {
    var step = this.speed * dt;
    var nx = this.x + Math.cos(this.angle) * step;
    var ny = this.y + Math.sin(this.angle) * step;
    var world = this.world;
    var list = world.entitiesInRadius((this.x + nx) / 2, (this.y + ny) / 2, step * 0.6 + 12);
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (e === this.owner) continue;
      if (this.hitSet.indexOf(e) >= 0) continue;
      if (e.def.move === 'air') continue;
      this.hitSet.push(e);
      DUNE.Combat.applyDamage(e, this.dmg, this.weapon.warhead, this.owner, world);
      world.effects.spark(e.x, e.y, 3);
    }
    this.x = nx; this.y = ny;
    this.travelled = (this.travelled || 0) + step;
    if (this.travelled >= this.maxRange || this.outOfBounds()) this.alive = false;
  };

  Projectile.prototype.outOfBounds = function () {
    var m = this.world.map;
    return this.x < -40 || this.y < -40 ||
           this.x > m.w * CFG.TILE + 40 || this.y > m.h * CFG.TILE + 40;
  };

  /** Anything hostile sitting on the projectile right now. */
  Projectile.prototype.checkHit = function () {
    var list = this.world.entitiesInRadius(this.x, this.y, 9);
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (e === this.owner) continue;
      // direct-fire rounds pass over friendly and allied heads
      if (!this.faction.isEnemyOf(e.faction)) continue;
      if (e.def.move === 'air' && !this.weapon.air) continue;
      if (e.hidden) continue;
      return e;
    }
    return null;
  };

  Projectile.prototype.detonate = function () {
    if (!this.alive) return;
    this.alive = false;
    var world = this.world, w = this.weapon;

    if (w.deviate) {
      // deviator gas - flips a vehicle rather than damaging it
      var victims = world.entitiesInRadius(this.x, this.y, (w.splash || 0.5) * CFG.TILE);
      for (var d = 0; d < victims.length; d++) {
        var v = victims[d];
        if (v.kind !== 'unit' || !this.faction.isEnemyOf(v.faction)) continue;
        if (v.def.move === 'foot' || v.def.move === 'air') continue;
        v.deviate(this.faction, w.deviate);
      }
      world.effects.explosion(this.x, this.y, 0.7, '#7ef0c0');
      DUNE.Sfx.play('zap', 0.8, world.audioDist(this.x, this.y));
      return;
    }

    var splash = w.splash || 0;
    if (splash > 0) {
      var r = splash * CFG.TILE;
      var list = world.entitiesInRadius(this.x, this.y, r + 8);
      for (var i = 0; i < list.length; i++) {
        var e = list[i];
        if (e.def.move === 'air' && !w.air) continue;
        var dist = U.dist(this.x, this.y, e.x, e.y);
        var falloff = U.clamp(1 - dist / (r + 10), 0.12, 1);
        // splash hurts everyone, which is why you keep launchers behind the line
        DUNE.Combat.applyDamage(e, this.dmg * falloff, w.warhead, this.owner, world);
      }
    } else if (this.target && this.target.alive) {
      if (U.dist(this.x, this.y, this.target.x, this.target.y) < 22) {
        DUNE.Combat.applyDamage(this.target, this.dmg, w.warhead, this.owner, world);
      }
    }

    // worms hate being shot at
    for (var k = 0; k < world.worms.length; k++) {
      var wm = world.worms[k];
      if (U.dist(this.x, this.y, wm.x, wm.y) < CFG.TILE * 1.2) wm.hit(this.dmg);
    }

    var size = this.kind === 'nuke' ? 6 : (splash > 0 ? 0.8 + splash * 0.8 : 0.55);
    world.effects.explosion(this.x, this.y, size);
    if (this.kind === 'nuke') {
      DUNE.Sfx.play('bigboom', 1, world.audioDist(this.x, this.y));
      world.effects.shake = 26;
    } else if (splash > 0.6) {
      DUNE.Sfx.play('explode', 0.7, world.audioDist(this.x, this.y));
    }
  };

  DUNE.Projectile = Projectile;
})();
"},{"path":"js/entities/structure.js","type":"text/javascript","text":"/* =============================================================================
   structure.js - buildings.

   Placement rules live here too: a structure must touch the existing base, and
   whatever part of its footprint is not sitting on concrete slabs will be
   ground away by the sand until somebody repairs it.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  function Structure(world, defId, faction, tx, ty) {
    var def = DUNE.STRUCTS[defId];
    this.world = world;
    this.kind = 'structure';
    this.def = def;
    this.id = world.nextId++;
    this.faction = faction;
    this.tx = tx; this.ty = ty;
    this.w = def.w; this.h = def.h;
    this.x = tx * CFG.TILE + def.w * CFG.TILE / 2;
    this.y = ty * CFG.TILE + def.h * CFG.TILE / 2;

    var mods = faction.mods;
    this.maxHp = Math.round(def.hp * mods.hp);
    this.sight = def.sight * mods.sight;

    this.concreteTiles = 0;
    this.footTiles = def.w * def.h;
    this.alive = true;
    this.building = true;          // rising out of the sand
    this.riseT = 0;
    this.riseTime = 1.1;
    this.repairing = false;
    this.selected = false;
    this.rally = null;
    this.dockUnit = null;
    this.dockTimer = 0;
    this.primary = false;          // preferred factory of its type

    // turret state
    this.turretAngle = -Math.PI / 2;
    this.cooldown = 0;
    this.target = null;
    this.retarget = 0;
    this.burstLeft = 0;
    this.burstTimer = 0;

    this.decayAcc = 0;
    this.damageFlash = 0;
    this.lastHitBy = null;
    this.lastHitAt = -99;

    this.claimTiles();
    this.hp = Math.round(this.maxHp * this.startHpFraction());
  }

  /* --------------------------- map bookkeeping --------------------------- */
  Structure.prototype.claimTiles = function () {
    var map = this.world.map, n = 0;
    for (var y = 0; y < this.h; y++) {
      for (var x = 0; x < this.w; x++) {
        var i = (this.ty + y) * map.w + (this.tx + x);
        map.building[i] = this.id;
        if (map.concrete[i]) n++;
      }
    }
    this.concreteTiles = n;
  };

  Structure.prototype.releaseTiles = function () {
    var map = this.world.map;
    for (var y = 0; y < this.h; y++) {
      for (var x = 0; x < this.w; x++) {
        var i = (this.ty + y) * map.w + (this.tx + x);
        if (map.building[i] === this.id) map.building[i] = 0;
      }
    }
  };

  /** Fraction of max hp a fresh building starts at, by concrete coverage. */
  Structure.prototype.startHpFraction = function () {
    if (this.def.foundation) return 1;
    var frac = this.concreteTiles / this.footTiles;
    return U.lerp(CFG.SAND_START_HP, CFG.CONCRETE_START_HP, frac);
  };

  Structure.prototype.uncoveredTiles = function () {
    return this.footTiles - this.concreteTiles;
  };

  /** Re-count concrete (slabs can be poured next to an existing building). */
  Structure.prototype.recountConcrete = function () {
    var map = this.world.map, n = 0;
    for (var y = 0; y < this.h; y++) {
      for (var x = 0; x < this.w; x++) {
        if (map.concrete[(this.ty + y) * map.w + (this.tx + x)]) n++;
      }
    }
    this.concreteTiles = n;
  };

  /* ------------------------------- geometry ------------------------------ */
  Structure.prototype.centreTile = function () {
    return { x: this.tx + (this.w - 1) / 2, y: this.ty + (this.h - 1) / 2 };
  };

  Structure.prototype.radius = function () {
    return Math.max(this.w, this.h) * CFG.TILE * 0.5;
  };

  /** Tile a harvester or damaged vehicle backs into. */
  Structure.prototype.dockTile = function () {
    if (!this.def.dock) return null;
    return { x: this.tx + this.def.dock.x, y: this.ty + this.def.dock.y };
  };

  /** Where finished units roll out. Falls back to any free neighbouring tile. */
  Structure.prototype.exitTile = function () {
    var map = this.world.map;
    var cand = [];
    if (this.def.exit) cand.push({ x: this.tx + this.def.exit.x, y: this.ty + this.def.exit.y });
    for (var y = -1; y <= this.h; y++) {
      for (var x = -1; x <= this.w; x++) {
        if (x >= 0 && x < this.w && y >= 0 && y < this.h) continue;
        cand.push({ x: this.tx + x, y: this.ty + y });
      }
    }
    for (var i = 0; i < cand.length; i++) {
      var c = cand[i];
      if (map.inBounds(c.x, c.y) && map.stepFree(c.x, c.y, 'track', -1)) return c;
    }
    return map.findFreeTile(this.tx, this.ty, 'track', 6, -1);
  };

  /* -------------------------------- damage ------------------------------- */
  Structure.prototype.damage = function (amount, source) {
    if (!this.alive) return;
    this.hp -= amount;
    this.damageFlash = 0.12;
    if (source) { this.lastHitBy = source; this.lastHitAt = this.world.time; }
    if (this.hp <= 0) this.destroy('combat');
  };

  Structure.prototype.healthFrac = function () { return U.clamp(this.hp / this.maxHp, 0, 1); };

  Structure.prototype.destroy = function (cause) {
    if (!this.alive) return;
    this.alive = false;
    this.releaseTiles();
    var world = this.world;
    var size = 1.2 + Math.max(this.w, this.h) * 0.45;
    world.effects.explosion(this.x, this.y, size);
    for (var i = 0; i < 4; i++) {
      world.effects.explosion(
        this.x + (Math.random() - 0.5) * this.w * CFG.TILE,
        this.y + (Math.random() - 0.5) * this.h * CFG.TILE,
        size * 0.5);
    }
    DUNE.Sfx.play('bigboom', 0.85, world.audioDist(this.x, this.y));
    if (this.dockUnit) { this.dockUnit.leaveDock(); }
    world.onStructureDestroyed(this, cause);
  };

  /** Sell a building back for half its price. */
  Structure.prototype.sell = function () {
    if (!this.alive) return 0;
    var refund = Math.round(this.def.cost * CFG.REFUND_RATE * this.healthFrac());
    this.faction.credits += refund;
    this.alive = false;
    this.releaseTiles();
    this.world.effects.explosion(this.x, this.y, 1.0, '#c8a05a');
    this.world.onStructureDestroyed(this, 'sold');
    return refund;
  };

  /* -------------------------------- update ------------------------------- */
  Structure.prototype.update = function (dt) {
    if (!this.alive) return;

    if (this.building) {
      this.riseT += dt;
      if (this.riseT >= this.riseTime) this.building = false;
      return;
    }

    if (this.damageFlash > 0) this.damageFlash -= dt;

    // --- the desert eats anything not standing on concrete ---------------
    var bare = this.uncoveredTiles();
    if (bare > 0 && !this.def.foundation) {
      var floor = this.maxHp * CFG.SAND_DECAY_FLOOR;
      if (this.hp > floor) {
        this.hp = Math.max(floor, this.hp - CFG.SAND_DECAY * bare * dt);
        this.decayAcc += dt;
        if (this.decayAcc > 3) {
          this.decayAcc = 0;
          if (this.faction.isPlayer && this.healthFrac() < 0.45) {
            this.world.notify(this.def.name + ' is being eaten by the sand', 'bad', 'decay' + this.id);
          }
        }
      }
    }

    // --- player-ordered repair -------------------------------------------
    if (this.repairing) {
      if (this.hp >= this.maxHp) {
        this.repairing = false;
      } else {
        var heal = CFG.REPAIR_RATE * dt;
        var cost = heal * CFG.REPAIR_COST_PER_HP;
        if (this.faction.credits >= cost) {
          this.faction.spend(cost);
          this.hp = Math.min(this.maxHp, this.hp + heal);
          if (Math.random() < 0.25) this.world.effects.spark(
            this.x + (Math.random() - 0.5) * this.w * CFG.TILE,
            this.y + (Math.random() - 0.5) * this.h * CFG.TILE, 1);
        } else {
          this.repairing = false;
          if (this.faction.isPlayer) this.world.notify('Insufficient credits to repair', 'bad', 'norepair');
        }
      }
    }

    // --- smoke when badly hurt -------------------------------------------
    var hf = this.healthFrac();
    if (hf < 0.6) {
      this.world.effects.damageSmoke(
        this.x + (Math.random() - 0.5) * this.w * CFG.TILE * 0.7,
        this.y + (Math.random() - 0.5) * this.h * CFG.TILE * 0.7,
        (0.6 - hf) * dt * 6);
    }

    // --- repair bay servicing --------------------------------------------
    if (this.def.id === 'repair' && this.dockUnit) this.serviceDock(dt);

    // --- turret ------------------------------------------------------------
    if (this.def.weapon) this.updateTurret(dt);
  };

  Structure.prototype.serviceDock = function (dt) {
    var u = this.dockUnit;
    if (!u || !u.alive) { this.dockUnit = null; return; }
    if (u.hp >= u.maxHp) {
      u.leaveDock();
      if (this.faction.isPlayer) this.world.notify(u.def.name + ' repaired', 'good');
      return;
    }
