  };

  Unit.prototype.healthFrac = function () { return U.clamp(this.hp / this.maxHp, 0, 1); };

  Unit.prototype.destroy = function (cause) {
    if (!this.alive) return;
    this.alive = false;
    this.releaseAll();
    if (this.carrying) { this.carrying.carriedBy = null; this.carrying.hidden = false; this.carrying = null; }
    if (this.carriedBy) { this.carriedBy.carrying = null; this.carriedBy = null; }
    if (this.dockedAt && this.dockedAt.dockUnit === this) this.dockedAt.dockUnit = null;

    var world = this.world;
    if (cause !== 'worm') {
      var size = this.def.move === 'foot' ? 0.45 : (this.def.hp > 400 ? 1.5 : 0.9);
      world.effects.explosion(this.x, this.y, size);
      if (this.def.selfDestruct && cause === 'combat') {
        // a dying Devastator takes its neighbours with it
        world.areaDamage(this.x, this.y, TILE * 2.4, 160, 'he', this);
        world.effects.explosion(this.x, this.y, 3);
        DUNE.Sfx.play('bigboom', 0.9, world.audioDist(this.x, this.y));
      } else {
        DUNE.Sfx.play('explode', 0.6, world.audioDist(this.x, this.y));
      }
    }
    if (this.cargo > 0) {
      // spilled load leaves a small bloom behind
      world.map.paintBloom(this.tx, this.ty, 1, Math.random);
    }
    world.onUnitDestroyed(this, cause);
  };

  /* ------------------------------ deviation ------------------------------ */
  Unit.prototype.deviate = function (toFaction, seconds) {
    if (this.def.move === 'foot' || this.def.move === 'air') return;
    if (this.faction === toFaction) return;
    this.world.changeUnitFaction(this, toFaction);
    this.deviateT = seconds;
    this.setOrder({ t: 'guard' });
    this.world.effects.text(this.x, this.y - 14, 'DEVIATED', '#7ef0c0');
  };

  /* ------------------------------- docking -------------------------------- */
  Unit.prototype.enterDock = function (structure) {
    this.releaseAll();
    this.hidden = true;
    this.dockedAt = structure;
    structure.dockUnit = this;
    this.stopMoving();
    this.x = structure.x; this.y = structure.y + TILE * 0.3;
  };

  Unit.prototype.leaveDock = function () {
    var s = this.dockedAt;
    this.dockedAt = null;
    this.hidden = false;
    if (!s) return;
    if (s.dockUnit === this) s.dockUnit = null;
    var exit = s.exitTile();
    if (exit) {
      this.tx = exit.x; this.ty = exit.y;
      this.x = this.world.map.cx(exit.x); this.y = this.world.map.cy(exit.y);
      this.claim(exit.x, exit.y);
    }
    this.setOrder({ t: 'guard' });
  };

  /* =============================== ORDERS ================================ */
  Unit.prototype.update = function (dt) {
    if (!this.alive) return;
    if (this.damageFlash > 0) this.damageFlash -= dt;
    if (this.recoil > 0) this.recoil = Math.max(0, this.recoil - dt * 6);

    if (this.deviateT > 0) {
      this.deviateT -= dt;
      if (this.deviateT <= 0) {
        this.world.changeUnitFaction(this, this.homeFaction);
        this.setOrder({ t: 'guard' });
      }
    }

    if (this.carriedBy) {
      this.x = this.carriedBy.x; this.y = this.carriedBy.y;
      return;
    }
    if (this.hidden) { this.updateDocked(dt); return; }

    this.runOrder(dt);
    this.updateMove(dt);
    this.updateWeapon(dt);

    if (this.healthFrac() < 0.45 && this.def.move !== 'foot') {
      this.world.effects.damageSmoke(this.x, this.y, (0.45 - this.healthFrac()) * dt * 5);
    }
  };

  Unit.prototype.updateDocked = function (dt) {
    var s = this.dockedAt;
    if (!s || !s.alive) { this.hidden = false; this.dockedAt = null; return; }
    if (this.def.harvester && this.hstate === 'unload') {
      var give = CFG.UNLOAD_RATE * dt;
      var moved = Math.min(this.cargo, give);
      this.cargo -= moved;
      this.faction.addSpice(moved, this);
      this.harvestAcc += moved;
      if (this.harvestAcc > 40) {
        this.harvestAcc = 0;
        DUNE.Sfx.play('credit', 0.6, this.world.audioDist(s.x, s.y));
      }
      if (this.cargo <= 0.01) {
        this.cargo = 0;
        this.leaveDock();
        this.setOrder({ t: 'harvest', x: this.harvestTile ? this.harvestTile.x : this.tx,
                        y: this.harvestTile ? this.harvestTile.y : this.ty });
        this.hstate = 'seek';
      }
    }
  };

  Unit.prototype.runOrder = function (dt) {
    var o = this.order;
    switch (o.t) {
      case 'move':      this.orderMove(dt, false); break;
      case 'amove':     this.orderMove(dt, true); break;
      case 'attack':    this.orderAttack(dt); break;
      case 'harvest':   this.orderHarvest(dt); break;
      case 'return':    this.orderReturn(dt); break;
      case 'repairself':this.orderRepair(dt); break;
      case 'enter':     this.orderEnter(dt); break;
      case 'deploy':    this.orderDeploy(dt); break;
      case 'ferry':     this.orderFerry(dt); break;
      case 'sabotage':  this.orderSabotage(dt); break;
      case 'guard':     this.orderGuard(dt); break;
      default: break;
    }
    if (this.def.harvester && o.t === 'guard' && this.hstate === 'idle' && !this.target) {
      // harvesters never stand around while there is spice to lift
      this.autoHarvest();
    }
    if (this.def.carrier && (o.t === 'guard' || o.t === 'stop')) this.autoFerry();
    if (this.def.id === 'ornithopter') this.updateOrnithopter(dt);
  };

  Unit.prototype.orderGuard = function () {
    if (this.target && this.weapon()) {
      // creep a little to keep a fleeing target in range
      var d = DUNE.Combat.rangeTo(this, this.target);
      if (d > this.attackRange() && d < this.attackRange() + CFG.GUARD_RANGE_BONUS * TILE * 2) {
        if (!this.moving && !this.step) {
          this.gotoTile(this.target.tx, this.target.ty, { adjacent: true });
        }
      }
    }
  };

  Unit.prototype.orderMove = function (dt, aggressive) {
    // attack-move: halt to fight, then pick the march back up
    if (aggressive && this.target && this.target.alive && this.weapon()) {
      if (DUNE.Combat.rangeTo(this, this.target) <= this.attackRange()) {
        if (this.pendingGoal) this._resume = { x: this.order.x, y: this.order.y };
        this.stopMoving();
        return;
      }
    }
    if (!this.pendingGoal) {
      if (this._resume && !this.target) {
        var r = this._resume;
        this._resume = null;
        this.gotoTile(r.x, r.y);
        return;
      }
      if (!this._resume) this.setOrder({ t: 'guard' });
      return;
    }
    if (this.atGoal() && !this.step) {
      this.stopMoving();
      this._resume = null;
      this.setOrder({ t: 'guard' });
    }
  };

  Unit.prototype.orderAttack = function (dt) {
    var t = this.order.target;
    if (!t || !t.alive) {
      this.setOrder({ t: 'guard' });
      return;
    }
    if (this.def.suicide) { this.orderSabotage(dt); return; }
    var w = this.weapon();
    if (!w) {
      // unarmed things "attack" by ramming (Devastator is not unarmed, but MCVs are)
      this.setOrder({ t: 'guard' });
      return;
    }
    var d = DUNE.Combat.rangeTo(this, t);
    var range = this.attackRange();
    if (d > range * 0.92) {
      if (!this.step) {
        this._chaseT = (this._chaseT || 0) - dt;
        if (this._chaseT <= 0 || !this.path) {
          this._chaseT = 0.7;
          this.gotoTile(t.tx, t.ty, { adjacent: true, targetId: t.kind === 'structure' ? t.id : 0 });
        }
      }
    } else if (this.moving || this.path) {
      this.stopMoving();
    }
  };

  /* ---------------------------- harvester loop --------------------------- */
  Unit.prototype.autoHarvest = function () {
    if (this._ahT > this.world.time) return;
    this._ahT = this.world.time + 1.5;
    var spot = this.findSpice();
    if (spot) { this.setOrder({ t: 'harvest', x: spot.x, y: spot.y }); this.hstate = 'seek'; }
  };

  Unit.prototype.findSpice = function () {
    var map = this.world.map;
    var from = this.harvestTile || { x: this.tx, y: this.ty };
    var spot = map.findNearestSpice(from.x, from.y, 30);
    if (!spot) spot = map.findNearestSpice(this.tx, this.ty, 45);
    return spot;
  };

  /**
   * Harvester crews are not brave. If a worm is closing, they run for the
   * nearest rock or concrete, where Shai-Hulud cannot follow, and go back to
   * work once it has passed.
   */
  Unit.prototype.checkWormThreat = function () {
    var world = this.world;
    if (this._wormT > world.time) return false;
    var map = world.map;
    var danger = null;
    for (var i = 0; i < world.worms.length; i++) {
      var wm = world.worms[i];
      if (wm.state === DUNE.Worm.STATE.DORMANT) continue;
      if (U.dist(this.x, this.y, wm.x, wm.y) < CFG.TILE * 6.5) { danger = wm; break; }
    }
    if (!danger) return false;
    if (!DUNE.isOpenSand(map.terrainAt(this.tx, this.ty)) ||
        map.concrete[this.ty * map.w + this.tx]) return false;

    this._wormT = world.time + 6;
    // nearest hard ground within reach
    var safe = map.spiral(this.tx, this.ty, 10, function (x, y, idx) {
      if (map.building[idx]) return null;
      if (map.concrete[idx] || !DUNE.isOpenSand(map.terrain[idx])) {
        if (map.terrainCost(x, y, 'track') === Infinity) return null;
        return { x: x, y: y };
      }
      return null;
    });
    if (!safe) {
      var away = U.angleTo(danger.x, danger.y, this.x, this.y);
      safe = {
        x: U.clamp(this.tx + Math.round(Math.cos(away) * 8), 0, map.w - 1),
        y: U.clamp(this.ty + Math.round(Math.sin(away) * 8), 0, map.h - 1)
      };
    }
    this.hstate = this.cargo > 0 ? 'full' : 'flee';
    this.gotoTile(safe.x, safe.y);
    if (this.faction.isPlayer) {
      world.notify('Sandworm! Harvester pulling back', 'bad', 'wormflee');
      world.flashOnMinimap(danger.x, danger.y);
    }
    return true;
  };

  Unit.prototype.orderHarvest = function (dt) {
    if (!this.def.harvester) { this.setOrder({ t: 'guard' }); return; }
    var map = this.world.map;

    if (this.hstate === 'flee') {
      if (!this.moving && !this.step) {
        this.hstate = 'seek';
        var back = this.harvestTile || { x: this.tx, y: this.ty };
        this.order.x = back.x; this.order.y = back.y;
      }
      return;
    }
    if ((this.hstate === 'harvest' || this.hstate === 'seek') && this.checkWormThreat()) return;

    // a full hopper interrupts gathering, but must not restart the run home
    if (this.cargo >= CFG.HARVESTER_CAP &&
        (this.hstate === 'harvest' || this.hstate === 'seek' || this.hstate === 'idle')) {
      this.hstate = 'full';
    }

    switch (this.hstate) {
      case 'idle':
      case 'seek': {
        var gx = this.order.x, gy = this.order.y;
        if (map.spiceAt(gx, gy) <= 5) {
          var spot = map.findNearestSpice(gx, gy, 34) || map.findNearestSpice(this.tx, this.ty, 45);
          if (!spot) {
            if (this.cargo > 0) { this.hstate = 'full'; return; }
            if (this.faction.isPlayer) {
              this.world.notify('Harvester: no spice in range', 'bad', 'nospice');
            }
            this.hstate = 'idle';
            this.setOrder({ t: 'guard' });
            return;
          }
          this.order.x = spot.x; this.order.y = spot.y;
          this.gotoTile(spot.x, spot.y);
          return;
        }
        if (this.tx === gx && this.ty === gy) {
          this.hstate = 'harvest';
          this.harvestTile = { x: gx, y: gy };
          this.stopMoving();
        } else if (!this.path && !this.step && !this.pendingGoal) {
          this.gotoTile(gx, gy);
        } else if (!this.moving && !this.step && this.atGoal()) {
          this.hstate = 'harvest';
          this.harvestTile = { x: this.tx, y: this.ty };
        }
        break;
      }

      case 'harvest': {
        var got = map.takeSpice(this.tx, this.ty, CFG.HARVEST_RATE * dt);
        if (got > 0) {
          this.cargo += got;
          this.harvestAcc += got;
          if (this.harvestAcc > 45) {
            this.harvestAcc = 0;
            DUNE.Sfx.play('harvest', 0.5, this.world.audioDist(this.x, this.y));
            this.world.effects.dust(this.x, this.y + 6, 2);
          }
          if (this.cargo >= CFG.HARVESTER_CAP) { this.cargo = CFG.HARVESTER_CAP; this.hstate = 'full'; }
        } else {
          // this tile is spent - shuffle to the next one
          var next = map.findNearestSpice(this.tx, this.ty, 12);
          if (next) {
            this.order.x = next.x; this.order.y = next.y;
            this.hstate = 'seek';
            this.gotoTile(next.x, next.y);
          } else if (this.cargo > 0) {
            this.hstate = 'full';
          } else {
            this.hstate = 'seek';
            this.order.x = this.tx; this.order.y = this.ty;
          }
        }
        break;
      }

      case 'full': {
        var ref = this.faction.nearestRefinery(this.x, this.y, true);
        if (!ref) {
          if (this.faction.isPlayer) this.world.notify('Harvester full — no refinery!', 'bad', 'noref');
          this._waitRef = (this._waitRef || 0) + dt;
          if (this._waitRef > 4) { this._waitRef = 0; }
          return;
        }
        this.targetRefinery = ref;
        this.hstate = 'return';
        var dock = ref.dockTile();
        this.gotoTile(dock.x, dock.y);
        break;
      }

      case 'return': {
        var r = this.targetRefinery;
        if (!r || !r.alive) { this.hstate = 'full'; return; }
        var dk = r.dockTile();
        if (U.cheb(this.tx, this.ty, dk.x, dk.y) <= 1 && !this.step) {
          if (r.dockUnit && r.dockUnit !== this) {
            // queue politely just outside the bay
            this.stopMoving();
            return;
          }
          this.enterDock(r);
          this.hstate = 'unload';
          DUNE.Sfx.play('deploy', 0.5, this.world.audioDist(r.x, r.y));
        } else if (!this.path && !this.step) {
          this.gotoTile(dk.x, dk.y);
        }
        break;
      }
    }
  };

  /** "Take it home now" - drops back into the harvest loop at the full stage. */
  Unit.prototype.orderReturn = function () {
    var back = this.harvestTile || { x: this.tx, y: this.ty };
    this.setOrder({ t: 'harvest', x: back.x, y: back.y });
    this.hstate = 'full';
  };

  /* ------------------------------ repair bay ----------------------------- */
  Unit.prototype.orderRepair = function (dt) {
    var bay = this.faction.nearestStructure('repair', this.x, this.y, function (s) { return !s.dockUnit; });
    if (!bay) {
      if (this.faction.isPlayer) this.world.notify('No repair facility available', 'bad', 'norepbay');
      this.setOrder({ t: 'guard' });
      return;
    }
    var dk = bay.dockTile();
    if (U.cheb(this.tx, this.ty, dk.x, dk.y) <= 1 && !this.step) {
      if (bay.dockUnit && bay.dockUnit !== this) { this.stopMoving(); return; }
      this.enterDock(bay);
      DUNE.Sfx.play('repair', 0.6, this.world.audioDist(bay.x, bay.y));
      this.order = { t: 'guard' };
    } else if (!this.path && !this.step) {
      this.gotoTile(dk.x, dk.y);
    }
  };

  Unit.prototype.orderEnter = function (dt) {
    var s = this.order.target;
    if (!s || !s.alive) { this.setOrder({ t: 'guard' }); return; }
    if (s.def.id === 'refinery' && this.def.harvester) {
      this.targetRefinery = s;
      this.hstate = this.cargo > 0 ? 'return' : 'seek';
      this.setOrder({ t: 'harvest', x: this.tx, y: this.ty });
      return;
    }
    if (s.def.id === 'repair') { this.setOrder({ t: 'repairself' }); return; }
    this.setOrder({ t: 'guard' });
  };

  /* -------------------------------- deploy ------------------------------- */
  Unit.prototype.orderDeploy = function (dt) {
    if (!this.def.deploy) { this.setOrder({ t: 'guard' }); return; }
    var tx = this.tx, ty = this.ty;
    var res = DUNE.Structure.checkPlacement(this.world, this.def.deploy, this.faction, tx, ty);
    var ok = res.ok || res.reason === 'Must adjoin your base';
    if (!ok) {
      // try to shuffle one tile and retry once
      var free = this.world.map.findFreeTile(tx, ty, 'track', 4, this.id);
      if (free && (free.x !== tx || free.y !== ty) && !this._deployTried) {
        this._deployTried = true;
        this.gotoTile(free.x, free.y);
        return;
      }
      if (this.faction.isPlayer) this.world.notify('Cannot deploy here: ' + res.reason, 'bad');
      this.setOrder({ t: 'guard' });
      return;
    }
    this.releaseAll();
    this.alive = false;
    this.world.onUnitDestroyed(this, 'deployed');
    var s = this.world.createStructure(this.def.deploy, this.faction, tx, ty);
    s.riseTime = 0.7;
    DUNE.Sfx.play('deploy', 1, this.world.audioDist(this.x, this.y));
    this.world.effects.sandBurst(this.x, this.y, 20);
    if (this.faction.isPlayer) this.world.notify('Construction Yard deployed', 'good');
  };

  /* ------------------------------- saboteur ------------------------------ */
  Unit.prototype.orderSabotage = function (dt) {
    var t = this.order.target;
    if (!t || !t.alive) {
      var found = DUNE.Combat.nearestEnemyStructure(this);
      if (!found) { this.setOrder({ t: 'guard' }); return; }
      this.order = { t: 'sabotage', target: found };
      t = found;
    }
    if (U.dist(this.x, this.y, t.x, t.y) < TILE * 1.2) {
      this.world.effects.explosion(t.x, t.y, 3.2);
      DUNE.Sfx.play('bigboom', 1, this.world.audioDist(t.x, t.y));
      if (t.kind === 'structure') t.damage(t.maxHp * 2, this);
      else DUNE.Combat.applyDamage(t, 2000, 'he', this, this.world);
      this.alive = false;
      this.releaseAll();
      this.world.onUnitDestroyed(this, 'sabotage');
      return;
    }
    if (!this.path && !this.step) {
      this.gotoTile(t.tx, t.ty, { adjacent: true, targetId: t.kind === 'structure' ? t.id : 0 });
    }
  };

  /* ------------------------------- carryall ------------------------------ */
  Unit.prototype.autoFerry = function () {
    if (this._ferryT > this.world.time) return;
    this._ferryT = this.world.time + 2.2;
    var best = null, bestScore = 0;
    var units = this.faction.units;
    for (var i = 0; i < units.length; i++) {
      var h = units[i];
      if (!h.def.harvester || !h.alive || h.hidden || h.carriedBy) continue;
      if (h.hstate !== 'full' && h.hstate !== 'return') continue;
      if (h._ferryClaim && h._ferryClaim !== this && h._ferryClaim.alive) continue;
      var ref = this.faction.nearestRefinery(h.x, h.y, false);
      if (!ref) continue;
      var d = U.dist(h.x, h.y, ref.x, ref.y) / TILE;
      if (d < 9) continue;                 // close enough to drive
      var score = d - U.dist(this.x, this.y, h.x, h.y) / TILE * 0.3;
      if (score > bestScore) { bestScore = score; best = h; }
    }
    if (best) {
      best._ferryClaim = this;
      this.setOrder({ t: 'ferry', target: best, phase: 'pickup' });
    }
  };

  Unit.prototype.orderFerry = function (dt) {
    var o = this.order;
    var h = o.target;
    if (!h || !h.alive) { if (this.carrying) this.dropCarry(); this.setOrder({ t: 'guard' }); return; }

    if (o.phase === 'pickup') {
      if (h.carriedBy && h.carriedBy !== this) { this.setOrder({ t: 'guard' }); return; }
      this.gotoTile(h.tx, h.ty);
      if (U.dist(this.x, this.y, h.x, h.y) < TILE * 0.8) {
        h.releaseAll();
        h.carriedBy = this; h.hidden = false; this.carrying = h;
        h.stopMoving();
        o.phase = 'deliver';
        var ref = this.faction.nearestRefinery(h.x, h.y, false);
        o.ref = ref;
        DUNE.Sfx.play('deploy', 0.5, this.world.audioDist(this.x, this.y));
      }
    } else if (o.phase === 'deliver') {
      var ref = o.ref;
      if (!ref || !ref.alive) { ref = o.ref = this.faction.nearestRefinery(this.x, this.y, false); }
      if (!ref) { this.dropCarry(); this.setOrder({ t: 'guard' }); return; }
      var dk = ref.dockTile();
      this.gotoTile(dk.x, dk.y);
      if (U.dist(this.x, this.y, this.world.map.cx(dk.x), this.world.map.cy(dk.y)) < TILE * 0.9) {
        var carried = this.carrying;
        this.dropCarry(dk);
        if (carried) {
          carried.targetRefinery = ref;
          carried.hstate = 'return';
          carried.setOrder({ t: 'harvest', x: carried.harvestTile ? carried.harvestTile.x : carried.tx,
                             y: carried.harvestTile ? carried.harvestTile.y : carried.ty });
          carried.hstate = 'return';
        }
        this.setOrder({ t: 'guard' });
      }
    }
  };

  Unit.prototype.dropCarry = function (tile) {
    var h = this.carrying;
    if (!h) return;
    var map = this.world.map;
    var spot = tile && map.stepFree(tile.x, tile.y, h.def.move, h.id)
      ? tile
      : map.findFreeTile(Math.floor(this.x / TILE), Math.floor(this.y / TILE), h.def.move, 6, h.id);
    if (!spot) spot = { x: h.tx, y: h.ty };
    h.carriedBy = null;
    h._ferryClaim = null;
    h.tx = spot.x; h.ty = spot.y;
    h.x = map.cx(spot.x); h.y = map.cy(spot.y);
    h.claim(spot.x, spot.y);
    h.hidden = false;
    this.carrying = null;
  };

  /* ----------------------------- ornithopter ----------------------------- */
  Unit.prototype.updateOrnithopter = function (dt) {
    // thopters carry a limited load then fly home to rearm
    if (this.rearm > 0) {
      this.rearm -= dt;
      var home = this.faction.nearestStructure('hightech', this.x, this.y) ||
                 this.faction.primaryStructure();
      if (home && !this.pendingGoal) this.gotoTile(home.tx, home.ty, { adjacent: true });
      if (this.rearm <= 0) { this.shotsLeft = 6; this.setOrder({ t: 'guard' }); }
      return;
    }
    if (this.shotsLeft == null) this.shotsLeft = 6;
    if (this.shotsLeft <= 0) { this.rearm = 7; this.pendingGoal = null; }
  };

  DUNE.Unit = Unit;
})();
"},{"path":"js/render/minimap.js","type":"text/javascript","text":"/* =============================================================================
   minimap.js - the radar display.

   It only works while a Radar Outpost stands and the power grid is holding;
   lose either and the screen fills with static, exactly as it should.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG, T = DUNE.T;

  var TERRAIN_COLOUR = {};
  TERRAIN_COLOUR[T.SAND] = [196, 156, 92];
  TERRAIN_COLOUR[T.DUNES] = [178, 140, 80];
  TERRAIN_COLOUR[T.ROCK] = [104, 96, 82];
  TERRAIN_COLOUR[T.MOUNTAIN] = [72, 66, 56];
  TERRAIN_COLOUR[T.SPICE] = [196, 112, 40];
  TERRAIN_COLOUR[T.SPICE2] = [222, 128, 34];

  function Minimap(canvas, world) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.world = world;
    this.w = canvas.width; this.h = canvas.height;
    this.scale = Math.min(this.w / world.map.w, this.h / world.map.h);
    this.ox = (this.w - world.map.w * this.scale) / 2;
    this.oy = (this.h - world.map.h * this.scale) / 2;

    this.base = document.createElement('canvas');
    this.base.width = world.map.w;
    this.base.height = world.map.h;
    this.bctx = this.base.getContext('2d');
    this.img = this.bctx.createImageData(world.map.w, world.map.h);
    this.refreshT = 0;
    this.blips = [];
    this.online = false;
  }

  Minimap.prototype.isOnline = function () {
    var f = this.world.playerFaction;
    if (!f) return false;
    if (!f.has('radar')) return false;
    return f.powerRatio() > 0.6;
  };

  /** Repaints the terrain image from the explored mask. */
  Minimap.prototype.refresh = function () {
    var map = this.world.map, fog = this.world.playerFog;
    var d = this.img.data;
    for (var i = 0; i < map.n; i++) {
      var o = i * 4;
      if (fog && fog.enabled && !fog.explored[i]) {
        d[o] = 8; d[o + 1] = 6; d[o + 2] = 4; d[o + 3] = 255;
        continue;
      }
      var c;
      if (map.concrete[i]) c = [122, 116, 104];
      else c = TERRAIN_COLOUR[map.terrain[i]] || [120, 100, 70];
      var dim = (fog && fog.enabled && !fog.visible[i]) ? 0.62 : 1;
      d[o] = c[0] * dim; d[o + 1] = c[1] * dim; d[o + 2] = c[2] * dim; d[o + 3] = 255;
    }
    this.bctx.putImageData(this.img, 0, 0);
  };

  Minimap.prototype.flash = function (wx, wy) {
    this.blips.push({ x: wx / CFG.TILE, y: wy / CFG.TILE, life: 3 });
  };

  Minimap.prototype.draw = function (dt) {
    var ctx = this.ctx, world = this.world;
    var online = this.isOnline();
    this.online = online;

    ctx.clearRect(0, 0, this.w, this.h);

    if (!online) {
      // static
      ctx.fillStyle = '#0d0904';
      ctx.fillRect(0, 0, this.w, this.h);
      ctx.fillStyle = 'rgba(120,96,50,.35)';
      for (var s = 0; s < 220; s++) {
        ctx.fillRect(Math.random() * this.w, Math.random() * this.h, 2, 1);
      }
      return;
    }

    this.refreshT -= dt;
    if (this.refreshT <= 0) { this.refreshT = 0.35; this.refresh(); }

    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(this.base, this.ox, this.oy, world.map.w * this.scale, world.map.h * this.scale);

    var fog = world.playerFog;
    var sc = this.scale, ox = this.ox, oy = this.oy;
    var i, e;

    // structures
    for (i = 0; i < world.structures.length; i++) {
      e = world.structures[i];
      if (!e.alive) continue;
      if (fog && fog.enabled && !fog.isExplored(e.tx, e.ty)) continue;
      if (fog && fog.enabled && !e.faction.isPlayer && !fog.isVisible(e.tx, e.ty)) {
        ctx.fillStyle = 'rgba(120,110,95,.7)';   // last known position
      } else {
        ctx.fillStyle = e.faction.colour;
      }
      ctx.fillRect(ox + e.tx * sc, oy + e.ty * sc, Math.max(2, e.w * sc), Math.max(2, e.h * sc));
    }

    // units
    for (i = 0; i < world.units.length; i++) {
      e = world.units[i];
      if (!e.alive || e.hidden || e.carriedBy) continue;
      if (fog && fog.enabled && !e.faction.isPlayer && !fog.isVisible(e.tx, e.ty)) continue;
      ctx.fillStyle = e.faction.isPlayer
        ? (e.def.harvester ? '#e0b83c' : e.faction.house.colourLight)
        : e.faction.colour;
      var sz = Math.max(2, sc * (e.def.hp > 400 ? 1.6 : 1.1));
      ctx.fillRect(ox + e.tx * sc, oy + e.ty * sc, sz, sz);
    }

    // worms show as a moving smear if you can see them
    for (i = 0; i < world.worms.length; i++) {
      var wm = world.worms[i];
      if (wm.state === DUNE.Worm.STATE.DORMANT) continue;
      var wtx = wm.tileX(), wty = wm.tileY();
      if (fog && fog.enabled && !fog.isVisible(wtx, wty)) continue;
      ctx.fillStyle = 'rgba(226,186,110,.9)';
      ctx.fillRect(ox + wtx * sc - 1, oy + wty * sc - 1, sc * 3, sc * 3);
    }

    // attack blips
    for (i = this.blips.length - 1; i >= 0; i--) {
      var b = this.blips[i];
      b.life -= dt;
      if (b.life <= 0) { this.blips.splice(i, 1); continue; }
      var r = (1 - (b.life % 1)) * 10;
      ctx.strokeStyle = 'rgba(200,53,42,' + (b.life % 1) + ')';
      ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(ox + b.x * sc, oy + b.y * sc, r, 0, U.TAU); ctx.stroke();
    }

    // viewport rectangle
    var r2 = world.renderer;
    if (r2) {
      var v = r2.viewRect();
      ctx.strokeStyle = 'rgba(240,215,166,.9)';
      ctx.lineWidth = 1;
      ctx.strokeRect(
        ox + (v.x / CFG.TILE) * sc,
        oy + (v.y / CFG.TILE) * sc,
        (v.w / CFG.TILE) * sc,
        (v.h / CFG.TILE) * sc);
    }

    // scanline sweep
    var t = (world.time * 0.35) % 1;
    ctx.fillStyle = 'rgba(126,240,160,.07)';
    ctx.fillRect(0, t * this.h, this.w, 2);
  };

  /** Converts a click on the radar into world coordinates. */
  Minimap.prototype.toWorld = function (mx, my) {
    return {
      x: ((mx - this.ox) / this.scale) * CFG.TILE,
      y: ((my - this.oy) / this.scale) * CFG.TILE
    };
  };

  DUNE.Minimap = Minimap;
})();
"},{"path":"js/render/renderer.js","type":"text/javascript","text":"/* =============================================================================
   renderer.js - camera, cached terrain, entity drawing and the shroud.

   The terrain is painted once into an offscreen canvas the size of the whole
   map and only repainted where tiles change (spice being eaten, concrete being
   poured). Everything else is drawn per frame in world space.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG, T = DUNE.T;
  var TILE = CFG.TILE;

  function Renderer(canvas, world) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.world = world;
    this.cam = { x: 0, y: 0, zoom: 1 };
    this.vw = 0; this.vh = 0;
    this.placement = null;      // {defId, tx, ty, valid, reason}
    this.selectionBox = null;   // {x0,y0,x1,y1} in world space
    this.buildTiles = null;
    this.hoverEntity = null;
    this.showRanges = false;

    this.terrain = document.createElement('canvas');
    this.terrain.width = world.map.w * TILE;
    this.terrain.height = world.map.h * TILE;
    this.tctx = this.terrain.getContext('2d');
    this.paintAllTiles();
    this.resize();
  }

  /* ------------------------------- camera -------------------------------- */
  Renderer.prototype.resize = function () {
    var r = this.canvas.parentNode.getBoundingClientRect();
    var dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.max(320, Math.floor(r.width * dpr));
    this.canvas.height = Math.max(240, Math.floor(r.height * dpr));
    this.dpr = dpr;
    this.vw = r.width; this.vh = r.height;
    this.clampCamera();
  };

  Renderer.prototype.clampCamera = function () {
    var mw = this.world.map.w * TILE, mh = this.world.map.h * TILE;
    var vw = this.vw / this.cam.zoom, vh = this.vh / this.cam.zoom;
    this.cam.x = U.clamp(this.cam.x, 0, Math.max(0, mw - vw));
    this.cam.y = U.clamp(this.cam.y, 0, Math.max(0, mh - vh));
  };

  Renderer.prototype.centreOn = function (wx, wy) {
    this.cam.x = wx - (this.vw / this.cam.zoom) / 2;
    this.cam.y = wy - (this.vh / this.cam.zoom) / 2;
    this.clampCamera();
  };

  Renderer.prototype.scroll = function (dx, dy) {
    this.cam.x += dx / this.cam.zoom;
    this.cam.y += dy / this.cam.zoom;
    this.clampCamera();
  };

  Renderer.prototype.zoomAt = function (sx, sy, factor) {
    var before = this.screenToWorld(sx, sy);
    this.cam.zoom = U.clamp(this.cam.zoom * factor, CFG.MIN_ZOOM, CFG.MAX_ZOOM);
    var after = this.screenToWorld(sx, sy);
    this.cam.x += before.x - after.x;
    this.cam.y += before.y - after.y;
    this.clampCamera();
  };

  Renderer.prototype.screenToWorld = function (sx, sy) {
    return { x: this.cam.x + sx / this.cam.zoom, y: this.cam.y + sy / this.cam.zoom };
  };
  Renderer.prototype.worldToScreen = function (wx, wy) {
    return { x: (wx - this.cam.x) * this.cam.zoom, y: (wy - this.cam.y) * this.cam.zoom };
  };
  Renderer.prototype.screenToTile = function (sx, sy) {
    var w = this.screenToWorld(sx, sy);
    return { x: Math.floor(w.x / TILE), y: Math.floor(w.y / TILE) };
  };

  /* ============================== TERRAIN ================================ */
  Renderer.prototype.paintAllTiles = function () {
    var map = this.world.map;
    for (var y = 0; y < map.h; y++) {
      for (var x = 0; x < map.w; x++) this.paintTile(x, y);
    }
  };

  Renderer.prototype.flushDirty = function () {
    var map = this.world.map;
    if (!map.dirty.length) return;
    var seen = {};
    for (var i = 0; i < map.dirty.length; i++) {
      var idx = map.dirty[i];
      if (seen[idx]) continue;
      seen[idx] = 1;
      this.paintTile(idx % map.w, (idx / map.w) | 0);
    }
    map.dirty.length = 0;
  };

  Renderer.prototype.paintTile = function (tx, ty) {
    var map = this.world.map, ctx = this.tctx;
    var i = ty * map.w + tx;
    var t = map.terrain[i];
    var px = tx * TILE, py = ty * TILE;
    var seed = map.seed;
    var n = U.hash2(tx, ty, seed);
    var n2 = U.hash2(tx * 3 + 1, ty * 7 + 5, seed);

    if (map.concrete[i]) {
      this.paintConcrete(ctx, px, py, tx, ty, n);
      return;
    }

    switch (t) {
      case T.SAND: {
        var v = 156 + n * 26;
        ctx.fillStyle = U.rgb(v + 24, v - 10, v - 78);
        ctx.fillRect(px, py, TILE, TILE);
        ctx.fillStyle = 'rgba(120,88,42,' + (0.06 + n2 * 0.08) + ')';
        for (var s = 0; s < 5; s++) {
          var hx = U.hash2(tx * 11 + s, ty * 13 - s, seed);
          var hy = U.hash2(tx * 17 - s, ty * 19 + s, seed);
          ctx.fillRect(px + hx * TILE, py + hy * TILE, 2, 1.5);
        }
        break;
      }
      case T.DUNES: {
        var d = 146 + n * 22;
        ctx.fillStyle = U.rgb(d + 26, d - 6, d - 74);
        ctx.fillRect(px, py, TILE, TILE);
        ctx.strokeStyle = 'rgba(210,172,104,.5)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        var off = n * TILE;
        ctx.moveTo(px, py + off % TILE);
        ctx.quadraticCurveTo(px + TILE / 2, py + (off % TILE) - 6, px + TILE, py + (off % TILE) + 3);
        ctx.stroke();
        ctx.strokeStyle = 'rgba(96,66,30,.28)';
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.moveTo(px, py + (off % TILE) + 4);
        ctx.quadraticCurveTo(px + TILE / 2, py + (off % TILE) - 2, px + TILE, py + (off % TILE) + 7);
        ctx.stroke();
        break;
      }
      case T.ROCK: {
        var r = 96 + n * 30;
        ctx.fillStyle = U.rgb(r + 10, r - 2, r - 22);
        ctx.fillRect(px, py, TILE, TILE);
        // slabs
        ctx.fillStyle = 'rgba(40,34,26,' + (0.14 + n2 * 0.18) + ')';
        ctx.fillRect(px + 1 + n * 6, py + 2 + n2 * 5, TILE * 0.42, TILE * 0.34);
        ctx.fillStyle = 'rgba(190,178,156,' + (0.08 + n * 0.1) + ')';
        ctx.fillRect(px + TILE * 0.5, py + TILE * 0.55, TILE * 0.34, TILE * 0.28);
        this.edgeShade(ctx, map, tx, ty, px, py, T.ROCK);
        break;
      }
      case T.MOUNTAIN: {
        var m = 74 + n * 26;
        ctx.fillStyle = U.rgb(m + 6, m - 4, m - 18);
        ctx.fillRect(px, py, TILE, TILE);
        ctx.fillStyle = 'rgba(210,196,168,.20)';
        ctx.beginPath();
        ctx.moveTo(px + 2, py + TILE - 2);
        ctx.lineTo(px + TILE * (0.3 + n * 0.3), py + 2);
        ctx.lineTo(px + TILE - 2, py + TILE - 2);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = 'rgba(18,14,10,.34)';
        ctx.beginPath();
        ctx.moveTo(px + TILE * (0.3 + n * 0.3), py + 2);
        ctx.lineTo(px + TILE - 2, py + TILE - 2);
        ctx.lineTo(px + TILE * 0.62, py + TILE - 2);
        ctx.closePath(); ctx.fill();
        break;
      }
      case T.SPICE: case T.SPICE2: {
        var amt = map.spice[i];
        var cap = t === T.SPICE2 ? CFG.TILE_SPICE_THICK : CFG.TILE_SPICE;
        var k = U.clamp(amt / cap, 0, 1);
        var base = 150 + n * 20;
        ctx.fillStyle = U.rgb(base + 24, base - 10, base - 78);
        ctx.fillRect(px, py, TILE, TILE);
        var rr = U.lerp(176, 208, k), gg = U.lerp(108, 92, k), bb = U.lerp(46, 26, k);
        ctx.fillStyle = 'rgba(' + (rr | 0) + ',' + (gg | 0) + ',' + (bb | 0) + ',' + (0.45 + k * 0.5) + ')';
        ctx.fillRect(px, py, TILE, TILE);
        ctx.fillStyle = 'rgba(255,186,92,' + (0.12 + k * 0.28) + ')';
        for (var g = 0; g < 6; g++) {
          var gx = U.hash2(tx * 23 + g, ty * 29 + g, seed);
          var gy = U.hash2(tx * 31 - g, ty * 37 + g, seed);
          ctx.fillRect(px + gx * TILE, py + gy * TILE, 2.4, 2.4);
        }
        if (t === T.SPICE2) {
          ctx.strokeStyle = 'rgba(120,52,12,.35)';
          ctx.lineWidth = 1;
          ctx.strokeRect(px + 1.5, py + 1.5, TILE - 3, TILE - 3);
        }
        break;
      }
    }
  };

  /** Darkens the boundary between rock and sand so plateaus read clearly. */
  Renderer.prototype.edgeShade = function (ctx, map, tx, ty, px, py, self) {
    ctx.fillStyle = 'rgba(30,22,12,.30)';
    if (map.terrainAt(tx, ty + 1) !== self && map.terrainAt(tx, ty + 1) !== T.MOUNTAIN) {
      ctx.fillRect(px, py + TILE - 3, TILE, 3);
    }
    if (map.terrainAt(tx - 1, ty) !== self && map.terrainAt(tx - 1, ty) !== T.MOUNTAIN) {
      ctx.fillRect(px, py, 2, TILE);
    }
    if (map.terrainAt(tx + 1, ty) !== self && map.terrainAt(tx + 1, ty) !== T.MOUNTAIN) {
      ctx.fillRect(px + TILE - 2, py, 2, TILE);
    }
    ctx.fillStyle = 'rgba(226,214,188,.12)';
    if (map.terrainAt(tx, ty - 1) !== self && map.terrainAt(tx, ty - 1) !== T.MOUNTAIN) {
      ctx.fillRect(px, py, TILE, 2);
    }
  };

  Renderer.prototype.paintConcrete = function (ctx, px, py, tx, ty, n) {
    var v = 118 + n * 16;
    ctx.fillStyle = U.rgb(v, v - 5, v - 16);
    ctx.fillRect(px, py, TILE, TILE);
    ctx.fillStyle = 'rgba(210,204,190,.14)';
    ctx.fillRect(px + 1, py + 1, TILE - 2, 2);
    ctx.fillStyle = 'rgba(24,20,14,.34)';
    ctx.fillRect(px + 1, py + TILE - 3, TILE - 2, 2);
    ctx.fillRect(px + TILE - 3, py + 1, 2, TILE - 2);
    ctx.strokeStyle = 'rgba(40,34,26,.45)';
    ctx.lineWidth = 1;
    ctx.strokeRect(px + 0.5, py + 0.5, TILE - 1, TILE - 1);
    ctx.fillStyle = 'rgba(60,52,40,.25)';
    ctx.fillRect(px + TILE * 0.3, py + TILE * 0.45, TILE * 0.4, 1.5);
  };

  /* =============================== DRAW ================================== */
  Renderer.prototype.draw = function (dt) {
    var ctx = this.ctx, world = this.world;
    this.flushDirty();

    var shake = world.effects.shake;
    var sx = shake > 0 ? (Math.random() - 0.5) * shake : 0;
    var sy = shake > 0 ? (Math.random() - 0.5) * shake : 0;

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.fillStyle = '#100b05';
    ctx.fillRect(0, 0, this.vw, this.vh);

    ctx.save();
    ctx.scale(this.cam.zoom, this.cam.zoom);
    ctx.translate(-this.cam.x + sx / this.cam.zoom, -this.cam.y + sy / this.cam.zoom);

    var view = this.viewRect();

    // terrain slab (a zero-size source rect is illegal, so guard it)
    if (view.w > 0 && view.h > 0) {
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(this.terrain,
        view.x, view.y, view.w, view.h,
        view.x, view.y, view.w, view.h);
      ctx.imageSmoothingEnabled = true;
    }

    this.drawScorch(ctx);
    this.drawBuildOverlay(ctx);
    this.drawStructures(ctx, view);
    this.drawWorms(ctx);
    this.drawUnits(ctx, view);
    this.drawProjectiles(ctx);
    this.drawEffects(ctx);
    this.drawSelectionOverlays(ctx);
    this.drawPlacement(ctx);
    this.drawShroud(ctx, view);
    this.drawSelectionBox(ctx);

    ctx.restore();
  };

  Renderer.prototype.viewRect = function () {
    var w = this.vw / this.cam.zoom, h = this.vh / this.cam.zoom;
    var mw = this.world.map.w * TILE, mh = this.world.map.h * TILE;
    var x = U.clamp(this.cam.x, 0, mw), y = U.clamp(this.cam.y, 0, mh);
    return { x: x, y: y, w: Math.min(w, mw - x), h: Math.min(h, mh - y) };
  };

  Renderer.prototype.inView = function (x, y, pad, view) {
    return x > view.x - pad && x < view.x + view.w + pad &&
           y > view.y - pad && y < view.y + view.h + pad;
  };

  /* ------------------------------- scorch -------------------------------- */
  Renderer.prototype.drawScorch = function (ctx) {
    var list = this.world.effects.scorch;
    for (var i = 0; i < list.length; i++) {
      var s = list[i];
      ctx.fillStyle = 'rgba(28,18,8,' + s.a + ')';
      ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, U.TAU); ctx.fill();
    }
  };

  /* --------------------------- structures -------------------------------- */
  Renderer.prototype.drawStructures = function (ctx, view) {
    var world = this.world;
    var fog = world.playerFog;
    for (var i = 0; i < world.structures.length; i++) {
      var s = world.structures[i];
      if (!s.alive) continue;
      if (!this.inView(s.x, s.y, 80, view)) continue;
      if (fog && !fog.isExplored(Math.round(s.tx + s.w / 2), Math.round(s.ty + s.h / 2))) continue;

      var w = s.w * TILE, h = s.h * TILE;
      ctx.save();
      ctx.translate(s.tx * TILE, s.ty * TILE);

      if (s.building) {
        // rising out of the ground
        var p = U.clamp(s.riseT / s.riseTime, 0, 1);
        ctx.save();
        ctx.beginPath(); ctx.rect(0, h * (1 - p), w, h * p); ctx.clip();
        ctx.translate(0, 0);
        DUNE.Sprites.structure(ctx, s.def.id, w, h, s.faction.colours,
          { time: world.time, damage: 0 });
        ctx.restore();
        ctx.fillStyle = 'rgba(200,160,90,' + (0.25 * (1 - p)) + ')';
        ctx.fillRect(0, 0, w, h);
      } else {
        DUNE.Sprites.structure(ctx, s.def.id, w, h, s.faction.colours, {
          time: world.time,
          damage: 1 - s.healthFrac(),
          powered: s.faction.hasPower()
        });
        if (s.def.weapon) {
          ctx.save();
          ctx.translate(w / 2, h / 2);
          ctx.rotate(s.turretAngle);
          DUNE.Sprites.turretHead(ctx, s.def.id, TILE * 1.25, s.faction.colours, {});
          ctx.restore();
        }
      }

      if (s.damageFlash > 0) {
        ctx.fillStyle = 'rgba(255,220,180,' + (s.damageFlash * 3) + ')';
        ctx.fillRect(0, 0, w, h);
      }
      ctx.restore();

      // sand-decay warning band
      if (!s.building && !s.def.foundation && s.uncoveredTiles() > 0) {
        ctx.strokeStyle = 'rgba(216,98,31,.45)';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(s.tx * TILE + 1, s.ty * TILE + 1, w - 2, h - 2);
        ctx.setLineDash([]);
      }

      this.drawHealthBar(ctx, s, s.tx * TILE + 2, s.ty * TILE - 6, w - 4);
      // ownership pip
      ctx.fillStyle = s.faction.colour;
      ctx.fillRect(s.tx * TILE + 2, s.ty * TILE + 2, 4, 4);
    }
  };

  /* ------------------------------- units --------------------------------- */
  Renderer.prototype.drawUnits = function (ctx, view) {
