      if (fog && !u.faction.isPlayer && !fog.isVisible(u.tx, u.ty)) continue;
      if (u.def.stealth && !u.faction.isPlayer) {
        var near = world.playerFaction &&
          world.unitsInRadius(u.x, u.y, TILE * 2.5).some(function (o) { return o.faction && o.faction.isPlayer; });
        if (!near) continue;
