      this.drawUnit(ctx, u);
    }
  };

  Renderer.prototype.drawUnit = function (ctx, u) {
    var world = this.world;
    var s = TILE * (u.def.move === 'foot' ? 1.5 : (u.def.hp > 500 ? 1.35 : 1.15));
    var air = u.def.move === 'air';

    ctx.save();
