      ctx.beginPath(); ctx.ellipse(1, s * 0.16, s * 0.34, s * 0.18, 0, 0, U.TAU); ctx.fill();
    }

    ctx.save();
    if (u.def.move !== 'foot') ctx.rotate(u.angle);
    DUNE.Sprites.unitBody(ctx, u.def.id, s, u.faction.colours, {
      time: world.time + u.idleWobble,
      moving: u.moving,
      cargo: u.def.harvester ? U.clamp(u.cargo / CFG.HARVESTER_CAP, 0, 1) : 0,
      carrying: !!u.carrying,
