    ctx.restore();

    // veterancy chevrons
    if (u.veteran > 0) {
      ctx.fillStyle = '#ffd77a';
      for (var v = 0; v < u.veteran; v++) {
        ctx.fillRect(u.x + TILE * 0.28, u.y - TILE * 0.42 + v * 3, 4, 2);
