    this.drawHealthBar(ctx, u, u.x - TILE * 0.45, u.y - TILE * 0.62, TILE * 0.9);
    if (u.def.harvester && u.cargo > 0) {
      var f = U.clamp(u.cargo / CFG.HARVESTER_CAP, 0, 1);
      ctx.fillStyle = 'rgba(10,7,3,.7)';
      ctx.fillRect(u.x - TILE * 0.45, u.y + TILE * 0.5, TILE * 0.9, 3);
      ctx.fillStyle = '#d8621f';
      ctx.fillRect(u.x - TILE * 0.45, u.y + TILE * 0.5, TILE * 0.9 * f, 3);
    }
  };

  Renderer.prototype.drawHealthBar = function (ctx, e, x, y, w) {
    var f = e.healthFrac();
    if (f >= 0.999 && !e.selected) return;
    if (!e.selected && this.world.time - (e.lastHitAt || -99) > 6 && f > 0.95) return;
    ctx.fillStyle = 'rgba(10,7,3,.72)';
    ctx.fillRect(x, y, w, 4);
    ctx.fillStyle = f > 0.6 ? '#5ec46a' : (f > 0.3 ? '#e0b83c' : '#c8352a');
    ctx.fillRect(x + 1, y + 1, (w - 2) * f, 2);
