  /* ----------------------------- projectiles ------------------------------ */
  Renderer.prototype.drawProjectiles = function (ctx) {
    var list = this.world.projectiles;
    for (var i = 0; i < list.length; i++) {
      var p = list[i];
      if (!p.alive) continue;
      var y = p.y - (p.z || 0);
      switch (p.kind) {
        case 'bullet':
          ctx.strokeStyle = 'rgba(255,228,150,.9)';
          ctx.lineWidth = 1.6;
          ctx.beginPath();
          ctx.moveTo(p.x, y);
          ctx.lineTo(p.x - Math.cos(p.angle) * 9, y - Math.sin(p.angle) * 9);
          ctx.stroke();
          break;
        case 'shell':
          ctx.fillStyle = '#e8d6a8';
          ctx.beginPath(); ctx.arc(p.x, y, 2.6, 0, U.TAU); ctx.fill();
          ctx.fillStyle = 'rgba(0,0,0,.25)';
          ctx.beginPath(); ctx.ellipse(p.x, p.y + 2, 3, 1.5, 0, 0, U.TAU); ctx.fill();
          break;
        case 'rocket':
          ctx.save();
          ctx.translate(p.x, y); ctx.rotate(p.angle);
          ctx.fillStyle = '#c8c0b0';
          ctx.fillRect(-5, -1.6, 10, 3.2);
          ctx.fillStyle = '#ff9a3c';
          ctx.beginPath();
          ctx.moveTo(-5, -1.6); ctx.lineTo(-10 - Math.random() * 4, 0); ctx.lineTo(-5, 1.6);
          ctx.closePath(); ctx.fill();
          ctx.restore();
          break;
        case 'gas':
          ctx.fillStyle = 'rgba(126,240,192,.75)';
          ctx.beginPath(); ctx.arc(p.x, y, 4, 0, U.TAU); ctx.fill();
          break;
        case 'sonic':
          ctx.save();
          ctx.translate(p.x, y); ctx.rotate(p.angle);
          ctx.strokeStyle = 'rgba(159,232,255,.8)';
          for (var r = 0; r < 3; r++) {
            ctx.lineWidth = 3 - r;
            ctx.beginPath();
            ctx.arc(-r * 7, 0, 10 + r * 3, -1.1, 1.1);
            ctx.stroke();
          }
          ctx.restore();
          break;
        case 'nuke':
          ctx.save();
          ctx.translate(p.x, y); ctx.rotate(p.angle + Math.PI / 2);
          ctx.fillStyle = '#4a4a52';
          ctx.fillRect(-3, -9, 6, 18);
          ctx.fillStyle = '#c8352a';
          ctx.beginPath(); ctx.moveTo(-3, -9); ctx.lineTo(0, -15); ctx.lineTo(3, -9); ctx.closePath(); ctx.fill();
          ctx.restore();
          break;
      }
    }
  };

  /* ------------------------------ effects --------------------------------- */
  Renderer.prototype.drawEffects = function (ctx) {
    var e = this.world.effects, i, p;
    for (i = 0; i < e.parts.length; i++) {
      p = e.parts[i];
      var k = U.clamp(p.life / p.max, 0, 1);
      switch (p.type) {
        case 'fire':
          ctx.fillStyle = p.c || ('rgba(' + (255) + ',' + Math.round(80 + k * 140) + ',' + Math.round(20 + k * 60) + ',' + k + ')');
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r * (0.4 + k * 0.8), 0, U.TAU); ctx.fill();
          break;
        case 'smoke':
          ctx.fillStyle = 'rgba(60,52,44,' + (k * 0.45) + ')';
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r * (1.6 - k * 0.6), 0, U.TAU); ctx.fill();
          break;
        case 'sand':
          ctx.fillStyle = 'rgba(214,176,108,' + (k * 0.9) + ')';
          ctx.fillRect(p.x, p.y, p.r, p.r);
          break;
        case 'dust':
          ctx.fillStyle = 'rgba(196,164,108,' + (k * 0.35) + ')';
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r * (1.5 - k * 0.5), 0, U.TAU); ctx.fill();
          break;
        case 'spark':
          ctx.fillStyle = 'rgba(255,224,150,' + k + ')';
          ctx.fillRect(p.x, p.y, 2, 2);
          break;
        case 'flash':
          ctx.save();
          ctx.translate(p.x, p.y); ctx.rotate(p.a);
          ctx.fillStyle = 'rgba(255,238,180,' + k + ')';
          ctx.beginPath();
          ctx.moveTo(0, 0); ctx.lineTo(p.r, -p.r * 0.45); ctx.lineTo(p.r * 1.3, 0);
          ctx.lineTo(p.r, p.r * 0.45); ctx.closePath(); ctx.fill();
          ctx.restore();
          break;
      }
    }
    for (i = 0; i < e.beams.length; i++) {
      var b = e.beams[i];
      var bk = b.life / b.max;
      ctx.strokeStyle = b.c;
      ctx.globalAlpha = bk;
      ctx.lineWidth = b.w * bk;
      ctx.beginPath(); ctx.moveTo(b.x1, b.y1); ctx.lineTo(b.x2, b.y2); ctx.stroke();
      ctx.globalAlpha = 1;
    }
    ctx.font = 'bold 11px ' + 'Trebuchet MS, sans-serif';
    ctx.textAlign = 'center';
    for (i = 0; i < e.texts.length; i++) {
      var t = e.texts[i];
      ctx.globalAlpha = U.clamp(t.life / t.max, 0, 1);
      ctx.fillStyle = 'rgba(0,0,0,.6)';
      ctx.fillText(t.s, t.x + 1, t.y + 1);
