  };

  /* -------------------------------- worms --------------------------------- */
  Renderer.prototype.drawWorms = function (ctx) {
    var world = this.world, fog = world.playerFog;
    for (var i = 0; i < world.worms.length; i++) {
      var w = world.worms[i];
      var tx = w.tileX(), ty = w.tileY();
      if (fog && !fog.isVisible(tx, ty) && !fog.isExplored(tx, ty)) continue;
      var seen = !fog || fog.isVisible(tx, ty);
      if (!seen) continue;

      var st = DUNE.Worm.STATE;
      if (w.state === st.DORMANT) continue;

      // the tell-tale sand ripple
      if (w.state === st.HUNT) {
        ctx.strokeStyle = 'rgba(120,86,40,.5)';
        for (var h = 1; h < w.history.length; h += 2) {
          var p = w.history[h];
          var k = 1 - h / w.history.length;
          ctx.lineWidth = 1 + k * 3;
          ctx.globalAlpha = k * 0.6;
          ctx.beginPath();
          ctx.arc(p.x, p.y, TILE * 0.35 * (1 + (1 - k)), 0, U.TAU);
          ctx.stroke();
        }
        ctx.globalAlpha = 1;
        // mound of displaced sand at the head
        ctx.fillStyle = 'rgba(206,168,100,.75)';
        ctx.beginPath();
        ctx.ellipse(w.x, w.y, TILE * 0.55 * w.sizeScale, TILE * 0.35 * w.sizeScale, w.angle, 0, U.TAU);
