      // surfaced: body segments trailing behind the maw
      var rise = w.state === st.RISE ? w.riseT : (w.state === st.DIVE ? w.riseT : 1);
      var size = TILE * 2.6 * w.sizeScale * (0.35 + rise * 0.65);
      for (var seg = 6; seg >= 1; seg--) {
        var hp = w.history[Math.min(w.history.length - 1, seg * 3)];
        if (!hp) continue;
