        ctx.fillStyle = seg % 2 ? '#5b4930' : '#6b5638';
        ctx.beginPath();
        ctx.ellipse(hp.x, hp.y, ss * 0.42, ss * 0.36, w.angle, 0, U.TAU);
        ctx.fill();
