      ctx.rotate(w.angle);
      DUNE.Sprites.wormHead(ctx, size, U.clamp(rise, 0.15, 1));
      ctx.restore();
    }
  };

  /* --------------------------- selection overlay -------------------------- */
  Renderer.prototype.drawSelectionOverlays = function (ctx) {
    var world = this.world;
    var sel = world.selection;
    for (var i = 0; i < sel.length; i++) {
      var e = sel[i];
      if (!e.alive) continue;
      ctx.strokeStyle = '#f0d7a6';
      ctx.lineWidth = 1.6;
      if (e.kind === 'unit') {
        var r = TILE * 0.55;
        ctx.beginPath();
        ctx.arc(e.x, e.y, r, 0, U.TAU);
        ctx.stroke();
        // heading pip
        ctx.fillStyle = '#f0d7a6';
        ctx.beginPath();
        ctx.arc(e.x + Math.cos(e.angle) * r, e.y + Math.sin(e.angle) * r, 2, 0, U.TAU);
        ctx.fill();
        // order line
        if (e.pendingGoal && e.moving) {
          ctx.strokeStyle = 'rgba(240,215,166,.28)';
          ctx.setLineDash([3, 4]);
          ctx.beginPath();
          ctx.moveTo(e.x, e.y);
          ctx.lineTo(world.map.cx(e.pendingGoal.x), world.map.cy(e.pendingGoal.y));
          ctx.stroke();
          ctx.setLineDash([]);
        }
      } else {
        var bx = e.tx * TILE, by = e.ty * TILE, bw = e.w * TILE, bh = e.h * TILE;
        var c = 7;
        ctx.beginPath();
        ctx.moveTo(bx, by + c); ctx.lineTo(bx, by); ctx.lineTo(bx + c, by);
        ctx.moveTo(bx + bw - c, by); ctx.lineTo(bx + bw, by); ctx.lineTo(bx + bw, by + c);
        ctx.moveTo(bx + bw, by + bh - c); ctx.lineTo(bx + bw, by + bh); ctx.lineTo(bx + bw - c, by + bh);
        ctx.moveTo(bx + c, by + bh); ctx.lineTo(bx, by + bh); ctx.lineTo(bx, by + bh - c);
        ctx.stroke();
        if (e.rally) {
          ctx.strokeStyle = 'rgba(94,196,106,.7)';
          ctx.setLineDash([5, 4]);
          ctx.beginPath();
          ctx.moveTo(e.x, e.y);
          ctx.lineTo(world.map.cx(e.rally.x), world.map.cy(e.rally.y));
          ctx.stroke();
          ctx.setLineDash([]);
          ctx.fillStyle = 'rgba(94,196,106,.8)';
          ctx.beginPath();
          ctx.arc(world.map.cx(e.rally.x), world.map.cy(e.rally.y), 4, 0, U.TAU);
          ctx.fill();
        }
      }

      // weapon envelope and firing arc
      var wp = e.kind === 'unit' ? e.weapon() : (e.def.weapon ? DUNE.WEAPONS[e.def.weapon] : null);
      if (wp && (this.showRanges || e.kind === 'structure')) {
        var range = wp.range * e.faction.mods.range * TILE;
        ctx.strokeStyle = 'rgba(240,169,46,.22)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(e.x, e.y, range, 0, U.TAU); ctx.stroke();
        if (wp.minRange) {
          ctx.strokeStyle = 'rgba(200,53,42,.3)';
          ctx.beginPath(); ctx.arc(e.x, e.y, wp.minRange * TILE, 0, U.TAU); ctx.stroke();
        }
        var aim = e.kind === 'unit' ? e.aimAngle() : e.turretAngle;
        var spread = Math.max(wp.arc, 0.14) * 2.2;
        ctx.fillStyle = 'rgba(240,169,46,.10)';
        ctx.beginPath();
        ctx.moveTo(e.x, e.y);
        ctx.arc(e.x, e.y, range, aim - spread, aim + spread);
        ctx.closePath(); ctx.fill();
      }
    }

    // hover highlight
    var hov = this.hoverEntity;
    if (hov && hov.alive && sel.indexOf(hov) < 0) {
      ctx.strokeStyle = 'rgba(240,215,166,.35)';
      ctx.lineWidth = 1;
      if (hov.kind === 'unit') {
        ctx.beginPath(); ctx.arc(hov.x, hov.y, TILE * 0.55, 0, U.TAU); ctx.stroke();
      } else {
        ctx.strokeRect(hov.tx * TILE, hov.ty * TILE, hov.w * TILE, hov.h * TILE);
      }
    }
  };

  Renderer.prototype.drawSelectionBox = function (ctx) {
    var b = this.selectionBox;
    if (!b) return;
    var x = Math.min(b.x0, b.x1), y = Math.min(b.y0, b.y1);
    var w = Math.abs(b.x1 - b.x0), h = Math.abs(b.y1 - b.y0);
    ctx.strokeStyle = '#f0d7a6';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 3]);
    ctx.strokeRect(x, y, w, h);
    ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(240,215,166,.08)';
    ctx.fillRect(x, y, w, h);
  };

  /* ---------------------------- placement ghost --------------------------- */
  Renderer.prototype.drawPlacement = function (ctx) {
    var p = this.placement;
    if (!p) return;
    var def = DUNE.STRUCTS[p.defId];
    var w = def.w * TILE, h = def.h * TILE;
    var px = p.tx * TILE, py = p.ty * TILE;
    var map = this.world.map;

    ctx.save();
    ctx.globalAlpha = 0.72;
    ctx.translate(px, py);
    if (!def.foundation) {
      DUNE.Sprites.structure(ctx, p.defId, w, h, this.world.playerFaction.colours,
        { time: this.world.time, damage: 0 });
    }
    ctx.restore();

    // per-tile validity: green ok, amber ok-but-no-concrete, red illegal
    for (var y = 0; y < def.h; y++) {
      for (var x = 0; x < def.w; x++) {
        var tx = p.tx + x, ty = p.ty + y;
        var ok = p.valid;
        var conc = map.inBounds(tx, ty) && map.concrete[ty * map.w + tx];
        var col = !ok ? 'rgba(200,53,42,.42)'
                : (conc || def.foundation ? 'rgba(94,196,106,.34)' : 'rgba(224,184,60,.34)');
        ctx.fillStyle = col;
        ctx.fillRect(tx * TILE, ty * TILE, TILE, TILE);
        ctx.strokeStyle = 'rgba(0,0,0,.35)';
        ctx.lineWidth = 1;
        ctx.strokeRect(tx * TILE + 0.5, ty * TILE + 0.5, TILE - 1, TILE - 1);
      }
    }

    // adjacency ring: show where the base allows building
    ctx.strokeStyle = 'rgba(240,169,46,.5)';
    ctx.lineWidth = 2;
    ctx.strokeRect(px + 1, py + 1, w - 2, h - 2);

    if (!p.valid && p.reason) {
      ctx.font = 'bold 12px Trebuchet MS, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(10,7,3,.8)';
      ctx.fillRect(px + w / 2 - 60, py - 20, 120, 16);
      ctx.fillStyle = '#ffb9ac';
      ctx.fillText(p.reason, px + w / 2, py - 8);
      ctx.textAlign = 'left';
    }
  };

  /** Faint hatch over every tile your base could legally extend onto. */
  Renderer.prototype.drawBuildOverlay = function (ctx) {
    if (!this.placement) return;
    var world = this.world, map = world.map, f = world.playerFaction;
    var view = this.viewRect();
    var x0 = Math.max(0, Math.floor(view.x / TILE) - 1), x1 = Math.min(map.w - 1, Math.ceil((view.x + view.w) / TILE));
    var y0 = Math.max(0, Math.floor(view.y / TILE) - 1), y1 = Math.min(map.h - 1, Math.ceil((view.y + view.h) / TILE));
    ctx.fillStyle = 'rgba(240,169,46,.07)';
    for (var y = y0; y <= y1; y++) {
      for (var x = x0; x <= x1; x++) {
        var i = y * map.w + x;
        if (map.concrete[i] === f.index + 1) ctx.fillRect(x * TILE, y * TILE, TILE, TILE);
      }
    }
  };

  /* -------------------------------- shroud -------------------------------- */
  Renderer.prototype.drawShroud = function (ctx, view) {
    var fog = this.world.playerFog;
    if (!fog || !fog.enabled) return;
    var map = this.world.map;
    var x0 = Math.max(0, Math.floor(view.x / TILE));
    var x1 = Math.min(map.w - 1, Math.ceil((view.x + view.w) / TILE));
    var y0 = Math.max(0, Math.floor(view.y / TILE));
    var y1 = Math.min(map.h - 1, Math.ceil((view.y + view.h) / TILE));

    for (var y = y0; y <= y1; y++) {
      for (var x = x0; x <= x1; x++) {
        var i = y * map.w + x;
        if (fog.explored[i] === 0) {
          ctx.fillStyle = '#050402';
          ctx.fillRect(x * TILE, y * TILE, TILE + 0.5, TILE + 0.5);
        } else if (fog.visible[i] === 0) {
          ctx.fillStyle = 'rgba(6,5,3,.48)';
          ctx.fillRect(x * TILE, y * TILE, TILE + 0.5, TILE + 0.5);
        }
      }
    }
  };

  DUNE.Renderer = Renderer;
})();
"},{"path":"js/render/sprites.js","type":"text/javascript","text":"/* =============================================================================
   sprites.js - all artwork is drawn with canvas paths at runtime.
   Nothing is loaded from disk, so the project is a single portable folder.

   Structures draw into a (0,0,w,h) box; units draw centred on the origin
   facing +x, and the caller applies the rotation.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;
  var S = DUNE.Sprites = {};

  /* ------------------------------ helpers -------------------------------- */
  function rr(ctx, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(ctx, x, y, w, h, fill, stroke, lw) {
    ctx.fillStyle = fill; ctx.fillRect(x, y, w, h);
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1; ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1); }
  }
  function bevel(ctx, x, y, w, h, base, light, dark) {
    ctx.fillStyle = base; ctx.fillRect(x, y, w, h);
    ctx.fillStyle = light; ctx.fillRect(x, y, w, 2); ctx.fillRect(x, y, 2, h);
    ctx.fillStyle = dark; ctx.fillRect(x, y + h - 2, w, 2); ctx.fillRect(x + w - 2, y, 2, h);
  }
  function rivets(ctx, x, y, w, h, c, step) {
    ctx.fillStyle = c;
    step = step || 8;
    for (var i = x + 3; i < x + w - 2; i += step) {
      ctx.fillRect(i, y + 2, 1.5, 1.5);
      ctx.fillRect(i, y + h - 4, 1.5, 1.5);
