        if (id === 'carryall' && o.carrying) {
          ctx.fillStyle = 'rgba(0,0,0,.35)';
          rr(ctx, -s * 0.3, -s * 0.28, s * 0.6, s * 0.56, s * 0.08); ctx.fill();
        }
        break;
      }
      default: {
        ctx.fillStyle = main;
        rr(ctx, -s * 0.4, -s * 0.3, s * 0.8, s * 0.6, s * 0.08); ctx.fill();
      }
    }
  };

  /** A squad of little figures rather than one big soldier. */
  S.infantrySquad = function (ctx, id, s, c, o) {
    var def = DUNE.UNITS[id];
    var n = def && def.squad ? def.squad : 1;
    var spread = s * 0.24;
    var walk = o.moving ? Math.sin((o.time || 0) * 11 + (o.phase || 0)) : 0;
    var layout = n === 3 ? [[-0.6, -0.7], [0.7, 0], [-0.6, 0.7]]
               : n === 2 ? [[-0.5, -0.5], [0.5, 0.5]]
               : [[0, 0]];
    for (var i = 0; i < layout.length; i++) {
      var px = layout[i][0] * spread, py = layout[i][1] * spread;
      var bob = Math.sin((o.time || 0) * 11 + i * 2) * (o.moving ? s * 0.035 : 0);
      ctx.save();
      ctx.translate(px, py + bob);
      // shadow
      ctx.fillStyle = 'rgba(0,0,0,.25)';
      ctx.beginPath(); ctx.ellipse(0, s * 0.13, s * 0.09, s * 0.04, 0, 0, U.TAU); ctx.fill();
      // legs
      ctx.strokeStyle = c.dark; ctx.lineWidth = Math.max(1, s * 0.035);
      ctx.beginPath();
      ctx.moveTo(0, s * 0.02); ctx.lineTo(-s * 0.04 + walk * s * 0.03, s * 0.12);
      ctx.moveTo(0, s * 0.02); ctx.lineTo(s * 0.04 - walk * s * 0.03, s * 0.12);
      ctx.stroke();
      // torso
      ctx.fillStyle = c.main;
      rr(ctx, -s * 0.05, -s * 0.08, s * 0.10, s * 0.13, s * 0.03); ctx.fill();
      // head
      ctx.fillStyle = id === 'fremen' ? '#c8b48a' : c.light;
      ctx.beginPath(); ctx.arc(0, -s * 0.11, s * 0.042, 0, U.TAU); ctx.fill();
      // weapon pointing forward
      ctx.strokeStyle = '#2a251f'; ctx.lineWidth = Math.max(1, s * 0.03);
      ctx.beginPath();
      ctx.moveTo(s * 0.02, -s * 0.03);
      ctx.lineTo(s * (id === 'trooper' ? 0.15 : 0.12), -s * (id === 'trooper' ? 0.08 : 0.04));
      ctx.stroke();
      if (id === 'saboteur') {
        ctx.fillStyle = 'rgba(180,255,220,.35)';
        ctx.beginPath(); ctx.arc(0, -s * 0.02, s * 0.14, 0, U.TAU); ctx.fill();
      }
      ctx.restore();
    }
  };

  /** Turrets and gun mounts, drawn on top of the body at their own angle. */
  S.unitTurret = function (ctx, id, s, c, o) {
    o = o || {};
    var rec = (o.recoil || 0) * s * 0.10;
    switch (id) {
      case 'tank': {
        ctx.fillStyle = c.dark;
        ctx.beginPath(); ctx.ellipse(0, 0, s * 0.22, s * 0.19, 0, 0, U.TAU); ctx.fill();
        ctx.fillStyle = c.main;
        ctx.beginPath(); ctx.ellipse(0, 0, s * 0.17, s * 0.15, 0, 0, U.TAU); ctx.fill();
        ctx.fillStyle = '#3a342c';
        ctx.fillRect(s * 0.10 - rec, -s * 0.045, s * 0.42, s * 0.09);
        ctx.fillStyle = '#211d17';
        ctx.fillRect(s * 0.48 - rec, -s * 0.05, s * 0.06, s * 0.10);
        break;
      }
      case 'siege': {
        ctx.fillStyle = c.dark;
        rr(ctx, -s * 0.22, -s * 0.20, s * 0.44, s * 0.40, s * 0.06); ctx.fill();
        ctx.fillStyle = c.main;
        rr(ctx, -s * 0.15, -s * 0.14, s * 0.32, s * 0.28, s * 0.05); ctx.fill();
        ctx.fillStyle = '#3a342c';
        ctx.fillRect(s * 0.12 - rec, -s * 0.06, s * 0.54, s * 0.12);
        ctx.fillStyle = '#5a5249';
        ctx.fillRect(s * 0.30 - rec, -s * 0.09, s * 0.10, s * 0.18);
        break;
      }
      case 'devastator': {
        ctx.fillStyle = c.dark;
        rr(ctx, -s * 0.24, -s * 0.22, s * 0.48, s * 0.44, s * 0.05); ctx.fill();
        ctx.fillStyle = c.main;
        rr(ctx, -s * 0.16, -s * 0.16, s * 0.34, s * 0.32, s * 0.04); ctx.fill();
        ctx.fillStyle = '#332e26';
        ctx.fillRect(s * 0.10 - rec, -s * 0.16, s * 0.46, s * 0.10);
        ctx.fillRect(s * 0.10 - rec, s * 0.06, s * 0.46, s * 0.10);
        ctx.fillStyle = '#ff9a3c';
        ctx.fillRect(-s * 0.06, -s * 0.05, s * 0.10, s * 0.10);
        break;
      }
      case 'rocketlauncher': {
        ctx.fillStyle = c.dark;
        rr(ctx, -s * 0.20, -s * 0.20, s * 0.42, s * 0.40, s * 0.05); ctx.fill();
        ctx.fillStyle = '#3d372f';
        for (var r = 0; r < 3; r++) {
          ctx.fillRect(-s * 0.05, -s * 0.17 + r * s * 0.12, s * 0.40, s * 0.09);
          ctx.fillStyle = '#a03a26';
          ctx.fillRect(s * 0.30, -s * 0.16 + r * s * 0.12, s * 0.05, s * 0.07);
          ctx.fillStyle = '#3d372f';
        }
        break;
      }
      case 'sonictank': {
        ctx.fillStyle = c.dark;
        ctx.beginPath(); ctx.ellipse(0, 0, s * 0.21, s * 0.19, 0, 0, U.TAU); ctx.fill();
        ctx.fillStyle = '#2a3a44';
        ctx.beginPath();
        ctx.moveTo(s * 0.10, -s * 0.16); ctx.lineTo(s * 0.52, -s * 0.22);
        ctx.lineTo(s * 0.52, s * 0.22); ctx.lineTo(s * 0.10, s * 0.16);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = '#9fe8ff'; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(s * 0.52, 0, s * 0.16, -1.1, 1.1); ctx.stroke();
        break;
      }
      case 'deviator': {
        ctx.fillStyle = c.dark;
        ctx.beginPath(); ctx.ellipse(0, 0, s * 0.20, s * 0.18, 0, 0, U.TAU); ctx.fill();
        ctx.fillStyle = '#2f5a48';
        ctx.fillRect(s * 0.08 - rec, -s * 0.09, s * 0.40, s * 0.18);
        ctx.fillStyle = '#7ef0c0';
        ctx.beginPath(); ctx.arc(s * 0.48 - rec, 0, s * 0.08, 0, U.TAU); ctx.fill();
        break;
      }
      case 'quad': {
        ctx.fillStyle = c.dark;
        ctx.beginPath(); ctx.ellipse(0, 0, s * 0.14, s * 0.12, 0, 0, U.TAU); ctx.fill();
        ctx.fillStyle = '#3a342c';
        ctx.fillRect(s * 0.08 - rec, -s * 0.09, s * 0.30, s * 0.05);
        ctx.fillRect(s * 0.08 - rec, s * 0.04, s * 0.30, s * 0.05);
        break;
      }
      case 'trike': case 'raider': {
        ctx.fillStyle = '#3a342c';
        ctx.fillRect(s * 0.02 - rec, -s * 0.035, s * 0.26, s * 0.07);
        break;
      }
      default: break;
    }
  };

  /* ------------------------------- worm ---------------------------------- */
  S.wormHead = function (ctx, s, open) {
    var r = s * 0.5;
    ctx.fillStyle = '#6b5638';
    ctx.beginPath(); ctx.ellipse(0, 0, r, r * 0.92, 0, 0, U.TAU); ctx.fill();
    ctx.fillStyle = '#4e3f28';
    ctx.beginPath(); ctx.ellipse(0, 0, r * 0.8, r * 0.74, 0, 0, U.TAU); ctx.fill();
    // maw
    ctx.fillStyle = '#1a0f07';
    ctx.beginPath(); ctx.ellipse(0, 0, r * 0.55 * open, r * 0.52 * open, 0, 0, U.TAU); ctx.fill();
    ctx.fillStyle = '#d9c9a8';
    var teeth = 11;
    for (var i = 0; i < teeth; i++) {
      var a = (i / teeth) * U.TAU;
      var tr = r * 0.55 * open;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * tr, Math.sin(a) * tr);
      ctx.lineTo(Math.cos(a + 0.16) * tr * 0.62, Math.sin(a + 0.16) * tr * 0.62);
      ctx.lineTo(Math.cos(a - 0.16) * tr * 0.62, Math.sin(a - 0.16) * tr * 0.62);
      ctx.closePath(); ctx.fill();
    }
  };

  /* ------------------------------- crests -------------------------------- */
  S.crest = function (ctx, houseId, size) {
    var h = DUNE.house(houseId);
    var c = DUNE.houseColours(houseId);
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.fillStyle = c.dark;
    ctx.beginPath();
    ctx.moveTo(0, -size * 0.46);
    ctx.lineTo(size * 0.4, -size * 0.2);
    ctx.lineTo(size * 0.4, size * 0.18);
    ctx.lineTo(0, size * 0.48);
    ctx.lineTo(-size * 0.4, size * 0.18);
    ctx.lineTo(-size * 0.4, -size * 0.2);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = c.light; ctx.lineWidth = Math.max(1, size * 0.04); ctx.stroke();

    ctx.fillStyle = c.main;
    ctx.beginPath();
    ctx.moveTo(0, -size * 0.36);
    ctx.lineTo(size * 0.31, -size * 0.15);
    ctx.lineTo(size * 0.31, size * 0.14);
    ctx.lineTo(0, size * 0.38);
    ctx.lineTo(-size * 0.31, size * 0.14);
    ctx.lineTo(-size * 0.31, -size * 0.15);
    ctx.closePath(); ctx.fill();

    ctx.fillStyle = c.light;
    ctx.strokeStyle = c.light;
    ctx.lineWidth = Math.max(1, size * 0.045);
    var s = size;
    switch (h.crest) {
      case 'hawk':   // Atreides: stooping hawk
        ctx.beginPath();
        ctx.moveTo(0, -s * 0.16);
        ctx.lineTo(s * 0.22, -s * 0.02); ctx.lineTo(s * 0.07, s * 0.02);
        ctx.lineTo(0, s * 0.19);
        ctx.lineTo(-s * 0.07, s * 0.02); ctx.lineTo(-s * 0.22, -s * 0.02);
        ctx.closePath(); ctx.fill();
        break;
      case 'ram':    // Harkonnen: horned ram
        ctx.beginPath(); ctx.arc(0, 0, s * 0.10, 0, U.TAU); ctx.fill();
        ctx.beginPath(); ctx.arc(-s * 0.13, -s * 0.02, s * 0.11, 0.4, 4.2); ctx.stroke();
        ctx.beginPath(); ctx.arc(s * 0.13, -s * 0.02, s * 0.11, -1.1, 2.7); ctx.stroke();
        break;
      case 'coil':   // Ordos: coiled serpent
        ctx.beginPath();
        for (var t = 0; t < 26; t++) {
          var a = t * 0.42, rr2 = s * 0.03 + t * s * 0.0075;
          var px = Math.cos(a) * rr2, py = Math.sin(a) * rr2;
          if (t === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
        }
        ctx.stroke();
        break;
      default:       // Imperial crown
        ctx.beginPath();
        ctx.moveTo(-s * 0.2, s * 0.1); ctx.lineTo(-s * 0.14, -s * 0.12);
        ctx.lineTo(0, s * 0.0); ctx.lineTo(s * 0.14, -s * 0.12);
        ctx.lineTo(s * 0.2, s * 0.1); ctx.closePath(); ctx.fill();
    }
    ctx.restore();
  };

  /* ------------------------- sidebar build icons ------------------------- */
  S.icon = function (canvas, id, houseId) {
    var ctx = canvas.getContext('2d');
    var w = canvas.width, h = canvas.height;
    var c = DUNE.houseColours(houseId);
    ctx.clearRect(0, 0, w, h);
    // background
    var g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#2a2016'); g.addColorStop(1, '#14100a');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);

    var sdef = DUNE.STRUCTS[id];
    if (sdef) {
      if (sdef.foundation) {
        ctx.fillStyle = '#8a8175';
        var n = id === 'concrete4' ? 2 : 1;
        var cell = Math.min(w, h) * 0.62 / n;
        for (var y = 0; y < n; y++) {
          for (var x = 0; x < n; x++) {
            ctx.fillStyle = '#7d766a';
            ctx.fillRect(w / 2 - (n * cell) / 2 + x * cell + 1, h / 2 - (n * cell) / 2 + y * cell + 1, cell - 2, cell - 2);
            ctx.strokeStyle = '#4a443c'; ctx.lineWidth = 1;
            ctx.strokeRect(w / 2 - (n * cell) / 2 + x * cell + 1.5, h / 2 - (n * cell) / 2 + y * cell + 1.5, cell - 3, cell - 3);
          }
        }
        return;
      }
      var sw = Math.min(w - 4, sdef.w * 13), sh = Math.min(h - 4, sdef.h * 13);
      ctx.save();
      ctx.translate((w - sw) / 2, (h - sh) / 2);
      ctx.scale(sw / (sdef.w * CFG.TILE), sh / (sdef.h * CFG.TILE));
      S.structure(ctx, id, sdef.w * CFG.TILE, sdef.h * CFG.TILE, c, { time: 0, damage: 0 });
      if (sdef.weapon) {
        ctx.save();
        ctx.translate(sdef.w * CFG.TILE / 2, sdef.h * CFG.TILE / 2);
        ctx.rotate(-0.6);
        S.turretHead(ctx, id, CFG.TILE * 1.3, c, {});
        ctx.restore();
      }
      ctx.restore();
      return;
    }

    var udef = DUNE.UNITS[id];
    if (udef) {
      ctx.save();
      ctx.translate(w / 2, h / 2);
      ctx.rotate(-0.45);
      var s = Math.min(w, h) * 1.35;
      S.unitBody(ctx, id, s, c, { time: 0, cargo: 0.6, moving: false });
      if (udef.turret) S.unitTurret(ctx, id, s, c, {});
      ctx.restore();
    }
  };

  /* --------------------------- mentat portrait --------------------------- */
  /** A stylised, House-tinted talking head for the briefing screen. */
  S.mentat = function (ctx, houseId, w, h, t, talking) {
    var c = DUNE.houseColours(houseId);
    var house = DUNE.house(houseId);
    ctx.clearRect(0, 0, w, h);

    // backdrop
    var g = ctx.createRadialGradient(w / 2, h * 0.36, 10, w / 2, h * 0.5, w * 0.85);
    g.addColorStop(0, U.mix(house.colour, '#000000', 0.55));
    g.addColorStop(1, '#0a0705');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);

    // hanging drapes
    ctx.fillStyle = 'rgba(0,0,0,.35)';
    for (var d = 0; d < 7; d++) {
      var dx = d * (w / 7);
      ctx.beginPath();
      ctx.moveTo(dx, 0);
      ctx.quadraticCurveTo(dx + w / 14, h * 0.18, dx + w / 7, 0);
      ctx.closePath(); ctx.fill();
    }

    var cx = w / 2, cy = h * 0.46;
    var breathe = Math.sin(t * 1.4) * 2;

    // shoulders / robe
    ctx.fillStyle = house.colourDark;
    ctx.beginPath();
    ctx.moveTo(cx - w * 0.42, h);
    ctx.quadraticCurveTo(cx - w * 0.30, h * 0.66, cx, h * 0.64 + breathe * 0.5);
    ctx.quadraticCurveTo(cx + w * 0.30, h * 0.66, cx + w * 0.42, h);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = house.colour;
    ctx.beginPath();
    ctx.moveTo(cx - w * 0.30, h);
    ctx.quadraticCurveTo(cx - w * 0.20, h * 0.72, cx, h * 0.70 + breathe * 0.5);
    ctx.quadraticCurveTo(cx + w * 0.20, h * 0.72, cx + w * 0.30, h);
    ctx.closePath(); ctx.fill();

    // collar
    ctx.fillStyle = house.colourLight;
    ctx.fillRect(cx - w * 0.16, h * 0.70 + breathe * 0.5, w * 0.32, 4);

    // neck + head
    ctx.fillStyle = '#c9a37a';
    ctx.fillRect(cx - 16, cy + 44 + breathe, 32, 26);
    ctx.fillStyle = '#d9b48a';
    ctx.beginPath();
    ctx.ellipse(cx, cy + breathe, 52, 62, 0, 0, U.TAU);
    ctx.fill();
    // cheekbones / shading
    ctx.fillStyle = 'rgba(120,80,50,.28)';
    ctx.beginPath(); ctx.ellipse(cx - 34, cy + 12 + breathe, 14, 20, 0.3, 0, U.TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(cx + 34, cy + 12 + breathe, 14, 20, -0.3, 0, U.TAU); ctx.fill();

    // hair / hood
    ctx.fillStyle = houseId === 'harkonnen' ? '#2a1a14' : (houseId === 'ordos' ? '#0f2a22' : '#3a2a18');
    ctx.beginPath();
    ctx.ellipse(cx, cy - 26 + breathe, 54, 40, 0, Math.PI, U.TAU);
    ctx.fill();
    ctx.fillRect(cx - 54, cy - 26 + breathe, 10, 46);
    ctx.fillRect(cx + 44, cy - 26 + breathe, 10, 46);

    // brows
    ctx.strokeStyle = '#3a2618'; ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(cx - 32, cy - 14 + breathe); ctx.lineTo(cx - 10, cy - 18 + breathe);
    ctx.moveTo(cx + 32, cy - 14 + breathe); ctx.lineTo(cx + 10, cy - 18 + breathe);
    ctx.stroke();

    // eyes - spice-blue sclera, the Mentat mark
    var blink = (Math.sin(t * 0.9) > 0.985) ? 0.15 : 1;
    [[-20, 1], [20, -1]].forEach(function (e) {
      ctx.fillStyle = '#f2e7d2';
      ctx.beginPath();
      ctx.ellipse(cx + e[0], cy - 2 + breathe, 12, 8 * blink, 0, 0, U.TAU); ctx.fill();
      ctx.fillStyle = '#2b6fd8';
      ctx.beginPath();
      ctx.ellipse(cx + e[0] + Math.sin(t * 0.7) * 2, cy - 2 + breathe, 5.5, 5.5 * blink, 0, 0, U.TAU); ctx.fill();
      ctx.fillStyle = '#07121f';
      ctx.beginPath();
      ctx.ellipse(cx + e[0] + Math.sin(t * 0.7) * 2, cy - 2 + breathe, 2.4, 2.4 * blink, 0, 0, U.TAU); ctx.fill();
    });

    // nose
    ctx.strokeStyle = 'rgba(120,80,50,.5)'; ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(cx, cy + 2 + breathe); ctx.lineTo(cx - 4, cy + 18 + breathe);
    ctx.lineTo(cx + 5, cy + 19 + breathe); ctx.stroke();

    // mouth - animates while the briefing types
    var open = talking ? (2 + Math.abs(Math.sin(t * 13)) * 9) : 2;
    ctx.fillStyle = '#7a3b32';
    ctx.beginPath();
    ctx.ellipse(cx, cy + 34 + breathe, 15, open, 0, 0, U.TAU); ctx.fill();
    ctx.strokeStyle = '#8a5a48'; ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx - 16, cy + 33 + breathe); ctx.lineTo(cx + 16, cy + 33 + breathe); ctx.stroke();

    // House sigil on the shoulder
    ctx.save();
    ctx.translate(cx - w * 0.30, h * 0.82);
    S.crest(ctx, houseId, 38);
    ctx.restore();

    // vignette
    var vg = ctx.createRadialGradient(w / 2, h / 2, w * 0.3, w / 2, h / 2, w * 0.78);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,.72)');
    ctx.fillStyle = vg; ctx.fillRect(0, 0, w, h);
  };
})();
"},{"path":"js/systems/ai.js","type":"text/javascript","text":"/* =============================================================================
   ai.js - the enemy commander.

   The AI plays the same game the player does: it orders buildings from its own
   Construction Yard, pays for concrete, places them against its base, runs
   harvesters to refineries, notices when its field is running dry and sends an
   MCV out to found a second base, and masses units into waves before attacking.
   Nothing is spawned from nowhere.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  function AI(world, faction, o) {
    o = o || {};
    this.world = world;
    this.f = faction;
    this.aggr = o.aggr == null ? 0.6 : o.aggr;      // 0 = turtle, 1.2 = relentless
    this.eco = o.eco == null ? 1 : o.eco;
    this.think = 0.4 + Math.random();
    this.rnd = U.rng(o.seed || ((Math.random() * 1e9) | 0));

    this.squad = [];
    this.squadTarget = null;
    this.squadRefresh = 0;
    this.waveNo = 0;
    // the first wave never comes before the player has had time to build
    this.nextWaveAt = 80 + 60 / Math.max(0.3, this.aggr);
    this.defending = false;
    this.defendT = 0;
    this.expanding = null;
    this.pavedSpend = 0;

    this.buildOrder = this.makeBuildOrder();
    this.boIndex = 0;
  }

  /* --------------------------- opening build order ----------------------- */
  AI.prototype.makeBuildOrder = function () {
    var h = this.f.houseId;
    var inf = (h === 'atreides') ? 'barracks' : 'wor';
    // economy and the Heavy Factory (which builds Harvesters) come first;
    // an AI that turtles behind turrets with no spice loses to itself
    return [
      'windtrap', 'refinery', 'lightfactory', 'radar', 'windtrap',
      'heavyfactory', 'turret', inf, 'silo', 'refinery',
      'windtrap', 'repair', 'rturret', 'hightech', 'turret',
      'windtrap', 'ix', 'starport', 'palace', 'rturret'
    ];
  };

  /* -------------------------------- update ------------------------------- */
  AI.prototype.update = function (dt) {
    var f = this.f;
    if (f.defeated) return;

    this.think -= dt;
    this.defendT -= dt;
    this.squadRefresh -= dt;

    if (this.think > 0) return;
    this.think = CFG.AI_THINK * (0.8 + this.rnd() * 0.5);

    // losing every harvester is fatal, so nothing else gets funded until the
    // spice is flowing again
    this.economyStalled = f.has('refinery') && f.countUnits('harvester') === 0;
    this.economyCritical = this.economyStalled &&
      f.queuedCount('heavyfactory', 'harvester') === 0;

    this.placeReady();
    this.manageBase();
    this.manageEconomy();
    this.manageArmy();
    this.manageDefence();
    this.manageExpansion();
    this.manageAttack();
  };

  /* ---------------------- place anything waiting to go ------------------- */
  AI.prototype.placeReady = function () {
    var f = this.f;
    var q = f.queues['structure'];
    if (!q || !q.items.length) return;
    var it = q.items[0];
    if (it.state !== 'ready') return;

    var def = DUNE.STRUCTS[it.id];
    var site = this.findSite(def);
    if (!site) {
      // nowhere sensible right now; drop it and try something else later
      if (this.rnd() < 0.3) f.cancel('structure', it.id);
      return;
    }
    this.paveFor(def, site.x, site.y);
    var s = this.world.placeStructure(it.id, f, site.x, site.y);
    if (s) {
      U.remove(q.items, it);
      if (def.produces && !f.primaryOf[def.produces]) f.primaryOf[def.produces] = s;
    }
  };

  /** Buys concrete slabs under a planned building, exactly as a player would. */
  AI.prototype.paveFor = function (def, tx, ty) {
    if (def.foundation) return;
    var f = this.f, map = this.world.map;
    var price = DUNE.STRUCTS.concrete.cost * f.mods.cost;
    for (var y = 0; y < def.h; y++) {
      for (var x = 0; x < def.w; x++) {
        var cx = tx + x, cy = ty + y;
        var i = cy * map.w + cx;
        if (map.concrete[i]) continue;
        if (f.credits < price * 2) return;
        f.spend(price);
        map.setConcrete(cx, cy, f.index + 1);
      }
    }
  };

  /**
   * Finds a legal spot for a building: adjacent to the base, on rock if
   * possible, out of the way of factory exits, and turrets pushed toward the
   * threat.
   */
  AI.prototype.findSite = function (def) {
    var f = this.f, world = this.world, map = world.map;
    var centre = f.baseCentre();
    if (!centre) return null;

    var toward = null;
    if (def.weapon) {
      var enemy = world.nearestEnemyBase(f);
      if (enemy) toward = U.angleTo(centre.x, centre.y, enemy.x / CFG.TILE, enemy.y / CFG.TILE);
    }
    if (def.id === 'refinery' && this.expandSite) toward = null;

    var best = null, bestScore = -Infinity, checks = 0;
    for (var r = 1; r <= 13 && checks < 900; r++) {
      for (var dy = -r; dy <= r; dy++) {
        for (var dx = -r; dx <= r; dx++) {
          if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
          var tx = centre.x + dx, ty = centre.y + dy;
          if (!map.inBounds(tx, ty) || !map.inBounds(tx + def.w, ty + def.h)) continue;
          checks++;
          if (checks > 900) break;
          var res = DUNE.Structure.checkPlacement(world, def.id, f, tx, ty);
          if (!res.ok) continue;

          var score = -r * 1.4;
          score += res.concrete * 1.2;
          // prefer rock underneath
          var rocky = 0;
          for (var yy = 0; yy < def.h; yy++) {
            for (var xx = 0; xx < def.w; xx++) {
              if (map.terrainAt(tx + xx, ty + yy) === DUNE.T.ROCK) rocky++;
            }
          }
          score += rocky * 1.6;
          // keep spice fields clear for the harvesters
          if (map.spiceAround(tx, ty, 2) > 100) score -= 8;
          if (toward != null) {
            var a = U.angleTo(centre.x, centre.y, tx, ty);
            score += Math.cos(U.angDiff(a, toward)) * 7;
          }
          if (def.weapon) score += r * 1.1;              // turrets on the perimeter
          if (score > bestScore) { bestScore = score; best = { x: tx, y: ty }; }
        }
      }
      if (best && r >= 4) break;
    }
    return best;
  };

  /* ------------------------------ base plan ------------------------------ */
  AI.prototype.manageBase = function () {
    var f = this.f;
    var q = f.queue('structure');
    if (!f.has('construction')) return;

    // 0. Emergency. With no Harvester and no Heavy Factory to build one, a
    //    fresh Refinery is the only way back - so drop whatever is queued and
    //    put every credit behind it.
    // No harvester and no credits is a death spiral. Sell something to break
    // out of it, exactly as a human would.
    if (this.economyStalled) this.emergencyFunds();

    if (this.economyCritical && !f.canBuild('harvester').ok) {
      var head = q.items[0];
      if (head && head.id === 'refinery') return;
      if (head && head.state !== 'ready') f.cancel('structure', head.id);
      this.dumpUnitQueues();
      if (!q.items.length && f.canBuild('refinery').ok) f.enqueue('refinery');
      return;
    }
    if (q.items.length > 0) return;
    if (this.economyCritical) return;

    // 1. keep the lights on
    var margin = f.powerMade - f.powerUsed;
    if (margin < 45 && f.canBuild('windtrap').ok) {
      f.enqueue('windtrap');
      return;
    }
    // 2. an economy before anything else
    if (!f.has('refinery') && f.canBuild('refinery').ok) { f.enqueue('refinery'); return; }
    // 3. storage if we keep overflowing
    if (f.credits > f.capacity * 0.92 && f.canBuild('silo').ok && f.count('silo') < 3) {
      f.enqueue('silo'); return;
    }
    // 4. more refineries as the economy grows
    var wantRef = U.clamp(Math.round(1 + this.eco), 1, 3);
    if (f.count('refinery') < wantRef && f.credits > 900 && f.canBuild('refinery').ok) {
      f.enqueue('refinery'); return;
    }
    // 4b. rebuild anything important that has been shot out from under us -
    //     the opening book only moves forwards, so this is what covers losses
    for (var r = 0; r < REBUILD.length; r++) {
      var rid = REBUILD[r];
      if (!f.everBuilt[rid] || f.has(rid)) continue;
      if (!f.canBuild(rid).ok) continue;
      if (f.credits < f.priceOf(rid) * 1.1) continue;
      f.enqueue(rid);
      return;
    }

    // 5. defences scale with how long the mission has run
    var wantTurrets = Math.min(7, 1 + Math.floor(this.world.time / 110) + Math.round(this.aggr * 2));
    var turrets = f.count('turret') + f.count('rturret');
    // the first couple of turrets are cheap insurance; the rest wait until
    // there is money spare, so defences never starve the tech path
    var turretBudget = turrets >= 2 ? 1000 : 340;
    if (turrets < wantTurrets && f.credits > turretBudget) {
      if (f.canBuild('rturret').ok && f.credits > 900) { f.enqueue('rturret'); return; }
      if (f.canBuild('turret').ok) { f.enqueue('turret'); return; }
    }
    // 6. otherwise walk the opening book
    while (this.boIndex < this.buildOrder.length) {
      var id = this.buildOrder[this.boIndex];
      var def = DUNE.STRUCTS[id];
      var already = f.count(id);
      var wantCount = (id === 'windtrap') ? 99 : (id === 'turret' || id === 'rturret') ? 99 : 1;
      if (already >= wantCount || !f.canBuild(id).ok) { this.boIndex++; continue; }
      if (f.credits < def.cost * 1.15) return;      // save up
      f.enqueue(id);
      this.boIndex++;
      return;
    }
  };

  /* Buildings worth putting back up the moment they are lost. */
  var REBUILD = ['refinery', 'lightfactory', 'radar', 'heavyfactory', 'repair', 'hightech', 'wor', 'barracks'];

  /* Buildings the commander will part with, cheapest regret first. */
  var SELLABLE = ['silo', 'barracks', 'wor', 'turret', 'starport', 'lightfactory', 'rturret', 'radar'];

  /** Sells a spare structure so the spice can start flowing again. */
  AI.prototype.emergencyFunds = function () {
    var f = this.f, world = this.world;
    var needed = f.canBuild('harvester').ok ? f.priceOf('harvester') : f.priceOf('refinery');
    if (f.credits > needed * 0.55) return;
    if (world.time - (this._soldT || -99) < 15) return;

    for (var s = 0; s < SELLABLE.length; s++) {
      var id = SELLABLE[s];
      var list = f.structures.filter(function (b) { return b.alive && b.def.id === id; });
      if (!list.length) continue;
      this._soldT = world.time;
      list[list.length - 1].sell();
      return;
