  };

  /** Refunds and clears every factory order, freeing the credits. */
  AI.prototype.dumpUnitQueues = function () {
    var f = this.f;
    for (var k in f.queues) {
      if (k === 'structure') continue;
      while (f.queues[k].items.length) f.cancel(k);
    }
  };

  /**
   * What the base planner will ask for next. Used to hold money back so unit
   * production cannot starve the tech path - the failure mode where an AI
   * builds trikes forever and never raises a Heavy Factory.
   */
  AI.prototype.nextPlanItem = function () {
    var f = this.f;
    if (f.powerMade - f.powerUsed < 45 && f.canBuild('windtrap').ok) return 'windtrap';
    if (!f.has('refinery') && f.canBuild('refinery').ok) return 'refinery';
    for (var i = this.boIndex; i < this.buildOrder.length; i++) {
      var id = this.buildOrder[i];
      var many = (id === 'windtrap' || id === 'turret' || id === 'rturret');
      if (!many && f.count(id) > 0) continue;
      if (!f.canBuild(id).ok) continue;
      return id;
    }
    return null;
  };

  /* ------------------------------- economy ------------------------------- */
  AI.prototype.manageEconomy = function () {
    var f = this.f;
    var refs = f.count('refinery');
    if (!refs) return;
    var want = Math.min(6, Math.round(refs * (1.4 + this.eco * 0.6)));
    var have = f.countUnits('harvester') + f.queuedCount('heavyfactory', 'harvester');
    if (have < want && f.canBuild('harvester').ok &&
        (f.credits > 420 || this.economyCritical)) {
      f.enqueue('harvester');
    }
    // idle harvesters get back to work
    for (var i = 0; i < f.units.length; i++) {
      var u = f.units[i];
      if (u.alive && u.def.harvester && u.isIdle() && u.hstate === 'idle') u.autoHarvest();
    }
    // a carryall pays for itself once the fields are far away
    if (f.canBuild('carryall').ok && f.countUnits('carryall') < 1 && f.credits > 1400) {
      f.enqueue('carryall');
    }
  };

  /* -------------------------------- army --------------------------------- */
  AI.prototype.armyWishlist = function () {
    var f = this.f, out = [];
    var h = f.houseId;
    if (f.canBuild('tank').ok) out.push(['tank', 3]);
    if (f.canBuild('quad').ok) out.push(['quad', 2]);
    if (f.canBuild('trike').ok) out.push(['trike', 2]);
    if (f.canBuild('raider').ok) out.push(['raider', 2]);
    if (f.canBuild('trooper').ok) out.push(['trooper', 2]);
    if (f.canBuild('infantry').ok) out.push(['infantry', 2]);
    if (f.canBuild('siege').ok) out.push(['siege', 2]);
    if (f.canBuild('rocketlauncher').ok) out.push(['rocketlauncher', 1]);
    if (h === 'atreides' && f.canBuild('sonictank').ok) out.push(['sonictank', 1]);
    if (h === 'harkonnen' && f.canBuild('devastator').ok) out.push(['devastator', 1]);
    if (h === 'ordos' && f.canBuild('deviator').ok) out.push(['deviator', 1]);
    if (f.canBuild('ornithopter').ok) out.push(['ornithopter', 1]);
    return out;
  };

  AI.prototype.manageArmy = function () {
    var f = this.f;
    if (this.economyCritical) return;
    var list = this.armyWishlist();
    if (!list.length) return;

    // money earmarked for the base plan is off limits to the factories
    var reserve = 0;
    var sq = f.queues['structure'];
    if (sq && sq.items.length && sq.items[0].state !== 'ready') {
      reserve = sq.items[0].cost * (1 - sq.items[0].progress);
    } else {
      var next = this.nextPlanItem();
      if (next) reserve = f.priceOf(next) * 1.15;
    }
    if (f.credits < reserve + 320) return;

    // do not flood the factory queues either
    var totalQueued = 0;
    for (var k in f.queues) {
      if (k === 'structure') continue;
      totalQueued += f.queues[k].items.length;
    }
    if (totalQueued >= 2) return;

    var army = f.armyUnits().length;
    var cap = 10 + Math.round(this.aggr * 14) + Math.floor(this.world.time / 80);
    if (army >= cap) return;

    // weighted pick
    var total = 0, i;
    for (i = 0; i < list.length; i++) total += list[i][1];
    var roll = this.rnd() * total;
    for (i = 0; i < list.length; i++) {
      roll -= list[i][1];
      if (roll <= 0) { f.enqueue(list[i][0]); return; }
    }
  };

  /* ------------------------------ defence -------------------------------- */
  AI.prototype.manageDefence = function () {
    var f = this.f, world = this.world;
    var threatened = null;
    for (var i = 0; i < f.structures.length; i++) {
      var s = f.structures[i];
      if (s.alive && world.time - s.lastHitAt < 6) { threatened = s; break; }
    }
    if (!threatened) {
      for (var j = 0; j < f.units.length; j++) {
        var hu = f.units[j];
        if (hu.alive && hu.def.harvester && world.time - hu.lastHitAt < 5) { threatened = hu; break; }
      }
    }
    if (!threatened) { this.defending = false; return; }

    this.defending = true;
    this.defendT = 12;
    var army = f.armyUnits();
    var responders = 0;
    for (var a = 0; a < army.length && responders < 9; a++) {
      var u = army[a];
      if (this.squad.indexOf(u) >= 0 && U.dist(u.x, u.y, threatened.x, threatened.y) > CFG.TILE * 26) continue;
      if (U.dist(u.x, u.y, threatened.x, threatened.y) > CFG.TILE * 30) continue;
      if (u.order.t === 'attack' && u.order.target && u.order.target.alive &&
          U.dist(u.x, u.y, u.order.target.x, u.order.target.y) < CFG.TILE * 8) continue;
      u.setOrder({ t: 'amove', x: threatened.tx, y: threatened.ty });
      responders++;
    }
  };

  /* ----------------------------- expansion ------------------------------- */
  AI.prototype.manageExpansion = function () {
    var f = this.f, world = this.world, map = world.map;
    var centre = f.baseCentre();
    if (!centre) return;

    // running out of spice nearby?
    var near = map.spiceAround(centre.x, centre.y, 14);
    if (this.expanding) {
      var mcv = this.expanding;
      if (!mcv.alive) { this.expanding = null; return; }
      if (!mcv.moving && !mcv.step && U.cheb(mcv.tx, mcv.ty, this.expandSite.x, this.expandSite.y) <= 3) {
        mcv.setOrder({ t: 'deploy' });
        this.expanding = null;
      } else if (!mcv.pendingGoal) {
        mcv.gotoTile(this.expandSite.x, this.expandSite.y);
      }
      return;
    }

    if (near > 4200) return;
    if (!f.canBuild('mcv').ok) return;
    if (f.credits < 1400) return;

    var existing = f.structures.filter(function (s) { return s.def.id === 'construction'; })
                              .map(function (s) { return { x: s.tx, y: s.ty }; });
    var region = map.bestSpiceRegion(existing, 14);
    if (!region) return;

    // find dry ground beside the field to put the yard on
    var site = map.spiral(region.x, region.y, 9, function (x, y) {
      var t = map.terrainAt(x, y);
      if (t === DUNE.T.ROCK && map.building[y * map.w + x] === 0) return { x: x, y: y };
      return null;
    }) || { x: region.x, y: region.y };

    this.expandSite = site;
    var have = f.countUnits('mcv');
    if (have > 0) {
      for (var i = 0; i < f.units.length; i++) {
        if (f.units[i].alive && f.units[i].def.id === 'mcv') {
          this.expanding = f.units[i];
          f.units[i].gotoTile(site.x, site.y);
          return;
        }
      }
    }
    if (f.queuedCount('heavyfactory', 'mcv') === 0) f.enqueue('mcv');
  };

  /* ------------------------------- attacks ------------------------------- */
  AI.prototype.waveSize = function () {
    var t = this.world.time;
    var base = 3 + this.aggr * 3;
    return Math.min(20, Math.round(base + t / 95 * (1 + this.aggr)));
  };

  AI.prototype.manageAttack = function () {
    var f = this.f, world = this.world;
    if (this.aggr <= 0.01) return;

    // prune the dead
    this.squad = this.squad.filter(function (u) { return u.alive; });

    if (this.squad.length) {
      if (this.squadRefresh <= 0) {
        this.squadRefresh = 5;
        var tgt = this.squadTarget;
        if (!tgt || !tgt.alive) {
          tgt = this.pickTarget();
          this.squadTarget = tgt;
        }
        if (!tgt) { this.releaseSquad(); return; }
        for (var i = 0; i < this.squad.length; i++) {
          var u = this.squad[i];
          if (!u.alive) continue;
          if (u.target && u.target.alive && DUNE.Combat.rangeTo(u, u.target) < u.attackRange()) continue;
          u.setOrder({ t: 'amove', x: tgt.tx, y: tgt.ty });
        }
      }
      if (this.squad.length < 2) this.releaseSquad();
      return;
    }

    if (this.defending) return;
    if (world.time < this.nextWaveAt) return;

    var army = f.armyUnits().filter(function (u) {
      return u.order.t === 'guard' || u.order.t === 'stop';
    });
    var need = this.waveSize();
    if (army.length < need) return;

    var target = this.pickTarget();
    if (!target) return;

    this.waveNo++;
    this.squadTarget = target;
    this.squad = army.slice(0, Math.min(army.length, need + 4));
    this.squadRefresh = 0;
    this.nextWaveAt = world.time + Math.max(45, 130 - this.aggr * 45 - this.waveNo * 3);

    for (var s = 0; s < this.squad.length; s++) {
      this.squad[s].setOrder({ t: 'amove', x: target.tx, y: target.ty });
    }
    if (world.playerFaction && this.isTargetingPlayer(target)) {
      world.onEnemyWave(this.f, this.squad.length);
    }
  };

  AI.prototype.isTargetingPlayer = function (t) {
    return t && t.faction && t.faction.isPlayer;
  };

  AI.prototype.releaseSquad = function () {
    for (var i = 0; i < this.squad.length; i++) {
      if (this.squad[i].alive) this.squad[i].setOrder({ t: 'guard' });
    }
    this.squad = [];
    this.squadTarget = null;
  };

  /** Chooses what the wave goes after: harvesters, defences, or the yard. */
  AI.prototype.pickTarget = function () {
    var world = this.world, f = this.f;
    var enemies = world.factions.filter(function (o) { return o !== f && !o.defeated && f.isEnemyOf(o); });
    if (!enemies.length) return null;

    var centre = f.baseCentre();
    var cx = centre ? centre.x * CFG.TILE : 0, cy = centre ? centre.y * CFG.TILE : 0;

    // harassing the economy is the highest-value play and the AI knows it
    if (this.rnd() < 0.3 + this.aggr * 0.2) {
      var best = null, bestD = Infinity;
      for (var e = 0; e < enemies.length; e++) {
        var eu = enemies[e].units;
        for (var i = 0; i < eu.length; i++) {
          var u = eu[i];
          if (!u.alive || !u.def.harvester || u.hidden) continue;
          var d = U.dist2(cx, cy, u.x, u.y);
          if (d < bestD) { bestD = d; best = u; }
        }
      }
      if (best) return best;
    }

    var bestS = null, bestScore = -Infinity;
    for (var k = 0; k < enemies.length; k++) {
      var list = enemies[k].structures;
      for (var j = 0; j < list.length; j++) {
        var s = list[j];
        if (!s.alive) continue;
        var dist = U.dist(cx, cy, s.x, s.y) / CFG.TILE;
        var score = -dist;
        if (s.def.id === 'refinery') score += 14;
        if (s.def.id === 'construction') score += 10;
        if (s.def.produces) score += 6;
        if (s.def.weapon) score -= 4;
        if (score > bestScore) { bestScore = score; bestS = s; }
      }
    }
    return bestS;
  };

  DUNE.AI = AI;
})();
