(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  var Combat = DUNE.Combat = {};

  /** Distance in pixels, measured to the edge of a building footprint. */
  Combat.rangeTo = function (from, to) {
    var d = U.dist(from.x, from.y, to.x, to.y);
    if (to.kind === 'structure') d -= to.radius() * 0.75;
    return Math.max(0, d);
  };

  /** Direct-fire weapons will not shoot through a mountain ridge. */
  Combat.canSee = function (from, to) {
    var map = from.world.map;
    var steps = Math.ceil(U.dist(from.x, from.y, to.x, to.y) / CFG.TILE);
    if (steps <= 1) return true;
    for (var s = 1; s < steps; s++) {
      var t = s / steps;
      var x = Math.floor(U.lerp(from.x, to.x, t) / CFG.TILE);
      var y = Math.floor(U.lerp(from.y, to.y, t) / CFG.TILE);
      if (map.terrainAt(x, y) === DUNE.T.MOUNTAIN) return false;
    }
    return true;
  };

  /**
   * Picks what an entity should shoot at.
   * Priority: something already shooting at us > armed units > harvesters
   * (kill the economy) > everything else. Distance breaks ties.
   */
  Combat.findTarget = function (self, weapon, rangeTiles) {
    var world = self.world;
    var range = rangeTiles * CFG.TILE;
    var best = null, bestScore = -Infinity;
    var i, list;

    var cands = world.entitiesInRadius(self.x, self.y, range + CFG.TILE * 2);
    for (i = 0; i < cands.length; i++) {
      var e = cands[i];
      if (!e.alive || e === self) continue;
      if (!self.faction.isEnemyOf(e.faction)) continue;
      if (e.hidden) continue;
      if (e.def.stealth && U.dist(self.x, self.y, e.x, e.y) > CFG.TILE * 2.2) continue;
      if (e.def.move === 'air' && !weapon.air) continue;
      if (e.kind === 'structure' && e.def.foundation) continue;

      var d = Combat.rangeTo(self, e);
      if (d > range) continue;
      if (weapon.minRange && d < weapon.minRange * CFG.TILE) continue;
      if (!Combat.canSee(self, e)) continue;

      var score = 100 - (d / CFG.TILE) * 3.2;
      if (e.kind === 'unit') {
        if (e.def.weapon) score += 26;
        if (e.def.harvester) score += 34;
        if (e.def.move === 'air') score += 12;
        // finish off what is nearly dead
        score += (1 - e.healthFrac()) * 14;
      } else {
        score += e.def.weapon ? 22 : 2;     // enemy turrets first
        if (e.def.id === 'construction') score += 8;
      }
