      score += DUNE.damageMultiplier(weapon.warhead, e.def.armour) * 18;

      if (score > bestScore) { bestScore = score; best = e; }
    }
    return best;
  };

  Combat.nearestEnemyStructure = function (self) {
    var world = self.world, best = null, bestD = Infinity;
    for (var i = 0; i < world.structures.length; i++) {
      var s = world.structures[i];
      if (!s.alive || !self.faction.isEnemyOf(s.faction)) continue;
      var d = U.dist2(self.x, self.y, s.x, s.y);
      if (d < bestD) { bestD = d; best = s; }
    }
    return best;
  };

  /* ----------------------------- damage ---------------------------------- */
  Combat.applyDamage = function (target, amount, warhead, source, world) {
    if (!target || !target.alive) return 0;
    var mult = DUNE.damageMultiplier(warhead, target.def.armour);
    var dealt = amount * mult;
    if (dealt <= 0) return 0;

    // buildings on bare sand are structurally compromised and take more
    if (target.kind === 'structure' && target.uncoveredTiles && target.uncoveredTiles() > 0) {
      dealt *= 1 + 0.12 * (target.uncoveredTiles() / target.footTiles);
    }

    var before = target.hp;
    target.damage(dealt, source);

    if (source && source.faction && world) {
      if (target.faction && target.faction.isPlayer && world.time - (world._lastAttackWarn || -99) > 12) {
        world._lastAttackWarn = world.time;
        if (target.kind === 'structure') {
          world.notify('Our base is under attack!', 'bad');
          DUNE.Sfx.play('alarm', 0.9);
          world.flashOnMinimap(target.x, target.y);
        }
      }
    }

    if (!target.alive && before > 0 && source && source.kind === 'unit') {
      source.kills = (source.kills || 0) + 1;
      if (source.kills >= CFG.VETERANCY_KILLS && source.veteran < 2) {
        source.veteran++;
        source.kills = 0;
        if (source.faction && source.faction.isPlayer) {
          world.effects.text(source.x, source.y - 16, 'VETERAN', '#ffd77a');
        }
      }
    }
    return dealt;
  };

  /** Total combat strength of a list of entities - used by the AI. */
  Combat.strength = function (list) {
    var s = 0;
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (!e.alive) continue;
      s += DUNE.combatValue(e.def) * e.healthFrac();
    }
    return s;
  };

  /** Is this point inside the threat envelope of an enemy defence? */
  Combat.threatAt = function (world, faction, x, y) {
    var t = 0;
    for (var i = 0; i < world.structures.length; i++) {
      var s = world.structures[i];
      if (!s.alive || s.faction === faction || !s.def.weapon) continue;
      var w = DUNE.WEAPONS[s.def.weapon];
      var d = U.dist(x, y, s.x, s.y);
      if (d < w.range * CFG.TILE * 1.2) t += w.dmg / w.rof;
    }
    return t;
  };
})();
"},{"path":"js/systems/faction.js","type":"text/javascript","text":"/* =============================================================================
   faction.js - a side in the battle: its credits, spice storage, power grid,
   tech unlocks and production queues.

   Credits and spice are the same pool, as in Dune II: a harvester unloading
   raises your credit balance, and you can only hold as much as your Refineries
   and Silos have room for.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  function Faction(world, o) {
    this.world = world;
    this.index = o.index;
    this.id = o.id || ('f' + o.index);
    this.houseId = o.house;
    this.house = DUNE.house(o.house);
    this.mods = this.house.mods;
    this.isPlayer = !!o.isPlayer;
    this.name = this.house.full;
    this.colour = this.house.colour;
    this.colours = DUNE.houseColours(o.house);
    this.tech = o.tech || 9;
    this.defeated = false;

    this.credits = o.credits || 1500;
    this.capacity = CFG.BASE_STORAGE;
    this.spiceHarvested = 0;
    this.spiceLost = 0;

    this.structures = [];
    this.units = [];
    this.counts = {};            // live structure counts by def id
    this.everBuilt = {};         // for "structure unlocks structure" memory

    this.powerMade = 0;
    this.powerUsed = 0;

    this.queues = {};            // key -> {items:[], }
    this.primaryOf = {};         // producer type -> chosen structure

    this.special = null;         // palace weapon state
    this.allies = [];

    this.stats = { built: 0, lost: 0, kills: 0, spice: 0 };
  }

  /* ------------------------------ economy -------------------------------- */
  Faction.prototype.canAfford = function (n) { return this.credits >= n; };
  Faction.prototype.spend = function (n) {
    this.credits = Math.max(0, this.credits - n);
  };
  Faction.prototype.refund = function (n) { this.addCredits(n); };

  /** Refunds and mission grants ignore storage; only harvested spice spills. */
  Faction.prototype.addCredits = function (n) {
    this.credits += n;
  };

  /** Spice delivered by a harvester. Overflow beyond storage blows away. */
  Faction.prototype.addSpice = function (amount, harvester) {
    var room = Math.max(0, this.capacity - this.credits);
    var take = Math.min(room, amount * CFG.SPICE_TO_CREDITS);
    this.credits += take;
    this.spiceHarvested += take;
    this.stats.spice += take;
    var lost = amount - take;
    if (lost > 0.1) {
      this.spiceLost += lost;
      if (this.isPlayer) {
        this.world.notify('Spice storage full — build a Silo', 'bad', 'silofull');
      }
    }
    return take;
  };

  /* ------------------------------- roster -------------------------------- */
  Faction.prototype.addStructure = function (s) {
    this.structures.push(s);
    this.everBuilt[s.def.id] = (this.everBuilt[s.def.id] || 0) + 1;
    this.recount();
  };
  Faction.prototype.removeStructure = function (s) {
    U.remove(this.structures, s);
    for (var k in this.primaryOf) {
      if (this.primaryOf[k] === s) delete this.primaryOf[k];
    }
    this.recount();
  };
  Faction.prototype.addUnit = function (u) { this.units.push(u); };
  Faction.prototype.removeUnit = function (u) { U.remove(this.units, u); };

  /** Recomputes power, storage and structure counts. Cheap; called on change. */
  Faction.prototype.recount = function () {
    var made = 0, used = 0, cap = CFG.BASE_STORAGE;
    var counts = {};
    for (var i = 0; i < this.structures.length; i++) {
      var s = this.structures[i];
      if (!s.alive) continue;
      counts[s.def.id] = (counts[s.def.id] || 0) + 1;
      if (s.building) continue;
      var p = s.def.power;
      // a damaged windtrap makes less power
      if (p > 0) made += p * (0.4 + 0.6 * s.healthFrac());
      else used -= p;
      if (s.def.storage) cap += s.def.storage;
    }
    this.counts = counts;
    this.powerMade = made;
    this.powerUsed = used;
    this.capacity = cap;
  };

  Faction.prototype.powerRatio = function () {
    if (this.powerUsed <= 0) return 1;
    return U.clamp(this.powerMade / this.powerUsed, CFG.MIN_POWER_RATIO, 1);
  };
  Faction.prototype.hasPower = function () { return this.powerMade >= this.powerUsed; };

  Faction.prototype.has = function (defId) { return (this.counts[defId] || 0) > 0; };
  Faction.prototype.count = function (defId) { return this.counts[defId] || 0; };

  Faction.prototype.countUnits = function (defId) {
    var n = 0;
    for (var i = 0; i < this.units.length; i++) {
      if (this.units[i].alive && this.units[i].def.id === defId) n++;
    }
    return n;
  };

  Faction.prototype.armyUnits = function () {
    var out = [];
    for (var i = 0; i < this.units.length; i++) {
      var u = this.units[i];
      if (u.alive && u.def.weapon && !u.def.harvester && u.def.move !== 'air') out.push(u);
    }
    return out;
  };

  /* ---------------------------- base queries ----------------------------- */
  Faction.prototype.primaryStructure = function () {
    for (var i = 0; i < this.structures.length; i++) {
      if (this.structures[i].alive && this.structures[i].def.primary) return this.structures[i];
    }
    return this.structures.length ? this.structures[0] : null;
  };

  Faction.prototype.baseCentre = function () {
    if (!this.structures.length) {
      if (this.units.length) return { x: this.units[0].tx, y: this.units[0].ty };
      return null;
    }
    var sx = 0, sy = 0, n = 0;
    for (var i = 0; i < this.structures.length; i++) {
      var s = this.structures[i];
      if (!s.alive) continue;
      sx += s.tx; sy += s.ty; n++;
    }
    if (!n) return null;
    return { x: Math.round(sx / n), y: Math.round(sy / n) };
  };

  Faction.prototype.nearestStructure = function (defId, x, y, filter) {
    var best = null, bestD = Infinity;
    for (var i = 0; i < this.structures.length; i++) {
      var s = this.structures[i];
      if (!s.alive || s.building) continue;
      if (defId && s.def.id !== defId) continue;
      if (filter && !filter(s)) continue;
      var d = U.dist2(x, y, s.x, s.y);
      if (d < bestD) { bestD = d; best = s; }
    }
    return best;
  };

  Faction.prototype.nearestRefinery = function (x, y, preferFree) {
    var free = this.nearestStructure('refinery', x, y, function (s) { return !s.dockUnit; });
    if (free || !preferFree) return free || this.nearestStructure('refinery', x, y);
    return this.nearestStructure('refinery', x, y);
  };

  /* ============================ tech and queues ========================== */
  /**
   * Can this faction order `defId` right now?
   * @return {object} {ok, reason, missing}
   */
  Faction.prototype.canBuild = function (defId, opts) {
    var def = DUNE.STRUCTS[defId] || DUNE.UNITS[defId];
    if (!def) return { ok: false, reason: 'Unknown' };
    var viaStarport = !!(opts && opts.starport);

    if (def.kind === 'structure') {
      if (!DUNE.houseAllowsStruct(def, this.houseId)) return { ok: false, reason: 'Not available to your House' };
    } else {
      if (!DUNE.houseAllowsUnit(def, this.houseId)) return { ok: false, reason: 'Not available to your House' };
    }
    if (def.tech > this.tech) return { ok: false, reason: 'Tech level ' + def.tech + ' required' };

    var missing = [];
    for (var i = 0; i < def.requires.length; i++) {
      if (!this.has(def.requires[i])) missing.push(DUNE.STRUCTS[def.requires[i]].name);
    }
    if (def.kind === 'unit') {
      // the whole point of the Starport is buying hardware you cannot build
      if (viaStarport) {
        if (!this.has('starport')) missing.push('Starport');
      } else if (!def.from || !this.has(def.from)) {
        missing.push(DUNE.STRUCTS[def.from] ? DUNE.STRUCTS[def.from].name : def.from);
      }
    } else {
      if (!this.has('construction') && defId !== 'construction') {
        missing.push('Construction Yard');
      }
    }
    if (missing.length) return { ok: false, reason: 'Requires ' + missing.join(' + '), missing: missing };

    if (def.unique && this.has(defId)) return { ok: false, reason: 'Only one permitted' };
    return { ok: true };
  };

  Faction.prototype.queueKey = function (defId) {
    var def = DUNE.STRUCTS[defId];
    if (def) return 'structure';
    var ud = DUNE.UNITS[defId];
    return ud ? ud.from : 'structure';
  };

  Faction.prototype.queue = function (key) {
    if (!this.queues[key]) this.queues[key] = { items: [], key: key };
    return this.queues[key];
  };

  /** Cost after House modifiers (and the Starport discount). */
  Faction.prototype.priceOf = function (defId, viaStarport) {
    var def = DUNE.STRUCTS[defId] || DUNE.UNITS[defId];
    var c = def.cost * (def.foundation ? 1 : this.mods.cost);
    if (viaStarport) c *= CFG.STARPORT_DISCOUNT;
    return Math.round(c);
  };

  Faction.prototype.buildSeconds = function (defId) {
    var def = DUNE.STRUCTS[defId] || DUNE.UNITS[defId];
    var t = Math.max(CFG.MIN_BUILD_SECONDS, def.cost * CFG.BUILD_SECONDS_PER_CREDIT * this.mods.build);
    if (def.foundation) t = 1.2;
    return t;
  };

  /** Number of factories of this type - each one speeds the shared queue. */
  Faction.prototype.producerCount = function (key) {
    if (key === 'structure') return Math.max(1, this.count('construction'));
    return Math.max(1, this.count(key));
  };

  Faction.prototype.enqueue = function (defId, opts) {
    opts = opts || {};
    var check = this.canBuild(defId, opts);
    if (!check.ok) return check;
    var key = opts.starport ? 'starport' : this.queueKey(defId);
    var q = this.queue(key);
    if (q.items.length >= CFG.MAX_QUEUE) return { ok: false, reason: 'Queue full' };
    q.items.push({
      id: defId,
      progress: 0,
      paid: 0,
      cost: this.priceOf(defId, !!opts.starport),
      seconds: this.buildSeconds(defId),
      state: 'building',
      starport: !!opts.starport,
      delivery: 0
    });
    return { ok: true };
  };

  /** Cancels the last item in a queue (or a ready structure), refunding it. */
  Faction.prototype.cancel = function (key, defId) {
    var q = this.queue(key);
    for (var i = q.items.length - 1; i >= 0; i--) {
      if (!defId || q.items[i].id === defId) {
        var it = q.items[i];
        this.addCredits(it.paid);
        q.items.splice(i, 1);
        return true;
      }
    }
    return false;
  };

  Faction.prototype.queuedCount = function (key, defId) {
    var q = this.queues[key];
    if (!q) return 0;
    var n = 0;
    for (var i = 0; i < q.items.length; i++) if (q.items[i].id === defId) n++;
    return n;
  };

  Faction.prototype.activeItem = function (key, defId) {
    var q = this.queues[key];
    if (!q || !q.items.length) return null;
    var head = q.items[0];
    if (defId && head.id !== defId) return null;
    return head;
  };

  /* ------------------------------ production ----------------------------- */
  Faction.prototype.updateQueues = function (dt) {
    var ratio = this.powerRatio();
    for (var key in this.queues) {
      var q = this.queues[key];
      if (!q.items.length) continue;
      var it = q.items[0];

      if (it.state === 'ready') continue;          // waiting for the player to place
      if (it.state === 'delivering') {
        it.delivery -= dt;
        if (it.delivery <= 0) { this.completeItem(q, it); }
        continue;
      }

      // the factory must still exist
      if (key !== 'structure' && !this.has(key)) { q.items.length = 0; continue; }
      if (key === 'structure' && !this.has('construction')) { continue; }

      var speed = ratio * Math.min(2.5, 0.6 + 0.4 * this.producerCount(key));
      var dProg = (dt / it.seconds) * speed;
      var want = it.cost * dProg;

      if (this.credits < want) {
        // build stalls when the credits run out
        it.state = 'hold';
        var afford = this.credits;
        if (afford <= 0.01) continue;
        dProg = afford / it.cost;
        want = afford;
      } else {
        it.state = 'building';
      }

      this.spend(want);
      it.paid += want;
      it.progress = Math.min(1, it.progress + dProg);

      if (it.progress >= 1) {
        if (it.starport) {
          it.state = 'delivering';
          it.delivery = CFG.STARPORT_DELAY;
          if (this.isPlayer) this.world.notify('Guild frigate inbound', 'good');
          DUNE.Sfx.play('frigate', 0.6);
        } else if (DUNE.STRUCTS[it.id]) {
          it.state = 'ready';
          if (this.isPlayer) {
            this.world.notify(DUNE.STRUCTS[it.id].name + ' ready — place it', 'good');
            DUNE.Sfx.play('ready', 1);
          }
        } else {
          this.completeItem(q, it);
        }
      }
    }
  };

  Faction.prototype.completeItem = function (q, it) {
    U.remove(q.items, it);
    var def = DUNE.UNITS[it.id];
    if (!def) return;
    var producer = it.starport
      ? this.nearestStructure('starport', 0, 0)
      : this.pickProducer(def.from);
    this.spawnUnit(it.id, producer, it.starport);
  };

  Faction.prototype.pickProducer = function (type) {
    if (this.primaryOf[type] && this.primaryOf[type].alive) return this.primaryOf[type];
    return this.nearestStructure(type, 0, 0);
  };

  Faction.prototype.spawnUnit = function (defId, producer, viaStarport) {
    var world = this.world;
    var spot = null;
    if (producer) spot = producer.exitTile();
    if (!spot) {
      var c = this.baseCentre();
      if (c) spot = world.map.findFreeTile(c.x, c.y, DUNE.UNITS[defId].move, 10, -1);
    }
    if (!spot) return null;

    var u = world.createUnit(defId, this, spot.x, spot.y);
    if (!u) return null;
    this.stats.built++;

    if (viaStarport) {
      world.effects.sandBurst(u.x, u.y, 18);
      DUNE.Sfx.play('deploy', 0.8, world.audioDist(u.x, u.y));
    } else {
      DUNE.Sfx.play('build', 0.7, world.audioDist(u.x, u.y));
    }

    if (producer && producer.rally) {
      u.setOrder({ t: 'move', x: producer.rally.x, y: producer.rally.y });
    } else if (u.def.harvester) {
      u.hstate = 'idle';
    }
    if (this.isPlayer) this.world.notify(u.def.name + ' ready', 'good', 'unit' + defId);
    return u;
  };

  /* --------------------------- palace special ---------------------------- */
  Faction.prototype.updateSpecial = function (dt) {
    var sp = this.house.palace;
    if (!sp) return;
    if (!this.has('palace')) { this.special = null; return; }
    if (!this.special) {
      this.special = { id: sp.id, name: sp.name, cooldown: sp.cooldown, timer: sp.cooldown * 0.5, ready: false };
    }
    if (!this.special.ready) {
      this.special.timer -= dt * this.powerRatio();
      if (this.special.timer <= 0) {
        this.special.ready = true;
        this.special.timer = 0;
        if (this.isPlayer) {
          this.world.notify(sp.name + ' is ready', 'good');
          DUNE.Sfx.play('ready', 1);
        }
      }
    }
  };

  Faction.prototype.useSpecial = function (tx, ty) {
    if (!this.special || !this.special.ready) return false;
    var world = this.world;
    var ok = world.fireSpecial(this, this.special.id, tx, ty);
    if (ok) {
      this.special.ready = false;
      this.special.timer = this.house.palace.cooldown;
    }
    return ok;
  };

  /* -------------------------------- update ------------------------------- */
  Faction.prototype.update = function (dt) {
    this.updateQueues(dt);
    this.updateSpecial(dt);
    this._recountT = (this._recountT || 0) - dt;
    if (this._recountT <= 0) { this._recountT = 0.5; this.recount(); }
  };

  /** A faction is beaten when it has no buildings and nothing that shoots. */
  Faction.prototype.isEliminated = function () {
    for (var i = 0; i < this.structures.length; i++) if (this.structures[i].alive) return false;
    for (var j = 0; j < this.units.length; j++) {
      var u = this.units[j];
      if (u.alive && (u.def.weapon || u.def.deploy)) return false;
    }
    return true;
  };

  Faction.prototype.isEnemyOf = function (other) {
    if (other === this) return false;
    return this.allies.indexOf(other) < 0;
  };

  DUNE.Faction = Faction;
})();
"},{"path":"js/ui/campaignmap.js","type":"text/javascript","text":"/* =============================================================================
   campaignmap.js - the chart of Arrakis between missions.

   The campaign is not a fixed running order: each mission the player is shown
   two or three territories and picks which one to invade. Conquered ground
   fills with your House colour; contested ground shows who holds it.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util;
  var UI = DUNE.UI = DUNE.UI || {};

  var canvas, ctx, raf = 0;
  var state = null, choices = [], hover = null, picked = null, onAttack = null;
  var t = 0;
  var sandPattern = null;

  function init() {
    if (canvas) return;
    canvas = U.$('#campaign-canvas');
    ctx = canvas.getContext('2d');

    canvas.addEventListener('mousemove', function (e) {
      var p = toCanvas(e);
      hover = hitTest(p.x, p.y);
      canvas.style.cursor = (hover && isChoice(hover)) ? 'pointer' : 'default';
      showInfo(hover);
    });
    canvas.addEventListener('mouseleave', function () { hover = null; showInfo(picked); });
    canvas.addEventListener('click', function (e) {
      var p = toCanvas(e);
      var terr = hitTest(p.x, p.y);
      if (terr && isChoice(terr)) {
        picked = terr;
        DUNE.Sfx.play('select', 0.9);
        showInfo(terr);
        U.$('#cm-attack').disabled = false;
      } else if (terr) {
        DUNE.Sfx.play('deny', 0.5);
      }
    });

    U.on('#cm-attack', 'click', function () {
      if (!picked) return;
      DUNE.Sfx.play('order', 1);
      stop();
      if (onAttack) onAttack(picked);
    });
  }

  function toCanvas(e) {
    var r = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - r.left) * (canvas.width / r.width),
      y: (e.clientY - r.top) * (canvas.height / r.height)
    };
  }

  function isChoice(terr) {
    return choices.indexOf(terr) >= 0;
  }

  function hitTest(x, y) {
    var list = DUNE.CAMPAIGN.TERRITORIES;
    for (var i = 0; i < list.length; i++) {
      if (U.pointInPoly(x, y, list[i].poly)) return list[i];
    }
    return null;
  }

  /* ------------------------------ side panel ----------------------------- */
  function showInfo(terr) {
    var body = U.$('#cm-terr-body');
    var name = U.$('#cm-terr-name');
    if (!terr) {
      name.textContent = '—';
      body.innerHTML = '<p class="dim">Hover a highlighted territory to scout it.</p>';
      return;
    }
    name.textContent = terr.name;
    var owned = state.owned.indexOf(terr.id) >= 0;
    var holder = state.holders[terr.id];
    var html = '';

    if (owned) html += '<div class="tag" style="border-color:' + DUNE.house(state.house).colour +
                       ';color:' + DUNE.house(state.house).colourLight + '">YOURS</div>';
    else if (holder) html += '<div class="tag" style="border-color:' + DUNE.house(holder).colour +
                       ';color:' + DUNE.house(holder).colourLight + '">' +
                       DUNE.house(holder).name.toUpperCase() + ' HELD</div>';
    else if (isChoice(terr)) html += '<div class="tag" style="border-color:#f0a92e;color:#f0a92e">TARGET</div>';
    else html += '<div class="tag dim">UNSURVEYED</div>';

    html += '<p>' + terr.note + '</p>';
    html += '<div class="kv"><span>SPICE</span><b>' + rate(terr.spice) + '</b></div>';
    html += '<div class="kv"><span>ROCK COVER</span><b>' + rate(terr.rock) + '</b></div>';
    html += '<div class="kv"><span>RESISTANCE</span><b>' + rate(terr.risk) + '</b></div>';

    if (isChoice(terr)) {
      var enemies = DUNE.CAMPAIGN.enemiesFor(state.mission, terr.id, state.house);
      html += '<div class="kv"><span>DEFENDERS</span><b>' +
              (enemies.length ? enemies.map(function (h) { return DUNE.house(h).name; }).join(', ')
                              : 'Scattered patrols') + '</b></div>';
      html += '<p class="dim" style="margin-top:8px">Low rock cover means more concrete to pour — and ' +
              'buildings founded on open sand will rot.</p>';
    }
    body.innerHTML = html;
  }

  function rate(v) {
    return ['■□□ Low', '■■□ Moderate', '■■■ High'][U.clamp(v - 1, 0, 2)];
  }

  /* -------------------------------- draw --------------------------------- */
  function drawBackdrop() {
    var w = canvas.width, h = canvas.height;
    var g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#6b4e24');
    g.addColorStop(0.45, '#8a6532');
    g.addColorStop(1, '#5d4320');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // dune bands
    ctx.strokeStyle = 'rgba(60,40,16,.18)';
    ctx.lineWidth = 2;
    for (var i = 0; i < 26; i++) {
      var y = i * 24 + Math.sin(i) * 6;
      ctx.beginPath();
      ctx.moveTo(0, y);
      for (var x = 0; x <= w; x += 60) {
        ctx.quadraticCurveTo(x + 30, y + Math.sin((x + i * 40) * 0.01) * 10, x + 60, y);
      }
      ctx.stroke();
    }
    // polar caps
    ctx.fillStyle = 'rgba(226,214,188,.10)';
    ctx.beginPath(); ctx.ellipse(w * 0.14, 30, 150, 46, 0, 0, U.TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(w * 0.6, h - 8, 210, 40, 0, 0, U.TAU); ctx.fill();

    // vignette
    var vg = ctx.createRadialGradient(w / 2, h / 2, h * 0.3, w / 2, h / 2, h * 0.95);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(20,12,4,.75)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, w, h);
  }

  function drawTerritory(terr) {
    var owned = state.owned.indexOf(terr.id) >= 0;
    var holder = state.holders[terr.id];
    var choice = isChoice(terr);
    var isHover = hover === terr;
    var isPicked = picked === terr;

    ctx.beginPath();
    var p = terr.poly;
    ctx.moveTo(p[0][0], p[0][1]);
    for (var i = 1; i < p.length; i++) {
      var prev = p[i - 1], cur = p[i];
      ctx.quadraticCurveTo(prev[0], prev[1], (prev[0] + cur[0]) / 2, (prev[1] + cur[1]) / 2);
    }
    ctx.closePath();

    if (owned) {
      ctx.fillStyle = U.alpha(DUNE.house(state.house).colour, 0.42);
    } else if (holder) {
      ctx.fillStyle = U.alpha(DUNE.house(holder).colour, 0.30);
    } else if (choice) {
      var pulse = 0.18 + 0.12 * Math.sin(t * 3);
      ctx.fillStyle = 'rgba(240,169,46,' + (isPicked ? 0.42 : pulse) + ')';
    } else {
      ctx.fillStyle = 'rgba(30,20,8,0.18)';
    }
    ctx.fill();

    ctx.lineWidth = isPicked ? 3.5 : (choice ? 2.4 : 1.2);
    ctx.strokeStyle = isPicked ? '#ffe2a0'
      : choice ? (isHover ? '#ffd77a' : '#f0a92e')
      : owned ? DUNE.house(state.house).colourLight
      : holder ? DUNE.house(holder).colourLight
      : 'rgba(40,28,12,.55)';
    ctx.stroke();

    // label
    ctx.font = (choice || owned ? 'bold ' : '') + '12px Trebuchet MS, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(12,8,3,.72)';
    ctx.fillText(terr.name, terr.x + 1, terr.y + 1);
    ctx.fillStyle = choice ? '#fff0cf' : (owned ? '#fff' : 'rgba(240,220,180,.62)');
    ctx.fillText(terr.name, terr.x, terr.y);

    if (choice && !owned) {
      var r = 16 + Math.sin(t * 3.4) * 3;
      ctx.strokeStyle = 'rgba(240,169,46,.75)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(terr.x, terr.y + 18, r, 0, U.TAU); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(terr.x - r - 5, terr.y + 18); ctx.lineTo(terr.x - r + 5, terr.y + 18);
      ctx.moveTo(terr.x + r - 5, terr.y + 18); ctx.lineTo(terr.x + r + 5, terr.y + 18);
      ctx.moveTo(terr.x, terr.y + 13 - r); ctx.lineTo(terr.x, terr.y + 23 - r);
      ctx.stroke();
    }
    if (owned) {
      ctx.save();
      ctx.translate(terr.x, terr.y + 22);
      DUNE.Sprites.crest(ctx, state.house, 22);
      ctx.restore();
    } else if (holder) {
      ctx.save();
      ctx.translate(terr.x, terr.y + 22);
      DUNE.Sprites.crest(ctx, holder, 18);
      ctx.restore();
    }
    ctx.textAlign = 'left';
  }

  function loop() {
    raf = requestAnimationFrame(loop);
    t += 1 / 60;
    drawBackdrop();
    var list = DUNE.CAMPAIGN.TERRITORIES;
    for (var i = 0; i < list.length; i++) drawTerritory(list[i]);

    // heading
    ctx.font = 'bold 13px Trebuchet MS, sans-serif';
    ctx.fillStyle = 'rgba(255,232,190,.85)';
    ctx.fillText('MISSION ' + state.mission + ' OF ' + DUNE.CAMPAIGN.count +
                 ' — SELECT A TERRITORY', 16, 24);
  }

  function stop() { if (raf) cancelAnimationFrame(raf); raf = 0; }

  UI.CampaignMap = {
    /**
     * @param {object} camp  {house, mission, owned:[], holders:{}}
     * @param {function} cb  called with the chosen territory
     */
    show: function (camp, cb) {
      init();
      state = camp; onAttack = cb; picked = null; hover = null;
      choices = DUNE.CAMPAIGN.choicesFor(camp.mission, camp.owned);
      if (choices.length === 1) {
        picked = choices[0];
        U.$('#cm-attack').disabled = false;
      } else {
        U.$('#cm-attack').disabled = true;
      }
      U.$('#cm-house').textContent = DUNE.house(camp.house).name;
      U.$('#cm-mission').textContent = camp.mission + ' / ' + DUNE.CAMPAIGN.count;
      U.$('#cm-owned').textContent = camp.owned.length;
      U.$('#cm-sub').textContent = choices.length > 1
        ? 'Choose your next target. The ground you pick decides the fight you get.'
        : 'One target remains. Arrakeen must fall.';
      showInfo(picked);
      stop();
      raf = requestAnimationFrame(loop);
    },
    hide: stop
  };
})();
"},{"path":"js/ui/hud.js","type":"text/javascript","text":"/* =============================================================================
   hud.js - topbar readouts, the selection panel and the order buttons.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;
  var UI = DUNE.UI = DUNE.UI || {};

  var world = null;
  var elCredits, elSpiceBar, elSpiceTxt, elPowerBar, elPowerTxt, elObjective;
  var elSel, elOrders, elAlerts, elCrest, elMission;
  var shownCredits = 0;
  var lastSelSig = '';
  var alertKeys = {};

  /* --------------------------- order definitions -------------------------- */
  /* each: {id, label, hint, show(sel), enabled(sel), run(sel)} */
  var ORDERS = [
    {
      id: 'move', label: 'MOVE', mode: 'move',
      show: function (s) { return s.units.length > 0; }
    },
    {
      id: 'attack', label: 'ATTACK', mode: 'attack',
      show: function (s) { return s.units.some(function (u) { return u.weapon() || u.def.suicide; }); }
    },
    {
      id: 'guard', label: 'GUARD',
      show: function (s) { return s.units.length > 0; },
      run: function (s) {
        s.units.forEach(function (u) { u.stopMoving(); u.setOrder({ t: 'guard' }); });
        world.notify('Holding position', null, 'guard');
      }
    },
    {
      id: 'harvest', label: 'HARVEST', mode: 'harvest',
      show: function (s) { return s.units.some(function (u) { return u.def.harvester; }); }
    },
    {
      id: 'unload', label: 'UNLOAD',
      show: function (s) { return s.units.some(function (u) { return u.def.harvester; }); },
      run: function (s) {
        s.units.forEach(function (u) { if (u.def.harvester) u.setOrder({ t: 'return' }); });
        world.notify('Harvesters returning to refinery', null, 'unload');
        DUNE.Sfx.play('order', 0.8);
      }
    },
    {
      id: 'repair', label: 'REPAIR',
      show: function (s) {
        return s.units.some(function (u) { return u.def.move === 'track' || u.def.move === 'wheel'; })
            || s.structures.length > 0;
      },
      run: function (s) {
        var any = false;
        s.units.forEach(function (u) {
          if (u.def.move === 'track' || u.def.move === 'wheel') { u.setOrder({ t: 'repairself' }); any = true; }
        });
        s.structures.forEach(function (b) {
          b.repairing = !b.repairing; any = true;
          world.notify(b.def.name + (b.repairing ? ' repairing' : ' repair stopped'), null, 'rep' + b.id);
        });
        if (any) DUNE.Sfx.play('repair', 0.8);
      }
    },
    {
      id: 'deploy', label: 'DEPLOY',
      show: function (s) { return s.units.some(function (u) { return u.def.deploy; }); },
      run: function (s) {
        s.units.forEach(function (u) { if (u.def.deploy) u.setOrder({ t: 'deploy' }); });
      }
    },
    {
      id: 'scatter', label: 'SCATTER',
      show: function (s) { return s.units.length > 1; },
      run: function (s) {
        s.units.forEach(function (u) {
          var a = Math.random() * U.TAU;
          u.setOrder({
            t: 'move',
            x: u.tx + Math.round(Math.cos(a) * CFG.SCATTER_RANGE),
            y: u.ty + Math.round(Math.sin(a) * CFG.SCATTER_RANGE)
          });
        });
        DUNE.Sfx.play('order', 0.7);
      }
    },
    {
      id: 'stop', label: 'STOP',
      show: function (s) { return s.units.length > 0; },
      run: function (s) {
        s.units.forEach(function (u) { u.stopMoving(); u.setOrder({ t: 'stop' }); u.target = null; });
      }
    },
    {
      id: 'rally', label: 'RALLY', mode: 'rally',
      show: function (s) { return s.structures.some(function (b) { return b.def.produces && b.def.produces !== 'structure'; }); }
    },
    {
      id: 'primary', label: 'PRIMARY',
      show: function (s) { return s.structures.some(function (b) { return b.def.produces && b.def.produces !== 'structure'; }); },
      run: function (s) {
        s.structures.forEach(function (b) {
          if (b.def.produces && b.def.produces !== 'structure') {
            world.playerFaction.primaryOf[b.def.produces] = b;
            world.notify(b.def.name + ' is now the primary factory', 'good');
          }
        });
      }
    },
    {
      id: 'sell', label: 'SELL', cls: 'danger',
      show: function (s) { return s.structures.length > 0; },
      run: function (s) {
        var total = 0;
        s.structures.slice().forEach(function (b) { total += b.sell(); });
        world.notify('Sold for ¤' + Math.round(total), 'good');
        world.clearSelection();
      }
    },
    {
      id: 'detonate', label: 'DETONATE', cls: 'danger',
      show: function (s) { return s.units.some(function (u) { return u.def.selfDestruct; }); },
      run: function (s) {
        s.units.forEach(function (u) {
          if (u.def.selfDestruct) { u.hp = 0; u.destroy('combat'); }
        });
      }
    }
  ];

  /* -------------------------------- init ---------------------------------- */
  function init(w) {
    world = w;
    elCredits = U.$('#ro-credits');
    elSpiceBar = U.$('#ro-spicebar');
    elSpiceTxt = U.$('#ro-spicetext');
    elPowerBar = U.$('#ro-powerbar');
    elPowerTxt = U.$('#ro-powertext');
    elObjective = U.$('#ro-objective');
    elSel = U.$('#sel-info');
    elOrders = U.$('#order-buttons');
    elAlerts = U.$('#alerts');
    elCrest = U.$('#house-crest');
    elMission = U.$('#mission-name');

    shownCredits = world.playerFaction.credits;
    lastSelSig = '';
    alertKeys = {};
    elAlerts.innerHTML = '';

    // house crest in the corner
    var cv = document.createElement('canvas');
    cv.width = 22; cv.height = 22;
    DUNE.Sprites.crest(cv.getContext('2d'), world.playerFaction.houseId, 22);
    elCrest.innerHTML = '';
    elCrest.appendChild(cv);
    elMission.textContent = world.missionName;
    buildOrderButtons();
  }

  /* ------------------------------- topbar --------------------------------- */
  function updateTop(dt) {
    var f = world.playerFaction;
    var target = Math.floor(f.credits);
    if (shownCredits !== target) {
      var step = Math.max(1, Math.abs(target - shownCredits) * dt * 6);
      shownCredits = U.approach(shownCredits, target, step);
      if (Math.abs(target - shownCredits) > 1) DUNE.Sfx.play('credit', 0.25);
    }
    elCredits.textContent = U.pad(Math.round(shownCredits), 5);
    elCredits.parentNode.classList.toggle('flash', Math.abs(target - shownCredits) > 3);

    var cap = Math.max(1, f.capacity);
    var frac = U.clamp(f.credits / cap, 0, 1);
    elSpiceBar.style.width = (frac * 100) + '%';
    elSpiceBar.className = frac > 0.92 ? 'crit' : (frac > 0.75 ? 'warn' : '');
    elSpiceTxt.textContent = Math.round(f.credits) + '/' + cap;

    var need = Math.max(1, f.powerUsed);
    var pr = f.powerMade / need;
    elPowerBar.style.width = U.clamp(pr, 0, 1) * 100 + '%';
    elPowerBar.className = pr < 0.6 ? 'crit' : (pr < 1 ? 'warn' : '');
    elPowerTxt.textContent = Math.round(f.powerMade) + '/' + Math.round(f.powerUsed);

    elObjective.textContent = world.objectiveText();
  }

  /* ---------------------------- selection panel --------------------------- */
  function selectionSets() {
    var sel = world.selection;
    var units = [], structures = [];
    for (var i = 0; i < sel.length; i++) {
      if (!sel[i].alive) continue;
      if (sel[i].kind === 'unit') units.push(sel[i]);
      else structures.push(sel[i]);
    }
    return { units: units, structures: structures, all: units.concat(structures) };
  }

  function updateSelection() {
    var s = selectionSets();
    var sig = s.all.map(function (e) { return e.id; }).join(',') + '|' +
              s.all.map(function (e) { return Math.round(e.healthFrac() * 20); }).join(',') + '|' +
              s.all.map(function (e) { return e.kind === 'unit' ? e.order.t + (e.hstate || '') : (e.repairing ? 'r' : '') + (e.dockUnit ? 'd' : ''); }).join(',');
    if (sig === lastSelSig) return;
    lastSelSig = sig;

    if (!s.all.length) {
      elSel.innerHTML = '<span class="dim">No selection. Left-click or drag to select. ' +
                        'Right-click to order.</span>';
      buildOrderButtons();
      return;
    }

    var html = '';
    if (s.all.length === 1) {
      var e = s.all[0];
      html += '<div class="title">' + e.def.name + '</div>';
      html += '<div class="row">';
      html += chip('HP', Math.round(e.hp) + '/' + e.maxHp, e.healthFrac());
      if (e.kind === 'unit') {
        if (e.def.weapon) {
          var w = DUNE.WEAPONS[e.def.weapon];
          html += chip('WEAPON', w.name);
          html += chip('RANGE', (w.range * e.faction.mods.range).toFixed(1) + ' tiles');
        }
        if (e.def.harvester) {
          html += chip('CARGO', Math.round(e.cargo) + '/' + CFG.HARVESTER_CAP);
          html += chip('STATE', harvestStateName(e.hstate));
        }
        html += chip('ORDER', orderName(e));
        if (e.veteran) html += chip('RANK', e.veteran > 1 ? 'Elite' : 'Veteran');
        if (e.deviateT > 0) html += chip('STATUS', 'Deviated ' + Math.ceil(e.deviateT) + 's');
      } else {
        if (e.def.power > 0) html += chip('OUTPUT', '+' + e.def.power + ' power');
        else if (e.def.power < 0) html += chip('DRAW', e.def.power + ' power');
        if (e.def.storage) html += chip('STORAGE', '+' + e.def.storage);
        if (e.def.weapon) html += chip('WEAPON', DUNE.WEAPONS[e.def.weapon].name);
        var bare = e.uncoveredTiles();
        html += chip('FOUNDATION', bare === 0 ? 'Concrete' : (e.footTiles - bare) + '/' + e.footTiles + ' slabs');
        if (e.repairing) html += chip('STATUS', 'Repairing');
        if (e.dockUnit) html += chip('BAY', e.dockUnit.def.name);
        if (bare > 0) html += '<span class="chip" style="color:#ffb9ac">SAND DECAY</span>';
      }
      html += '</div>';
      html += '<div class="dim" style="margin-top:3px;font-size:10.5px">' + e.def.desc + '</div>';
    } else {
      html += '<div class="title">' + s.all.length + ' UNITS SELECTED</div>';
      var byType = {};
      s.all.forEach(function (e) { byType[e.def.name] = (byType[e.def.name] || 0) + 1; });
      html += '<div class="grouplist">';
      for (var k in byType) html += '<span class="gtag">' + k + ' x' + byType[k] + '</span>';
      html += '</div>';
      var hp = 0, mx = 0;
      s.all.forEach(function (e) { hp += e.hp; mx += e.maxHp; });
      html += '<div class="row">' + chip('TOTAL HP', Math.round(hp) + '/' + Math.round(mx), hp / mx) + '</div>';
    }
    elSel.innerHTML = html;
    buildOrderButtons();
  }

  function chip(label, value, frac) {
    var h = '<span class="chip"><b style="color:#9a7a48;font-weight:700">' + label + '</b> ' + value;
    if (frac != null) {
      var col = frac > 0.6 ? '#5ec46a' : (frac > 0.3 ? '#e0b83c' : '#c8352a');
      h += ' <span class="hpbar"><i style="width:' + (frac * 100) + '%;background:' + col + '"></i></span>';
    }
    return h + '</span>';
  }

  function harvestStateName(s) {
    return { idle: 'Idle', seek: 'Moving to spice', harvest: 'Harvesting',
             full: 'Full', return: 'Returning', unload: 'Unloading',
             flee: 'Fleeing a worm' }[s] || s;
  }

  function orderName(u) {
    var o = u.order;
    switch (o.t) {
      case 'move': return 'Moving';
      case 'amove': return 'Attack move';
      case 'attack': return 'Attacking';
      case 'guard': return u.target ? 'Engaging' : 'Guarding';
      case 'harvest': return 'Harvesting';
      case 'repairself': return 'To repair bay';
      case 'deploy': return 'Deploying';
      case 'ferry': return 'Ferrying';
      case 'sabotage': return 'Infiltrating';
      default: return 'Holding';
    }
  }

  /* ---------------------------- order buttons ----------------------------- */
  function buildOrderButtons() {
    var s = selectionSets();
    elOrders.innerHTML = '';
    if (!s.all.length) return;
    var mine = s.all.every(function (e) { return e.faction === world.playerFaction; });
    if (!mine) return;

    ORDERS.forEach(function (o) {
      if (!o.show(s)) return;
      var b = U.el('button', 'obtn' + (o.cls ? ' ' + o.cls : ''), o.label);
      if (o.mode && world.orderMode === o.mode) b.classList.add('on');
      b.addEventListener('click', function () {
        if (o.mode) {
          world.orderMode = world.orderMode === o.mode ? null : o.mode;
          UI.Hud.refresh();
          DUNE.Sfx.play('select', 0.6);
          var cv = U.$('#game-canvas');
          cv.classList.toggle('attack', world.orderMode === 'attack');
        } else if (o.run) {
          o.run(selectionSets());
          lastSelSig = '';
        }
      });
      elOrders.appendChild(b);
    });
  }

  /* ------------------------------- alerts --------------------------------- */
  function notify(msg, type, key) {
    if (key) {
      var now = world ? world.time : 0;
      if (alertKeys[key] && now - alertKeys[key] < 6) return;
      alertKeys[key] = now;
    }
    var el = U.el('div', 'alert' + (type ? ' ' + type : ''), msg);
    elAlerts.appendChild(el);
    while (elAlerts.children.length > 6) elAlerts.removeChild(elAlerts.firstChild);
    setTimeout(function () { el.classList.add('fade'); }, 3600);
    setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 4400);
  }

  UI.Hud = {
    init: init,
    notify: notify,
    refresh: function () { lastSelSig = ''; },
    update: function (dt) {
      if (!world || !world.playerFaction) return;
      updateTop(dt);
      updateSelection();
    }
  };
})();
"},{"path":"js/ui/input.js","type":"text/javascript","text":"/* =============================================================================
   input.js - mouse, keyboard and radar interaction.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;
  var UI = DUNE.UI = DUNE.UI || {};

  var world = null, canvas = null, rend = null;
  var keys = {};
  var drag = null;
  var mouse = { x: 0, y: 0, inside: false };
  var lastClickT = 0, lastClickEnt = null;
  var mapDrag = false;
  var bound = false;

  function init(w) {
    world = w;
    canvas = U.$('#game-canvas');
    rend = w.renderer;
    world.groups = world.groups || {};
    if (bound) return;
    bound = true;

    canvas.addEventListener('mousedown', onDown);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    canvas.addEventListener('contextmenu', function (e) { e.preventDefault(); });
    canvas.addEventListener('wheel', onWheel, { passive: false });
    canvas.addEventListener('mouseleave', function () { mouse.inside = false; });
    canvas.addEventListener('mouseenter', function () { mouse.inside = true; });

    var mm = U.$('#minimap');
    mm.addEventListener('mousedown', function (e) { mapDrag = true; onMinimap(e); });
    mm.addEventListener('mousemove', function (e) { if (mapDrag) onMinimap(e); });
    window.addEventListener('mouseup', function () { mapDrag = false; });
    mm.addEventListener('contextmenu', function (e) {
      e.preventDefault();
      onMinimapOrder(e);
    });

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', function (e) { keys[e.key.toLowerCase()] = false; });
    window.addEventListener('blur', function () { keys = {}; });
  }

  /* ------------------------------ helpers -------------------------------- */
  function canvasPos(e) {
    var r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  function playerSel() {
    return world.selection.filter(function (e) {
      return e.alive && e.faction === world.playerFaction;
    });
  }

  function selUnits() {
    return playerSel().filter(function (e) { return e.kind === 'unit'; });
  }

  /* ------------------------------- mouse --------------------------------- */
  function onDown(e) {
    if (world.state !== 'playing') return;
    DUNE.Sfx.resume();
    var p = canvasPos(e);
    var wp = rend.screenToWorld(p.x, p.y);
    var tile = { x: Math.floor(wp.x / CFG.TILE), y: Math.floor(wp.y / CFG.TILE) };

    if (e.button === 2) {
      onRightClick(tile, wp, e);
      return;
    }
    if (e.button !== 0) return;

    // placing a building
    if (world.placement) {
      world.tryPlace(tile.x, tile.y);
      return;
    }
    // aiming a palace weapon
    if (world.targetingSpecial) {
      world.playerFaction.useSpecial(tile.x, tile.y);
      world.targetingSpecial = false;
      canvas.classList.remove('attack');
      return;
    }
    // an explicit order mode from the button bar
    if (world.orderMode) {
      applyOrderMode(tile, wp, e);
      return;
    }

    drag = { x0: p.x, y0: p.y, x1: p.x, y1: p.y, w0: wp, moved: false, add: e.shiftKey };
  }

  function onMove(e) {
    if (world.state !== 'playing') return;
    var p = canvasPos(e);
    mouse.x = p.x; mouse.y = p.y;
    var wp = rend.screenToWorld(p.x, p.y);
    var tile = { x: Math.floor(wp.x / CFG.TILE), y: Math.floor(wp.y / CFG.TILE) };

    if (world.placement) {
      var def = DUNE.STRUCTS[world.placement.defId];
      var tx = U.clamp(tile.x - ((def.w / 2) | 0), 0, world.map.w - def.w);
      var ty = U.clamp(tile.y - ((def.h / 2) | 0), 0, world.map.h - def.h);
      var res = DUNE.Structure.checkPlacement(world, def.id, world.playerFaction, tx, ty);
      rend.placement = { defId: def.id, tx: tx, ty: ty, valid: res.ok, reason: res.reason };
    } else {
      rend.hoverEntity = world.entityAtTile(tile.x, tile.y);
    }

    if (drag) {
      drag.x1 = p.x; drag.y1 = p.y;
      if (Math.abs(drag.x1 - drag.x0) > 4 || Math.abs(drag.y1 - drag.y0) > 4) drag.moved = true;
      var a = rend.screenToWorld(drag.x0, drag.y0);
      var b = rend.screenToWorld(drag.x1, drag.y1);
      rend.selectionBox = drag.moved ? { x0: a.x, y0: a.y, x1: b.x, y1: b.y } : null;
    }
  }

  function onUp(e) {
    if (!drag || world.state !== 'playing') { drag = null; return; }
    var p = canvasPos(e);
    var a = rend.screenToWorld(drag.x0, drag.y0);
    var b = rend.screenToWorld(p.x, p.y);
    rend.selectionBox = null;

    if (drag.moved) {
      selectInBox(Math.min(a.x, b.x), Math.min(a.y, b.y), Math.max(a.x, b.x), Math.max(a.y, b.y), drag.add);
    } else {
      clickSelect(b.x, b.y, drag.add, e);
    }
    drag = null;
  }

  function onWheel(e) {
    e.preventDefault();
    var p = canvasPos(e);
    rend.zoomAt(p.x, p.y, e.deltaY < 0 ? 1.12 : 1 / 1.12);
  }

  /* ----------------------------- selection -------------------------------- */
  function clickSelect(wx, wy, add, e) {
    var ent = world.entityAt(wx, wy);
    var now = performance.now();

    if (ent && ent === lastClickEnt && now - lastClickT < 350 && ent.kind === 'unit') {
      // double click: everything of that type on screen
      selectSameTypeOnScreen(ent);
      lastClickT = 0; lastClickEnt = null;
      return;
    }
    lastClickT = now; lastClickEnt = ent;

    if (!ent) {
      if (!add) world.clearSelection();
      return;
    }
    if (add) {
      if (world.selection.indexOf(ent) >= 0) world.deselect(ent);
      else world.select(ent, true);
    } else {
      world.setSelection([ent]);
    }
    DUNE.Sfx.play('select', 0.7);
  }

  function selectSameTypeOnScreen(proto) {
    var v = rend.viewRect();
    var out = [];
    world.units.forEach(function (u) {
      if (!u.alive || u.hidden) return;
      if (u.faction !== world.playerFaction) return;
      if (u.def.id !== proto.def.id) return;
      if (u.x < v.x || u.x > v.x + v.w || u.y < v.y || u.y > v.y + v.h) return;
      out.push(u);
    });
    if (out.length) {
      world.setSelection(out);
      DUNE.Sfx.play('select', 0.9);
    }
  }

  function selectInBox(x0, y0, x1, y1, add) {
    var out = add ? world.selection.slice() : [];
    var anyUnit = false;
    world.units.forEach(function (u) {
      if (!u.alive || u.hidden || u.carriedBy) return;
      if (u.faction !== world.playerFaction) return;
      if (u.x < x0 || u.x > x1 || u.y < y0 || u.y > y1) return;
      if (out.indexOf(u) < 0) out.push(u);
      anyUnit = true;
    });
    if (!anyUnit) {
      // dragging over buildings selects them instead
      world.structures.forEach(function (s) {
        if (!s.alive || s.faction !== world.playerFaction) return;
        var sx = s.tx * CFG.TILE, sy = s.ty * CFG.TILE;
        if (sx + s.w * CFG.TILE < x0 || sx > x1 || sy + s.h * CFG.TILE < y0 || sy > y1) return;
        if (out.indexOf(s) < 0) out.push(s);
      });
    } else {
      out = out.filter(function (e) { return e.kind === 'unit'; });
    }
    world.setSelection(out);
    if (out.length) DUNE.Sfx.play('select', 0.8);
  }

  /* ------------------------------- orders --------------------------------- */
  function onRightClick(tile, wp, e) {
    if (world.placement) { UI.Sidebar.cancelPlacement(); return; }
    if (world.targetingSpecial) {
      world.targetingSpecial = false;
      canvas.classList.remove('attack');
      return;
    }
    if (world.orderMode) { world.orderMode = null; UI.Hud.refresh(); canvas.classList.remove('attack'); return; }

    var sel = playerSel();
    if (!sel.length) return;

    var ent = world.entityAt(wp.x, wp.y);
    var units = sel.filter(function (s) { return s.kind === 'unit'; });
    var builds = sel.filter(function (s) { return s.kind === 'structure'; });

    // factories take a rally point
    builds.forEach(function (b) {
      if (b.def.produces && b.def.produces !== 'structure') {
        b.rally = { x: tile.x, y: tile.y };
        world.notify(b.def.name + ' rally point set', null, 'rally');
      }
    });

    if (!units.length) return;

    if (ent && ent.faction && ent.faction !== world.playerFaction) {
      issueAttack(units, ent);
      return;
    }
    if (ent && ent.kind === 'structure' && ent.faction === world.playerFaction) {
      var used = false;
      units.forEach(function (u) {
        if (u.def.harvester && ent.def.id === 'refinery') { u.setOrder({ t: 'enter', target: ent }); used = true; }
        else if (ent.def.id === 'repair' && (u.def.move === 'track' || u.def.move === 'wheel')) {
          u.setOrder({ t: 'repairself' }); used = true;
        }
      });
      if (used) { DUNE.Sfx.play('order', 0.8); return; }
    }

    var spice = world.map.spiceAt(tile.x, tile.y);
    var harvesters = units.filter(function (u) { return u.def.harvester; });
    if (spice > 5 && harvesters.length) {
      harvesters.forEach(function (u) {
        u.hstate = 'seek';
        u.harvestTile = { x: tile.x, y: tile.y };
        u.setOrder({ t: 'harvest', x: tile.x, y: tile.y });
      });
      world.notify('Harvesting ordered', null, 'harv');
      DUNE.Sfx.play('order', 0.8);
      var rest = units.filter(function (u) { return !u.def.harvester; });
      if (rest.length) issueMove(rest, tile);
      return;
    }

    issueMove(units, tile);
  }

  function applyOrderMode(tile, wp, e) {
    var units = selUnits();
    var mode = world.orderMode;
    var ent = world.entityAt(wp.x, wp.y);

    if (mode === 'attack') {
      if (ent && ent.faction !== world.playerFaction) issueAttack(units, ent);
      else {
        units.forEach(function (u) { u.setOrder({ t: 'amove', x: tile.x, y: tile.y }); });
        world.notify('Attack move ordered', null, 'amove');
        DUNE.Sfx.play('order', 0.9);
      }
    } else if (mode === 'move') {
      issueMove(units, tile);
    } else if (mode === 'harvest') {
      units.forEach(function (u) {
        if (!u.def.harvester) return;
        u.hstate = 'seek';
        u.harvestTile = { x: tile.x, y: tile.y };
        u.setOrder({ t: 'harvest', x: tile.x, y: tile.y });
      });
      DUNE.Sfx.play('order', 0.8);
    } else if (mode === 'rally') {
      playerSel().forEach(function (b) {
        if (b.kind === 'structure' && b.def.produces) b.rally = { x: tile.x, y: tile.y };
      });
      world.notify('Rally point set', null, 'rally');
    }
    if (!e.shiftKey) {
      world.orderMode = null;
      canvas.classList.remove('attack');
      UI.Hud.refresh();
    }
  }

  function issueAttack(units, ent) {
    var any = false;
    units.forEach(function (u) {
      if (u.def.suicide) { u.setOrder({ t: 'sabotage', target: ent }); any = true; return; }
      if (!u.weapon()) {
        u.setOrder({ t: 'move', x: ent.tx, y: ent.ty });
        return;
      }
      u.setOrder({ t: 'attack', target: ent });
      any = true;
    });
    if (any) {
      world.notify('Attacking ' + ent.def.name, null, 'atk');
      DUNE.Sfx.play('order', 0.9);
      world.effects.text(ent.x, ent.y - 18, 'TARGET', '#ffb9ac');
    }
  }

  /** Spreads a group order out so units do not all path to one tile. */
  function issueMove(units, tile) {
    if (!units.length) return;
    var n = units.length;
    var cols = Math.ceil(Math.sqrt(n));
    var idx = 0;
    var map = world.map;
    units.forEach(function (u) {
      var ox = (idx % cols) - (cols - 1) / 2;
      var oy = Math.floor(idx / cols) - (Math.ceil(n / cols) - 1) / 2;
      idx++;
      var gx = U.clamp(Math.round(tile.x + ox), 0, map.w - 1);
      var gy = U.clamp(Math.round(tile.y + oy), 0, map.h - 1);
      if (map.terrainCost(gx, gy, u.def.move) === Infinity || map.building[gy * map.w + gx]) {
        var free = map.findFreeTile(tile.x, tile.y, u.def.move, 5, u.id);
        if (free) { gx = free.x; gy = free.y; }
      }
      u.setOrder({ t: 'move', x: gx, y: gy });
    });
    world.effects.text(map.cx(tile.x), map.cy(tile.y), '▼', '#f0d7a6');
    DUNE.Sfx.play('order', 0.8);
  }

  /* ------------------------------- radar ---------------------------------- */
  function onMinimap(e) {
    if (!world.minimap || !world.minimap.online) return;
    var r = e.currentTarget.getBoundingClientRect();
    var mx = (e.clientX - r.left) * (world.minimap.w / r.width);
    var my = (e.clientY - r.top) * (world.minimap.h / r.height);
    var wp = world.minimap.toWorld(mx, my);
    rend.centreOn(wp.x, wp.y);
  }

  function onMinimapOrder(e) {
    if (!world.minimap || !world.minimap.online) return;
    var r = e.currentTarget.getBoundingClientRect();
    var mx = (e.clientX - r.left) * (world.minimap.w / r.width);
    var my = (e.clientY - r.top) * (world.minimap.h / r.height);
    var wp = world.minimap.toWorld(mx, my);
    var tile = { x: Math.floor(wp.x / CFG.TILE), y: Math.floor(wp.y / CFG.TILE) };
    var units = selUnits();
    if (units.length) issueMove(units, tile);
  }

  /* ------------------------------ keyboard -------------------------------- */
  function onKeyDown(e) {
    var k = e.key.toLowerCase();
    keys[k] = true;
    if (world.state !== 'playing' && k !== 'escape') return;

    if (e.ctrlKey && k >= '1' && k <= '9') {
      world.groups[k] = playerSel().filter(function (x) { return x.kind === 'unit'; });
      world.notify('Group ' + k + ' assigned (' + world.groups[k].length + ')', null, 'grp');
      e.preventDefault();
      return;
    }
    if (!e.ctrlKey && k >= '1' && k <= '9') {
      var g = (world.groups[k] || []).filter(function (x) { return x.alive; });
      if (g.length) {
        world.setSelection(g);
        DUNE.Sfx.play('select', 0.8);
        if (world._lastGroupKey === k && world.time - (world._lastGroupT || 0) < 0.4) {
          rend.centreOn(g[0].x, g[0].y);
        }
        world._lastGroupKey = k; world._lastGroupT = world.time;
      }
      return;
    }

    switch (k) {
      case 'escape':
        if (world.placement) UI.Sidebar.cancelPlacement();
        else if (world.targetingSpecial) { world.targetingSpecial = false; canvas.classList.remove('attack'); }
        else if (world.orderMode) { world.orderMode = null; canvas.classList.remove('attack'); UI.Hud.refresh(); }
        else world.clearSelection();
        break;
      case ' ':
        world.togglePause();
        e.preventDefault();
        break;
      case 'a':
        world.orderMode = world.orderMode === 'attack' ? null : 'attack';
        canvas.classList.toggle('attack', world.orderMode === 'attack');
        UI.Hud.refresh();
        break;
      case 'g':
        selUnits().forEach(function (u) { u.stopMoving(); u.setOrder({ t: 'guard' }); });
        break;
      case 's':
        selUnits().forEach(function (u) { u.stopMoving(); u.setOrder({ t: 'stop' }); u.target = null; });
        break;
      case 'h':
        selUnits().forEach(function (u) { if (u.def.harvester) { u.hstate = 'idle'; u.autoHarvest(); } });
        break;
      case 'r':
        playerSel().forEach(function (e2) {
          if (e2.kind === 'structure') e2.repairing = !e2.repairing;
          else if (e2.def.move === 'track' || e2.def.move === 'wheel') e2.setOrder({ t: 'repairself' });
        });
        UI.Hud.refresh();
        break;
      case 'd':
        selUnits().forEach(function (u) { if (u.def.deploy) u.setOrder({ t: 'deploy' }); });
        break;
      case 'f':
        // jump to the next idle harvester
        var hv = world.playerFaction.units.filter(function (u) {
          return u.alive && u.def.harvester;
        });
        if (hv.length) {
          world._hvIdx = ((world._hvIdx || 0) + 1) % hv.length;
          var t = hv[world._hvIdx];
          world.setSelection([t]);
          rend.centreOn(t.x, t.y);
        }
        break;
      case 'b':
        var cy = world.playerFaction.primaryStructure();
        if (cy) rend.centreOn(cy.x, cy.y);
        break;
      case 'tab':
        rend.showRanges = !rend.showRanges;
        e.preventDefault();
        break;
    }
  }

  /* ------------------------------ per frame -------------------------------- */
  function update(dt) {
    if (!world || world.state !== 'playing') return;
    var sp = CFG.SCROLL_SPEED * dt;
    var dx = 0, dy = 0;
    // arrow keys only - the letters are all order hotkeys
    if (keys['arrowleft']) dx -= sp;
    if (keys['arrowright']) dx += sp;
    if (keys['arrowup']) dy -= sp;
    if (keys['arrowdown']) dy += sp;

    // edge scrolling
    if (mouse.inside && !drag) {
      var b = CFG.EDGE_SCROLL;
      if (mouse.x < b) dx -= sp;
      if (mouse.x > rend.vw - b) dx += sp;
      if (mouse.y < b) dy -= sp;
      if (mouse.y > rend.vh - b) dy += sp;
    }
    if (dx || dy) rend.scroll(dx, dy);
  }

  UI.Input = { init: init, update: update, keys: keys };
})();
"},{"path":"js/ui/mentat.js","type":"text/javascript","text":"/* =============================================================================
   mentat.js - the briefing screen.

   Your House Mentat appears before every mission, delivers the situation in
   his own voice, and lists the objectives. The text types itself out and his
   mouth moves while it does.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util;
  var UI = DUNE.UI = DUNE.UI || {};

  var canvas, ctx, elText, elTitle, elName, elObj;
  var raf = 0, t0 = 0;
  var brief = null, typed = 0, typing = false, onDone = null;
  var CHARS_PER_SEC = 62;

  function init() {
    if (canvas) return;
    canvas = U.$('#mentat-canvas');
    ctx = canvas.getContext('2d');
    elText = U.$('#mentat-text');
    elTitle = U.$('#mentat-title');
    elName = U.$('#mentat-name');
    elObj = U.$('#mentat-obj');

    U.on('#mentat-repeat', 'click', function () {
      typed = 0; typing = true;
      DUNE.Sfx.play('select', 0.6);
    });
    U.on('#mentat-proceed', 'click', function () {
      if (typing && typed < brief.text.length) {
        typed = brief.text.length;       // first press finishes the text
        typing = false;
        render();
        return;
      }
      DUNE.Sfx.play('order', 0.8);
      stop();
      if (onDone) onDone();
    });
  }

  function loop(ts) {
    raf = requestAnimationFrame(loop);
    if (!t0) t0 = ts;
    var t = (ts - t0) / 1000;

    if (typing) {
      var want = Math.floor(t * CHARS_PER_SEC);
      if (want > typed) {
        typed = Math.min(brief.text.length, want);
        render();
        if (typed >= brief.text.length) typing = false;
      }
    }
    DUNE.Sprites.mentat(ctx, brief.house, canvas.width, canvas.height, t, typing);
  }

  function render() {
    var shown = brief.text.slice(0, typed);
    elText.textContent = shown;
    if (typing) {
      var cur = U.el('span', 'cursor', '▌');
      elText.appendChild(cur);
    }
    elText.scrollTop = elText.scrollHeight;
  }

  function stop() {
    if (raf) cancelAnimationFrame(raf);
    raf = 0; t0 = 0; typing = false;
  }

  UI.Mentat = {
    /**
     * @param {object} b   result of DUNE.CAMPAIGN.brief()
     * @param {function} cb called when the player presses PROCEED
     */
    show: function (b, cb) {
      init();
      brief = b; onDone = cb;
      typed = 0; typing = true; t0 = 0;

      elTitle.textContent = b.title;
      elName.textContent = (b.mentat || 'Mentat').toUpperCase();
      elName.style.color = DUNE.house(b.house).colourLight;

      elObj.innerHTML = '';
      var head = U.el('b', null, 'OBJECTIVES');
      elObj.appendChild(head);
      var ul = U.el('div');
      b.objectives.forEach(function (o) {
        var line = U.el('div', null, '▸ ' + o);
        ul.appendChild(line);
      });
      elObj.appendChild(ul);

      elText.textContent = '';
      stop();
      raf = requestAnimationFrame(loop);
    },

    /** Also used for the post-mission debrief, with a custom button label. */
    showMessage: function (houseId, title, text, buttonLabel, cb) {
      init();
      brief = { house: houseId, text: text, title: title, objectives: [],
                mentat: DUNE.house(houseId).mentat };
      onDone = cb;
      typed = 0; typing = true; t0 = 0;
      elTitle.textContent = title;
      elName.textContent = (brief.mentat || 'Mentat').toUpperCase();
      elObj.innerHTML = '';
      elText.textContent = '';
      U.$('#mentat-proceed').textContent = buttonLabel || 'PROCEED';
      stop();
      raf = requestAnimationFrame(loop);
    },

    hide: stop
  };
})();
"},{"path":"js/ui/sidebar.js","type":"text/javascript","text":"/* =============================================================================
   sidebar.js - the Construction Yard panel.

   Structures are bought here and then *placed* by hand on the map, which is
   the whole Dune II build loop. Items you cannot build yet stay visible but
   locked, with the prerequisite spelled out, so the tech tree is legible.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;
  var UI = DUNE.UI = DUNE.UI || {};

  var world = null, listEl, tabsEl, specialEl;
  var tab = 'structure';
  var rows = {};          // defId -> {el, prog, veil, qty, cost}
  var builtFor = '';      // signature of the last DOM build

  function init(w) {
    world = w;
    listEl = U.$('#build-list');
    tabsEl = U.$('#build-tabs');
    specialEl = U.$('#special-panel');
    tab = 'structure';

    tabsEl.innerHTML = '';
    addTab('structure', 'BUILD');
    addTab('unit', 'UNITS');
    builtFor = '';
    rebuild();
  }

  function addTab(key, label) {
    var b = U.el('button', key === tab ? 'active' : '', label);
    b.setAttribute('data-tab', key);
    b.addEventListener('click', function () {
      tab = key;
      U.$$('#build-tabs button').forEach(function (x) {
        x.className = x.getAttribute('data-tab') === key ? 'active' : '';
      });
      builtFor = '';
      rebuild();
      DUNE.Sfx.play('select', 0.5);
    });
    tabsEl.appendChild(b);
  }

  /* ------------------------------ item list ------------------------------ */
  function itemsForTab() {
    var f = world.playerFaction;
    var out = [];
    if (tab === 'structure') {
      DUNE.STRUCT_ORDER.forEach(function (id) {
        var def = DUNE.STRUCTS[id];
        if (!DUNE.houseAllowsStruct(def, f.houseId)) return;
        if (id === 'construction') return;      // only ever from an MCV
        out.push(id);
      });
    } else if (tab === 'unit') {
      DUNE.UNIT_ORDER.forEach(function (id) {
        var def = DUNE.UNITS[id];
        if (!DUNE.houseAllowsUnit(def, f.houseId)) return;
        out.push(id);
      });
    } else if (tab === 'starport') {
      DUNE.STARPORT_STOCK.forEach(function (id) {
        var def = DUNE.UNITS[id];
        if (!DUNE.houseAllowsUnit(def, f.houseId)) return;
        out.push(id);
      });
    }
    return out;
  }

  function signature() {
    var f = world.playerFaction;
    var keys = Object.keys(f.counts).sort().join(',');
    return tab + '|' + keys + '|' + f.tech + '|' + f.has('starport');
  }

  function rebuild() {
    var sig = signature();
    if (sig === builtFor) return;
    builtFor = sig;

    var f = world.playerFaction;
    // add or remove the Starport tab as the building comes and goes
    var hasSp = f.has('starport');
    var spTab = tabsEl.querySelector('[data-tab="starport"]');
    if (hasSp && !spTab) addTab('starport', 'GUILD');
    if (!hasSp && spTab) { spTab.remove(); if (tab === 'starport') tab = 'unit'; }

    listEl.innerHTML = '';
    rows = {};
    var ids = itemsForTab();

    for (var i = 0; i < ids.length; i++) {
      var id = ids[i];
      var def = DUNE.STRUCTS[id] || DUNE.UNITS[id];
      var check = f.canBuild(id, { starport: tab === 'starport' });

      var row = U.el('div', 'bitem');
      var cv = document.createElement('canvas');
      cv.width = 44; cv.height = 36;
      DUNE.Sprites.icon(cv, id, f.houseId);
      row.appendChild(cv);

      var meta = U.el('div', 'meta');
      meta.appendChild(U.el('div', 'nm', def.name));
      var cost = U.el('div', 'cost', '¤' + f.priceOf(id, tab === 'starport'));
      meta.appendChild(cost);
      var sub = U.el('div', 'sub', check.ok ? subtitleFor(def) : check.reason);
      meta.appendChild(sub);
      row.appendChild(meta);

      var qty = U.el('div', 'qty');
      qty.style.display = 'none';
      row.appendChild(qty);

      var prog = U.el('i', 'prog');
      row.appendChild(prog);

      var veil = U.el('div', 'veil');
      veil.style.display = 'none';
      row.appendChild(veil);

      if (!check.ok) row.classList.add('locked');
      row.title = def.name + ' — ' + def.desc + (check.ok ? '' : '\n\n' + check.reason);

      bindRow(row, id);
      listEl.appendChild(row);
      rows[id] = { el: row, prog: prog, veil: veil, qty: qty, cost: cost, sub: sub, def: def };
    }
  }

  function subtitleFor(def) {
    if (def.kind === 'structure') {
      var bits = [];
      if (def.power > 0) bits.push('+' + def.power + ' pwr');
      else if (def.power < 0) bits.push(def.power + ' pwr');
      if (def.storage) bits.push('+' + def.storage + ' spice');
      if (def.produces) bits.push('factory');
      if (def.weapon) bits.push('defence');
      return bits.join(' · ') || (def.w + 'x' + def.h);
    }
    var b = [];
    if (def.weapon) b.push(DUNE.WEAPONS[def.weapon].name);
    else if (def.harvester) b.push('harvests spice');
    else if (def.carrier) b.push('lifts harvesters');
    else if (def.deploy) b.push('deploys into a base');
    return b.join(' · ');
  }

  function bindRow(row, id) {
    row.addEventListener('click', function (e) {
      e.preventDefault();
      onActivate(id, e.shiftKey);
    });
    row.addEventListener('contextmenu', function (e) {
      e.preventDefault();
      onCancel(id);
    });
  }

  /* ------------------------------ actions -------------------------------- */
  function onActivate(id, shift) {
    var f = world.playerFaction;
    var key = tab === 'starport' ? 'starport' : f.queueKey(id);
    var head = f.activeItem(key, id);

    // a finished structure is waiting to be sited
    if (head && head.state === 'ready' && head.id === id) {
      UI.Sidebar.beginPlacement(id);
      return;
    }
    var check = f.canBuild(id, { starport: tab === 'starport' });
    if (!check.ok) {
      world.notify(check.reason, 'bad');
      DUNE.Sfx.play('deny', 0.7);
      return;
    }
    var times = shift ? 5 : 1;
    for (var i = 0; i < times; i++) {
      var res = f.enqueue(id, { starport: tab === 'starport' });
      if (!res.ok) { world.notify(res.reason, 'bad'); DUNE.Sfx.play('deny', 0.7); return; }
    }
    DUNE.Sfx.play('build', 0.7);
  }

  function onCancel(id) {
    var f = world.playerFaction;
    var key = tab === 'starport' ? 'starport' : f.queueKey(id);
    if (f.cancel(key, id)) {
      DUNE.Sfx.play('deny', 0.6);
      world.notify('Order cancelled', null, 'cancel');
      if (world.placement && world.placement.defId === id) UI.Sidebar.cancelPlacement();
    }
  }

  /* ---------------------------- placement mode ---------------------------- */
  UI.Sidebar = {
    init: init,
    rebuild: function () { builtFor = ''; rebuild(); },

    beginPlacement: function (id) {
      world.placement = { defId: id };
      world.renderer.placement = { defId: id, tx: -1, ty: -1, valid: false, reason: '' };
      U.$('#game-canvas').classList.add('place');
      world.notify('Place the ' + DUNE.STRUCTS[id].name + ' — it must adjoin your base', null, 'placehint');
    },

    cancelPlacement: function () {
      world.placement = null;
      if (world.renderer) world.renderer.placement = null;
      U.$('#game-canvas').classList.remove('place');
    },

    isPlacing: function () { return !!world.placement; },

    /* ------------------------------ per frame ---------------------------- */
    update: function (dt) {
      if (!world || !world.playerFaction) return;
      rebuild();
      var f = world.playerFaction;

      for (var id in rows) {
        var r = rows[id];
        var key = tab === 'starport' ? 'starport' : f.queueKey(id);
        var q = f.queues[key];
        var head = q && q.items.length ? q.items[0] : null;
        var mine = head && head.id === id ? head : null;
        var queued = f.queuedCount(key, id);
        var check = f.canBuild(id, { starport: tab === 'starport' });

        r.el.classList.toggle('locked', !check.ok && !mine);
        if (!check.ok && r.sub.textContent !== check.reason) r.sub.textContent = check.reason;
        else if (check.ok) {
          var st = subtitleFor(r.def);
          if (r.sub.textContent !== st) r.sub.textContent = st;
        }

        var price = f.priceOf(id, tab === 'starport');
        r.el.classList.toggle('cantafford', f.credits < price);

        if (mine) {
          r.el.classList.add('building');
          r.prog.style.width = (mine.progress * 100) + '%';
          if (mine.state === 'ready') {
            r.el.classList.add('ready');
            r.veil.style.display = 'flex';
            r.veil.className = 'veil ready';
            r.veil.textContent = 'PLACE IT';
          } else if (mine.state === 'delivering') {
            r.veil.style.display = 'flex';
            r.veil.className = 'veil';
            r.veil.textContent = 'INBOUND ' + Math.ceil(mine.delivery) + 's';
          } else if (mine.state === 'hold') {
            r.veil.style.display = 'flex';
            r.veil.className = 'veil hold';
            r.veil.textContent = 'NO FUNDS';
          } else {
            r.veil.style.display = 'flex';
            r.veil.className = 'veil';
            r.veil.textContent = Math.floor(mine.progress * 100) + '%';
          }
        } else {
          r.el.classList.remove('building', 'ready');
          r.prog.style.width = '0%';
          r.veil.style.display = 'none';
        }

        if (queued > 1) {
          r.qty.style.display = 'block';
          r.qty.textContent = 'x' + queued;
        } else {
          r.qty.style.display = 'none';
        }
      }

      updateSpecial();
    }
  };

  /* --------------------------- palace superweapon ------------------------ */
  var specialBtn = null;
  function updateSpecial() {
    var f = world.playerFaction;
    var sp = f.special;
    if (!sp) {
      if (specialBtn) { specialEl.innerHTML = ''; specialBtn = null; }
      return;
    }
    if (!specialBtn) {
      specialEl.innerHTML = '';
      specialBtn = U.el('button', 'special-btn');
      var bar = U.el('i');
      specialBtn.appendChild(bar);
      specialBtn._bar = bar;
      specialBtn.addEventListener('click', function () {
        if (!f.special || !f.special.ready) { DUNE.Sfx.play('deny', 0.6); return; }
        if (f.special.id === 'saboteur') {
          f.useSpecial();
        } else {
          world.targetingSpecial = true;
          U.$('#game-canvas').classList.add('attack');
          world.notify('Select a target location', null, 'special');
        }
        DUNE.Sfx.play('select', 1);
      });
      specialEl.appendChild(specialBtn);
    }
    var label = sp.name.toUpperCase();
    if (!sp.ready) label += ' — ' + Math.ceil(sp.timer) + 's';
    else label += ' — READY';
    if (specialBtn.firstChild.nodeType === 3) specialBtn.firstChild.nodeValue = label;
    else specialBtn.insertBefore(document.createTextNode(label), specialBtn.firstChild);
    specialBtn.disabled = !sp.ready;
    var frac = sp.ready ? 1 : 1 - sp.timer / DUNE.house(f.houseId).palace.cooldown;
    specialBtn._bar.style.width = (frac * 100) + '%';
  }
})();
"},{"path":"js/util/util.js","type":"text/javascript","text":"/* =============================================================================
   util.js - maths, seeded randomness, geometry and small DOM helpers.
   Everything hangs off the global DUNE namespace; no modules so the project
   runs straight off the filesystem with no server.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util = {};

  var TAU = Math.PI * 2;
  U.TAU = TAU;

  /* ------------------------------- numbers ------------------------------ */
  U.clamp = function (v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); };
  U.lerp = function (a, b, t) { return a + (b - a) * t; };
  U.sign = function (v) { return v < 0 ? -1 : (v > 0 ? 1 : 0); };
  U.round = function (v) { return Math.round(v); };

  /** Moves `cur` toward `target` by at most `step`. */
  U.approach = function (cur, target, step) {
    if (cur < target) return Math.min(cur + step, target);
    if (cur > target) return Math.max(cur - step, target);
    return cur;
  };

  /* ------------------------------- angles ------------------------------- */
  U.norm = function (a) {
    a = a % TAU;
    if (a > Math.PI) a -= TAU;
    if (a < -Math.PI) a += TAU;
    return a;
  };
  /** Shortest signed difference from a to b. */
  U.angDiff = function (a, b) { return U.norm(b - a); };
  /** Rotate `cur` toward `target` by at most `step` radians. */
  U.rotToward = function (cur, target, step) {
    var d = U.angDiff(cur, target);
    if (Math.abs(d) <= step) return U.norm(target);
    return U.norm(cur + U.sign(d) * step);
  };
  /** Snap an angle to one of `n` facings (Dune II style chunky rotation). */
  U.snapAngle = function (a, n) {
    var step = TAU / n;
    return Math.round(a / step) * step;
  };

  /* ------------------------------ geometry ------------------------------ */
  U.dist = function (ax, ay, bx, by) {
    var dx = bx - ax, dy = by - ay;
    return Math.sqrt(dx * dx + dy * dy);
  };
  U.dist2 = function (ax, ay, bx, by) {
    var dx = bx - ax, dy = by - ay;
    return dx * dx + dy * dy;
  };
  U.angleTo = function (ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax); };
  /** Chebyshev distance - the right metric for 8-way tile movement. */
  U.cheb = function (ax, ay, bx, by) {
    return Math.max(Math.abs(bx - ax), Math.abs(by - ay));
  };
  U.rectsOverlap = function (a, b) {
    return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
  };
  U.pointInPoly = function (px, py, pts) {
    var inside = false, n = pts.length;
    for (var i = 0, j = n - 1; i < n; j = i++) {
      var xi = pts[i][0], yi = pts[i][1], xj = pts[j][0], yj = pts[j][1];
      if (((yi > py) !== (yj > py)) && (px < (xj - xi) * (py - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
  };

  /* ------------------------------- random ------------------------------- */
  /** mulberry32 - small, fast, deterministic. Returns a function in [0,1). */
  U.rng = function (seed) {
    var a = (seed >>> 0) || 1;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  };
  /** Deterministic hash of two integers into [0,1). Used for per-tile detail. */
  U.hash2 = function (x, y, seed) {
    var h = (x * 374761393 + y * 668265263 + (seed || 0) * 2147483647) | 0;
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
  };
  U.stringSeed = function (s) {
    var h = 2166136261 >>> 0;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  };
  U.pick = function (arr, rnd) { return arr[Math.floor((rnd ? rnd() : Math.random()) * arr.length)]; };
  U.shuffle = function (arr, rnd) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor((rnd ? rnd() : Math.random()) * (i + 1));
      var t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }
    return arr;
  };

  /* -------------------------------- noise ------------------------------- */
  /**
   * Cheap tileable-ish value noise. Builds a lattice of random values and
   * samples it with smoothstep interpolation; octaves are summed.
   */
  U.makeNoise = function (seed) {
    var rnd = U.rng(seed);
    var SZ = 256;
    var grid = new Float32Array(SZ * SZ);
    for (var i = 0; i < grid.length; i++) grid[i] = rnd();
    function at(x, y) { return grid[((y & (SZ - 1)) * SZ) + (x & (SZ - 1))]; }
    function smooth(t) { return t * t * (3 - 2 * t); }
    function sample(x, y) {
      var xi = Math.floor(x), yi = Math.floor(y);
      var xf = smooth(x - xi), yf = smooth(y - yi);
      var a = at(xi, yi), b = at(xi + 1, yi), c = at(xi, yi + 1), d = at(xi + 1, yi + 1);
      return U.lerp(U.lerp(a, b, xf), U.lerp(c, d, xf), yf);
    }
    return function (x, y, octaves, scale) {
      octaves = octaves || 4; scale = scale || 1;
      var amp = 1, freq = scale, sum = 0, norm = 0;
      for (var o = 0; o < octaves; o++) {
        sum += sample(x * freq, y * freq) * amp;
        norm += amp;
        amp *= 0.5; freq *= 2;
      }
      return sum / norm;
    };
  };

  /* -------------------------------- colour ------------------------------ */
  U.rgb = function (r, g, b) {
    return 'rgb(' + (r | 0) + ',' + (g | 0) + ',' + (b | 0) + ')';
  };
  U.shade = function (hex, amt) {
    var c = U.hexToRgb(hex);
    return U.rgb(U.clamp(c[0] + amt, 0, 255), U.clamp(c[1] + amt, 0, 255), U.clamp(c[2] + amt, 0, 255));
  };
  U.mix = function (hexA, hexB, t) {
    var a = U.hexToRgb(hexA), b = U.hexToRgb(hexB);
    return U.rgb(U.lerp(a[0], b[0], t), U.lerp(a[1], b[1], t), U.lerp(a[2], b[2], t));
  };
  U.hexToRgb = function (hex) {
    hex = hex.replace('#', '');
    if (hex.length === 3) hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
    var n = parseInt(hex, 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  U.alpha = function (hex, a) {
    var c = U.hexToRgb(hex);
    return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
  };

  /* ------------------------------ formatting ---------------------------- */
  U.pad = function (n, w) {
    var s = String(n);
    while (s.length < w) s = '0' + s;
    return s;
  };
  U.mmss = function (sec) {
    sec = Math.max(0, Math.floor(sec));
    return Math.floor(sec / 60) + ':' + U.pad(sec % 60, 2);
  };

  /* --------------------------------- DOM -------------------------------- */
  U.$ = function (sel, root) { return (root || document).querySelector(sel); };
  U.$$ = function (sel, root) {
    return Array.prototype.slice.call((root || document).querySelectorAll(sel));
  };
  U.el = function (tag, cls, txt) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (txt != null) e.textContent = txt;
    return e;
  };
  U.on = function (target, evt, fn, opts) {
    if (typeof target === 'string') target = U.$(target);
    if (target) target.addEventListener(evt, fn, opts || false);
    return target;
  };

  /* ------------------------------- storage ------------------------------ */
  var KEY = 'dune2.save.v1';
  U.save = function (data) {
    try { localStorage.setItem(KEY, JSON.stringify(data)); return true; }
    catch (e) { return false; }
  };
  U.load = function () {
    try {
      var s = localStorage.getItem(KEY);
      return s ? JSON.parse(s) : null;
    } catch (e) { return null; }
  };
  U.clearSave = function () {
    try { localStorage.removeItem(KEY); } catch (e) { /* ignore */ }
  };

  /* ----------------------------- collections ---------------------------- */
  U.remove = function (arr, item) {
    var i = arr.indexOf(item);
    if (i >= 0) arr.splice(i, 1);
    return i >= 0;
  };
  U.minBy = function (arr, fn) {
    var best = null, bestV = Infinity;
    for (var i = 0; i < arr.length; i++) {
      var v = fn(arr[i], i);
      if (v < bestV) { bestV = v; best = arr[i]; }
    }
    return best;
  };
  U.count = function (arr, fn) {
    var n = 0;
    for (var i = 0; i < arr.length; i++) if (fn(arr[i])) n++;
    return n;
  };

  /* ------------------------- fixed-capacity heap ------------------------ */
  /** Binary min-heap over integer node ids keyed by a Float32Array of costs. */
  U.Heap = function (cost) {
    this.cost = cost;
    this.data = [];
  };
  U.Heap.prototype.clear = function () { this.data.length = 0; };
  U.Heap.prototype.size = function () { return this.data.length; };
  U.Heap.prototype.push = function (n) {
    var d = this.data, c = this.cost, i = d.length;
    d.push(n);
    while (i > 0) {
      var p = (i - 1) >> 1;
      if (c[d[p]] <= c[d[i]]) break;
      var t = d[p]; d[p] = d[i]; d[i] = t; i = p;
    }
  };
  U.Heap.prototype.pop = function () {
    var d = this.data, c = this.cost;
    var top = d[0], last = d.pop();
    if (d.length) {
      d[0] = last;
      var i = 0, n = d.length;
      for (;;) {
        var l = i * 2 + 1, r = l + 1, s = i;
        if (l < n && c[d[l]] < c[d[s]]) s = l;
        if (r < n && c[d[r]] < c[d[s]]) s = r;
        if (s === i) break;
        var t = d[s]; d[s] = d[i]; d[i] = t; i = s;
      }
    }
    return top;
  };
})();
"},{"path":"js/world/fog.js","type":"text/javascript","text":"/* =============================================================================
   fog.js - shroud and live visibility, tracked per faction.

   Two layers, as Dune II had them: ground you have never walked is solid
   black, and ground you have explored but cannot currently see is dimmed.
   Enemy units inside the dimmed band are not drawn at all.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  var discCache = {};
  /** Offsets of every tile inside radius r, computed once per radius. */
  function disc(r) {
    var key = r | 0;
    if (discCache[key]) return discCache[key];
    var out = [];
    var rr = r * r;
    for (var y = -key; y <= key; y++) {
      for (var x = -key; x <= key; x++) {
        if (x * x + y * y <= rr + r * 0.5) out.push(x, y);
      }
    }
    discCache[key] = out;
    return out;
  }

  function Fog(map, enabled) {
    this.map = map;
    this.w = map.w; this.h = map.h;
    this.explored = new Uint8Array(map.n);
    this.visible = new Uint8Array(map.n);
    this.enabled = enabled !== false;
    this.timer = 0;
    this.dirty = true;
    if (!this.enabled) {
      this.explored.fill(1);
      this.visible.fill(1);
    }
  }

  Fog.prototype.isExplored = function (tx, ty) {
    if (!this.enabled) return true;
    if (tx < 0 || ty < 0 || tx >= this.w || ty >= this.h) return false;
    return this.explored[ty * this.w + tx] === 1;
  };
  Fog.prototype.isVisible = function (tx, ty) {
    if (!this.enabled) return true;
    if (tx < 0 || ty < 0 || tx >= this.w || ty >= this.h) return false;
    return this.visible[ty * this.w + tx] === 1;
  };
  /** Visibility test in world pixels. */
  Fog.prototype.seesPoint = function (px, py) {
    return this.isVisible(Math.floor(px / CFG.TILE), Math.floor(py / CFG.TILE));
  };

  /** Permanently reveal a radius - used for mission-start base reveals. */
  Fog.prototype.reveal = function (tx, ty, r) {
    var d = disc(r), w = this.w, h = this.h;
    for (var i = 0; i < d.length; i += 2) {
      var x = tx + d[i], y = ty + d[i + 1];
      if (x < 0 || y < 0 || x >= w || y >= h) continue;
      this.explored[y * w + x] = 1;
    }
    this.dirty = true;
  };

  Fog.prototype.revealAll = function () {
    this.explored.fill(1);
    this.dirty = true;
  };

  /**
   * Recomputes the live visibility layer from everything the faction owns.
   * Throttled: vision only needs refreshing a handful of times a second.
   */
  Fog.prototype.update = function (dt, faction) {
    if (!this.enabled) return;
    this.timer -= dt;
    if (this.timer > 0) return;
    this.timer = CFG.FOG_UPDATE;

    var vis = this.visible, exp = this.explored, w = this.w, h = this.h;
    vis.fill(0);

    var i, j, e, d, x, y, r;

    for (i = 0; i < faction.structures.length; i++) {
      e = faction.structures[i];
      if (!e.alive || e.building) continue;
      r = Math.max(2, Math.round(e.sight));
      d = disc(r);
      var bx = e.tx + (e.def.w - 1) / 2, by = e.ty + (e.def.h - 1) / 2;
      for (j = 0; j < d.length; j += 2) {
        x = Math.round(bx) + d[j]; y = Math.round(by) + d[j + 1];
        if (x < 0 || y < 0 || x >= w || y >= h) continue;
        var k = y * w + x;
        vis[k] = 1; exp[k] = 1;
      }
    }

    for (i = 0; i < faction.units.length; i++) {
      e = faction.units[i];
      if (!e.alive || e.hidden) continue;
      r = Math.max(2, Math.round(e.sight));
      d = disc(r);
      var ux = e.tx, uy = e.ty;
      for (j = 0; j < d.length; j += 2) {
        x = ux + d[j]; y = uy + d[j + 1];
        if (x < 0 || y < 0 || x >= w || y >= h) continue;
        var m = y * w + x;
        vis[m] = 1; exp[m] = 1;
      }
    }

    this.dirty = true;
  };

  /** Fraction of the map explored - shown on the debrief screen. */
  Fog.prototype.exploredFraction = function () {
    var n = 0;
    for (var i = 0; i < this.explored.length; i++) if (this.explored[i]) n++;
    return n / this.explored.length;
  };

  DUNE.Fog = Fog;
})();
"},{"path":"js/world/map.js","type":"text/javascript","text":"/* =============================================================================
   map.js - procedural Arrakis: rock, dunes, mountains, spice blooms, and the
   occupancy grids that movement and building placement run on.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG, T = DUNE.T;

  /**
   * @param {object} o  {seed, w, h, spice:1..3, rock:1..3, starts:n}
   */
  function GameMap(o) {
    o = o || {};
    this.w = o.w || CFG.MAP_W;
    this.h = o.h || CFG.MAP_H;
    this.seed = o.seed || 12345;
    this.n = this.w * this.h;

    this.terrain = new Uint8Array(this.n);
    this.spice = new Float32Array(this.n);
    this.spiceSeed = new Uint8Array(this.n);   // tiles that slowly re-bloom
    this.concrete = new Uint8Array(this.n);
    this.building = new Int32Array(this.n);    // structure id occupying the tile
    this.unit = new Int32Array(this.n);        // ground unit id claiming the tile
    this.dirty = [];                           // tiles the renderer must repaint

    this.starts = [];
    this.generate(o);
  }

  /* ----------------------------- basic access ---------------------------- */
  GameMap.prototype.idx = function (tx, ty) { return ty * this.w + tx; };
  GameMap.prototype.inBounds = function (tx, ty) {
    return tx >= 0 && ty >= 0 && tx < this.w && ty < this.h;
  };
  GameMap.prototype.terrainAt = function (tx, ty) {
    if (!this.inBounds(tx, ty)) return T.MOUNTAIN;
    return this.terrain[ty * this.w + tx];
  };
  GameMap.prototype.markDirty = function (i) { this.dirty.push(i); };

  GameMap.prototype.setTerrain = function (tx, ty, t) {
    var i = ty * this.w + tx;
    if (this.terrain[i] !== t) { this.terrain[i] = t; this.dirty.push(i); }
  };

  GameMap.prototype.setConcrete = function (tx, ty, v) {
    var i = ty * this.w + tx;
    if (this.concrete[i] !== v) { this.concrete[i] = v; this.dirty.push(i); }
  };

  /** Pixel centre of a tile. */
  GameMap.prototype.cx = function (tx) { return tx * CFG.TILE + CFG.TILE / 2; };
  GameMap.prototype.cy = function (ty) { return ty * CFG.TILE + CFG.TILE / 2; };
  GameMap.prototype.tileOf = function (px) { return Math.floor(px / CFG.TILE); };

  /* ------------------------------ movement ------------------------------- */
  /**
   * Terrain-only passability. Occupancy is handled separately so the
   * pathfinder can treat units as soft obstacles.
   */
  GameMap.prototype.terrainCost = function (tx, ty, move) {
    if (!this.inBounds(tx, ty)) return Infinity;
    if (move === 'air') return 1;
    var i = ty * this.w + tx;
    if (this.concrete[i]) return 1;
    var info = DUNE.TERRAIN[this.terrain[i]];
    var c = info[move];
    return c == null ? Infinity : c;
  };

  GameMap.prototype.passable = function (tx, ty, move) {
    if (move === 'air') return this.inBounds(tx, ty);
    if (this.terrainCost(tx, ty, move) === Infinity) return false;
    return this.building[ty * this.w + tx] === 0;
  };

  /** Free for a ground unit to step onto right now. */
  GameMap.prototype.stepFree = function (tx, ty, move, selfId) {
    if (!this.passable(tx, ty, move)) return false;
    var u = this.unit[ty * this.w + tx];
    return u === 0 || u === selfId;
  };

  /* --------------------------- spice management -------------------------- */
  GameMap.prototype.spiceAt = function (tx, ty) {
    if (!this.inBounds(tx, ty)) return 0;
    return this.spice[ty * this.w + tx];
  };

  /** Removes up to `amount` spice from a tile, returning what was taken. */
  GameMap.prototype.takeSpice = function (tx, ty, amount) {
    var i = ty * this.w + tx;
    var got = Math.min(this.spice[i], amount);
    if (got <= 0) return 0;
    this.spice[i] -= got;
    var t = this.terrain[i];
    var want = this.spice[i] <= 0 ? T.SAND
             : this.spice[i] > CFG.TILE_SPICE ? T.SPICE2 : T.SPICE;
    if (t !== want) { this.terrain[i] = want; this.dirty.push(i); }
    else if (((this.spice[i] + got) / 60 | 0) !== (this.spice[i] / 60 | 0)) this.dirty.push(i);
    return got;
  };

  /** Slow re-bloom so a long mission does not strand every harvester. */
  GameMap.prototype.updateSpice = function (dt) {
    this._regrowAcc = (this._regrowAcc || 0) + dt;
    if (this._regrowAcc < 1.5) return;
    var step = this._regrowAcc; this._regrowAcc = 0;
    var list = this._seedList;
    if (!list) {
      list = this._seedList = [];
      for (var i = 0; i < this.n; i++) if (this.spiceSeed[i]) list.push(i);
    }
    // touch a slice each pass rather than the whole field
    var start = this._regrowCursor || 0;
    var count = Math.min(list.length, 400);
    for (var k = 0; k < count; k++) {
      var j = list[(start + k) % list.length];
      if (this.building[j] || this.concrete[j]) continue;
      var cap = this.spiceSeed[j] === 2 ? CFG.TILE_SPICE_THICK : CFG.TILE_SPICE;
      if (this.spice[j] < cap) {
        var before = this.spice[j];
        this.spice[j] = Math.min(cap, this.spice[j] + CFG.SPICE_REGROW * step);
        var want = this.spice[j] <= 0 ? T.SAND
                 : this.spice[j] > CFG.TILE_SPICE ? T.SPICE2 : T.SPICE;
        if (this.terrain[j] !== want) { this.terrain[j] = want; this.dirty.push(j); }
        else if (Math.floor(before / 60) !== Math.floor(this.spice[j] / 60)) this.dirty.push(j);
      }
    }
    this._regrowCursor = (start + count) % Math.max(1, list.length);
  };

  /* ---------------------------- spiral search ---------------------------- */
  /**
   * Walks outward from (tx,ty) calling fn(x,y,i) until it returns truthy.
   * Returns whatever fn returned, or null.
   */
  GameMap.prototype.spiral = function (tx, ty, maxR, fn) {
    var r, x, y, res;
    res = fn(tx, ty, this.idx(tx, ty));
    if (res) return res;
    for (r = 1; r <= maxR; r++) {
      for (x = tx - r; x <= tx + r; x++) {
        for (y = ty - r; y <= ty + r; y++) {
          if (Math.max(Math.abs(x - tx), Math.abs(y - ty)) !== r) continue;
          if (!this.inBounds(x, y)) continue;
          res = fn(x, y, this.idx(x, y));
          if (res) return res;
        }
      }
    }
    return null;
  };

  GameMap.prototype.findNearestSpice = function (tx, ty, maxR, filter) {
    var self = this;
    return this.spiral(tx, ty, maxR || 26, function (x, y, i) {
      if (self.spice[i] > 10 && self.building[i] === 0 && !self.concrete[i]) {
        if (filter && !filter(x, y, i)) return null;
        return { x: x, y: y };
      }
      return null;
    });
  };

  GameMap.prototype.findFreeTile = function (tx, ty, move, maxR, selfId) {
    var self = this;
    return this.spiral(tx, ty, maxR || 8, function (x, y) {
      return self.stepFree(x, y, move || 'track', selfId || -1) ? { x: x, y: y } : null;
    });
  };

  /* ============================== generation ============================= */
  GameMap.prototype.generate = function (o) {
    var w = this.w, h = this.h;
    var rnd = U.rng(this.seed);
    var nTerr = U.makeNoise(this.seed);
    var nSpice = U.makeNoise(this.seed ^ 0x5a5a);
    var nDune = U.makeNoise(this.seed ^ 0x1234);

    var rockLevel = (o.rock == null ? 2 : o.rock);     // 1..3
    var spiceLevel = (o.spice == null ? 2 : o.spice);  // 1..3

    /* Rock coverage: low rock territories are nearly all sand. */
    var rockThresh = [0.615, 0.545, 0.485][U.clamp(rockLevel - 1, 0, 2)];
    var mountThresh = rockThresh + 0.085;
    var spiceThresh = [0.700, 0.648, 0.600][U.clamp(spiceLevel - 1, 0, 2)];

    var i, x, y, v;
    for (y = 0; y < h; y++) {
      for (x = 0; x < w; x++) {
        i = y * w + x;
        v = nTerr(x, y, 4, 0.055);
        // fall off toward the map edge so bases are not jammed into corners
        var edge = Math.min(x, y, w - 1 - x, h - 1 - y);
        if (edge < 3) v -= (3 - edge) * 0.05;
        var t;
        if (v > mountThresh) t = T.MOUNTAIN;
        else if (v > rockThresh) t = T.ROCK;
        else {
          var d = nDune(x, y, 3, 0.09);
          t = d > 0.56 ? T.DUNES : T.SAND;
        }
        this.terrain[i] = t;
      }
    }

    /* Spice blooms only on open sand, thickest at the core of a bloom. */
    for (y = 0; y < h; y++) {
      for (x = 0; x < w; x++) {
        i = y * w + x;
        if (this.terrain[i] !== T.SAND && this.terrain[i] !== T.DUNES) continue;
        var s = nSpice(x, y, 3, 0.07);
        if (s > spiceThresh + 0.075) {
          this.terrain[i] = T.SPICE2;
          this.spice[i] = CFG.TILE_SPICE_THICK * (0.7 + rnd() * 0.3);
          this.spiceSeed[i] = 2;
        } else if (s > spiceThresh) {
          this.terrain[i] = T.SPICE;
          this.spice[i] = CFG.TILE_SPICE * (0.6 + rnd() * 0.4);
          this.spiceSeed[i] = 1;
        }
      }
    }

    this.placeStarts(o.starts || 2, rnd);
    this.connectStarts();
    this.ensureSpiceNearStarts(rnd);
  };

  /** Picks well-separated start sites and flattens a rock plateau at each. */
  GameMap.prototype.placeStarts = function (count, rnd) {
    var w = this.w, h = this.h, self = this;
    var margin = 7;
    var cand = [];
    for (var a = 0; a < 700; a++) {
      var x = margin + Math.floor(rnd() * (w - margin * 2));
      var y = margin + Math.floor(rnd() * (h - margin * 2));
      cand.push({ x: x, y: y, score: rockScore(x, y) });
    }
    function rockScore(cx, cy) {
      var s = 0;
      for (var yy = cy - 3; yy <= cy + 3; yy++) {
        for (var xx = cx - 3; xx <= cx + 3; xx++) {
          if (!self.inBounds(xx, yy)) { s -= 4; continue; }
          var t = self.terrain[yy * w + xx];
          if (t === T.ROCK) s += 2;
          else if (t === T.MOUNTAIN) s -= 3;
          else if (t === T.SPICE || t === T.SPICE2) s -= 1;
        }
      }
      return s;
    }
    cand.sort(function (p, q) { return q.score - p.score; });

    var picked = [];
    var minSep = Math.max(18, Math.floor(Math.min(w, h) * 0.42));
    for (var pass = 0; pass < 3 && picked.length < count; pass++) {
      var sep = minSep - pass * 5;
      for (var c = 0; c < cand.length && picked.length < count; c++) {
        var p = cand[c], ok = true;
        for (var k = 0; k < picked.length; k++) {
          if (U.dist(p.x, p.y, picked[k].x, picked[k].y) < sep) { ok = false; break; }
        }
        if (ok) picked.push({ x: p.x, y: p.y });
      }
    }
    while (picked.length < count) {
      picked.push({ x: margin + Math.floor(rnd() * (w - margin * 2)),
                    y: margin + Math.floor(rnd() * (h - margin * 2)) });
    }

    /* Flatten each site into buildable rock and clear spice off it. */
    for (var s = 0; s < picked.length; s++) {
      var st = picked[s];
      for (var yy = st.y - 4; yy <= st.y + 4; yy++) {
        for (var xx = st.x - 4; xx <= st.x + 4; xx++) {
          if (!this.inBounds(xx, yy)) continue;
          var d = U.dist(xx, yy, st.x, st.y);
          if (d > 4.3) continue;
          var ii = yy * w + xx;
          this.terrain[ii] = T.ROCK;
          this.spice[ii] = 0;
          this.spiceSeed[ii] = 0;
        }
      }
      this.starts.push(st);
    }
  };

  /** Carves rock corridors so every start can physically reach every other. */
  GameMap.prototype.connectStarts = function () {
    for (var i = 1; i < this.starts.length; i++) {
      this.carve(this.starts[0].x, this.starts[0].y, this.starts[i].x, this.starts[i].y);
    }
    // and a couple of cross links for flanking routes
    for (var j = 2; j < this.starts.length; j++) {
      this.carve(this.starts[j - 1].x, this.starts[j - 1].y, this.starts[j].x, this.starts[j].y);
    }
  };

  /** Turns mountains along a line into passable ground (a natural pass). */
  GameMap.prototype.carve = function (x0, y0, x1, y1) {
    var steps = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
    for (var s = 0; s <= steps; s++) {
      var t = steps === 0 ? 0 : s / steps;
      var x = Math.round(U.lerp(x0, x1, t));
      var y = Math.round(U.lerp(y0, y1, t));
      for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
          var xx = x + dx, yy = y + dy;
          if (!this.inBounds(xx, yy)) continue;
          var i = yy * this.w + xx;
          if (this.terrain[i] === T.MOUNTAIN) this.terrain[i] = T.ROCK;
        }
      }
    }
  };

  /** Every start must have a workable field within harvesting distance. */
  GameMap.prototype.ensureSpiceNearStarts = function (rnd) {
    for (var s = 0; s < this.starts.length; s++) {
      var st = this.starts[s];
      var found = this.findNearestSpice(st.x, st.y, 14);
      if (found) continue;
      // drop a bloom on the nearest open sand
      var self = this;
      var site = this.spiral(st.x, st.y, 20, function (x, y, i) {
        return (self.terrain[i] === T.SAND || self.terrain[i] === T.DUNES) &&
               U.dist(x, y, st.x, st.y) > 6 ? { x: x, y: y } : null;
      });
      if (!site) continue;
      this.paintBloom(site.x, site.y, 4 + Math.floor(rnd() * 3), rnd);
    }
  };

  GameMap.prototype.paintBloom = function (cx, cy, r, rnd) {
    for (var y = cy - r; y <= cy + r; y++) {
      for (var x = cx - r; x <= cx + r; x++) {
        if (!this.inBounds(x, y)) continue;
        var d = U.dist(x, y, cx, cy);
        if (d > r) continue;
        var i = y * this.w + x;
        if (this.terrain[i] === T.ROCK || this.terrain[i] === T.MOUNTAIN) continue;
        var thick = d < r * 0.4;
        this.terrain[i] = thick ? T.SPICE2 : T.SPICE;
        this.spice[i] = thick ? CFG.TILE_SPICE_THICK : CFG.TILE_SPICE * (0.6 + rnd() * 0.4);
        this.spiceSeed[i] = thick ? 2 : 1;
        this.dirty.push(i);
        this._seedList = null;          // the regrow list needs rebuilding
      }
    }
  };

  /* --------------------------- building helpers -------------------------- */
  /** Total spice sitting within `r` tiles of a point - used by the AI. */
  GameMap.prototype.spiceAround = function (tx, ty, r) {
    var total = 0;
    for (var y = ty - r; y <= ty + r; y++) {
      for (var x = tx - r; x <= tx + r; x++) {
        if (!this.inBounds(x, y)) continue;
        total += this.spice[y * this.w + x];
      }
    }
    return total;
  };

  /** Centre of the richest spice concentration, for AI expansion planning. */
  GameMap.prototype.bestSpiceRegion = function (avoid, minDist) {
    var best = null, bestV = 0, step = 4;
    for (var y = step; y < this.h - step; y += step) {
      for (var x = step; x < this.w - step; x += step) {
        if (avoid) {
          var far = true;
          for (var i = 0; i < avoid.length; i++) {
            if (U.dist(x, y, avoid[i].x, avoid[i].y) < (minDist || 12)) { far = false; break; }
          }
          if (!far) continue;
        }
        var v = this.spiceAround(x, y, 5);
        if (v > bestV) { bestV = v; best = { x: x, y: y, value: v }; }
      }
    }
    return best;
  };

  DUNE.GameMap = GameMap;
})();
"},{"path":"js/world/pathfinder.js","type":"text/javascript","text":"/* =============================================================================
   pathfinder.js - 8-way A* over the tile grid.

   Other units are *soft* obstacles (extra cost, not walls) so columns flow
   around each other instead of deadlocking; buildings and mountains are hard.
   A per-frame node budget keeps a hundred simultaneous repaths from stalling
   the frame.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util;

  var DX = [1, -1, 0, 0, 1, 1, -1, -1];
  var DY = [0, 0, 1, -1, 1, -1, 1, -1];
  var DIAG = [0, 0, 0, 0, 1, 1, 1, 1];
  var SQRT2 = Math.SQRT2;

  function Pathfinder(map) {
    this.map = map;
    var n = map.n;
    this.g = new Float32Array(n);
    this.f = new Float32Array(n);
    this.from = new Int32Array(n);
    this.stamp = new Int32Array(n);   // visited marker, avoids clearing arrays
    this.closed = new Uint8Array(n);
    this.run = 0;
    this.heap = new U.Heap(this.f);
    this.budget = 0;
    this.frameBudget = 9000;
  }

  Pathfinder.prototype.beginFrame = function () { this.budget = this.frameBudget; };
  Pathfinder.prototype.hasBudget = function () { return this.budget > 0; };

  /**
   * @param {number} sx,sy   start tile
   * @param {number} gx,gy   goal tile
   * @param {object} opts    {move, selfId, adjacent, maxNodes, ignoreUnits, targetId}
   * @return {Array|null}    list of {x,y} steps (excluding the start), or null
   */
  Pathfinder.prototype.find = function (sx, sy, gx, gy, opts) {
    opts = opts || {};
    var map = this.map, w = map.w;
    if (!map.inBounds(sx, sy) || !map.inBounds(gx, gy)) return null;

    var move = opts.move || 'track';
    var selfId = opts.selfId || -1;
    var adjacent = !!opts.adjacent;
    var maxNodes = Math.min(opts.maxNodes || 5200, Math.max(400, this.budget));

    var start = sy * w + sx, goal = gy * w + gx;
    if (start === goal) return [];

    // Air units fly straight there.
    if (move === 'air') return [{ x: gx, y: gy }];

    this.run++;
    var run = this.run;
    var g = this.g, f = this.f, from = this.from, stamp = this.stamp, closed = this.closed;
    var heap = this.heap;
    heap.clear();

    g[start] = 0;
    f[start] = h(sx, sy, gx, gy);
    from[start] = -1;
    stamp[start] = run;
    closed[start] = 0;
    heap.push(start);

    var expanded = 0;
    var bestNode = start, bestH = f[start];
    var found = -1;

    while (heap.size()) {
      var cur = heap.pop();
      if (closed[cur] === 1 && stamp[cur] === run) continue;
      closed[cur] = 1;

      var cx = cur % w, cy = (cur / w) | 0;

      if (cur === goal || (adjacent && Math.max(Math.abs(cx - gx), Math.abs(cy - gy)) <= 1)) {
        found = cur;
        break;
      }

      expanded++;
      if (expanded > maxNodes) break;

      for (var d = 0; d < 8; d++) {
        var nx = cx + DX[d], ny = cy + DY[d];
        if (nx < 0 || ny < 0 || nx >= w || ny >= map.h) continue;
        var ni = ny * w + nx;

        var tcost = map.terrainCost(nx, ny, move);
        if (tcost === Infinity) continue;
        if (map.building[ni] !== 0 && !(opts.targetId && map.building[ni] === opts.targetId)) continue;

        if (DIAG[d]) {
          // no cutting corners through a blocked orthogonal neighbour
          if (map.terrainCost(cx + DX[d], cy, move) === Infinity ||
              map.terrainCost(cx, cy + DY[d], move) === Infinity) continue;
          if (map.building[cy * w + (cx + DX[d])] !== 0 ||
              map.building[(cy + DY[d]) * w + cx] !== 0) continue;
        }

        var step = tcost * (DIAG[d] ? SQRT2 : 1);

        // Soft penalty for tiles another unit is standing on or heading to.
        if (!opts.ignoreUnits) {
          var occ = map.unit[ni];
          if (occ !== 0 && occ !== selfId) step += 4.2;
        }

        var ng = g[cur] + step;
        if (stamp[ni] !== run) {
          stamp[ni] = run; closed[ni] = 0; g[ni] = Infinity;
        }
        if (ng < g[ni]) {
          g[ni] = ng;
          from[ni] = cur;
          var hh = h(nx, ny, gx, gy);
          f[ni] = ng + hh;
          if (hh < bestH) { bestH = hh; bestNode = ni; }
          heap.push(ni);
        }
      }
    }

    this.budget -= expanded;

    var end = found >= 0 ? found : bestNode;
    if (end === start) return found >= 0 ? [] : null;

    // walk the parent chain back
    var path = [];
    var node = end;
    var guard = 0;
    while (node !== -1 && node !== start && guard++ < 6000) {
      path.push({ x: node % w, y: (node / w) | 0 });
      node = from[node];
    }
    path.reverse();
    return path.length ? path : null;
  };

  /** Octile heuristic - admissible for 8-way movement. */
  function h(ax, ay, bx, by) {
    var dx = Math.abs(bx - ax), dy = Math.abs(by - ay);
    return (dx + dy) + (SQRT2 - 2) * Math.min(dx, dy);
  }

  /**
   * Quick line-of-sight test on the tile grid. Used to skip pathfinding
   * entirely for short unobstructed hops, which is most orders.
   */
  Pathfinder.prototype.clearLine = function (sx, sy, gx, gy, move, selfId) {
    var map = this.map;
    var steps = Math.max(Math.abs(gx - sx), Math.abs(gy - sy));
    if (steps > 10) return false;
    for (var s = 1; s <= steps; s++) {
      var t = s / steps;
      var x = Math.round(U.lerp(sx, gx, t));
      var y = Math.round(U.lerp(sy, gy, t));
      if (map.terrainCost(x, y, move) === Infinity) return false;
      if (map.building[y * map.w + x] !== 0) return false;
      var occ = map.unit[y * map.w + x];
      if (occ !== 0 && occ !== selfId) return false;
    }
    return true;
  };

  DUNE.Pathfinder = Pathfinder;
})();
"},{"path":"js/world/worm.js","type":"text/javascript","text":"/* =============================================================================
   worm.js - Shai-Hulud.

   A worm swims through open sand, feeling for the rhythmic vibration of
   machinery. It cannot cross rock or concrete, so a base on a plateau is safe;
   a harvester parked on a spice field is not. It surfaces, swallows, and sinks
   back. After a few meals it goes dormant for a while.
   ========================================================================== */
(function () {
  'use strict';
  var DUNE = window.DUNE = window.DUNE || {};
  var U = DUNE.util, CFG = DUNE.CFG;

  var STATE = { DORMANT: 0, HUNT: 1, RISE: 2, STRIKE: 3, DIVE: 4 };
  Worm.STATE = STATE;

  function Worm(world, tx, ty, seed) {
    this.world = world;
    this.id = world.nextId++;
    this.x = world.map.cx(tx);
    this.y = world.map.cy(ty);
    this.angle = Math.random() * U.TAU;
    this.state = STATE.HUNT;
    this.timer = 2 + Math.random() * 6;
    this.meals = CFG.WORM_MEALS;
    this.target = null;
    this.wander = null;
    this.rnd = U.rng(seed || (Math.random() * 1e9) | 0);
    this.history = [];
    this.hurt = 0;
    this.alive = true;
    this.riseT = 0;
    this.sizeScale = 0.9 + this.rnd() * 0.5;
  }

  Worm.prototype.tileX = function () { return Math.floor(this.x / CFG.TILE); };
  Worm.prototype.tileY = function () { return Math.floor(this.y / CFG.TILE); };

  /** Worms can only swim through open, unpaved sand. */
  Worm.prototype.canSwim = function (tx, ty) {
    var map = this.world.map;
    if (!map.inBounds(tx, ty)) return false;
    var i = ty * map.w + tx;
    if (map.concrete[i]) return false;
    if (map.building[i]) return false;
    return DUNE.isOpenSand(map.terrain[i]);
  };

  Worm.prototype.onSand = function () { return this.canSwim(this.tileX(), this.tileY()); };

  /** A unit is edible if it is on open sand and not flying or Fremen. */
  Worm.prototype.edible = function (u) {
    if (!u.alive || u.hidden) return false;
    if (u.def.move === 'air') return false;
    if (u.def.wormSafe) return false;
    return this.canSwim(u.tx, u.ty);
  };

  Worm.prototype.findPrey = function () {
    var best = null, bestScore = Infinity;
    var units = this.world.units;
    var sense = CFG.WORM_SENSE * CFG.TILE;
    for (var i = 0; i < units.length; i++) {
      var u = units[i];
      if (!this.edible(u)) continue;
      var d = U.dist(this.x, this.y, u.x, u.y);
      if (d > sense) continue;
      // machinery thumps louder than boots, and movement louder than idling
      var noise = (u.def.move === 'foot' ? 2.2 : 1.0) * (u.moving ? 0.65 : 1.0);
      var score = d * noise;
      if (score < bestScore) { bestScore = score; best = u; }
    }
    return best;
  };

  Worm.prototype.pickWander = function () {
    var map = this.world.map;
    for (var a = 0; a < 40; a++) {
      var tx = Math.floor(this.rnd() * map.w);
      var ty = Math.floor(this.rnd() * map.h);
      if (this.canSwim(tx, ty)) { this.wander = { x: map.cx(tx), y: map.cy(ty) }; return; }
    }
    this.wander = null;
  };

  /** Steers toward (gx,gy) but refuses to leave the sand. */
  Worm.prototype.steer = function (gx, gy, dt, speedScale) {
    var desired = U.angleTo(this.x, this.y, gx, gy);
    var probes = [0, 0.35, -0.35, 0.8, -0.8, 1.4, -1.4, 2.2, -2.2, Math.PI];
    var look = CFG.TILE * 2.0;
    var chosen = null;
    for (var i = 0; i < probes.length; i++) {
      var a = desired + probes[i];
      var px = this.x + Math.cos(a) * look;
      var py = this.y + Math.sin(a) * look;
      if (this.canSwim(Math.floor(px / CFG.TILE), Math.floor(py / CFG.TILE))) { chosen = a; break; }
    }
    if (chosen == null) chosen = this.angle + Math.PI;
    this.angle = U.rotToward(this.angle, chosen, 2.4 * dt);
    var sp = CFG.WORM_SPEED * CFG.TILE * (speedScale || 1);
    var nx = this.x + Math.cos(this.angle) * sp * dt;
    var ny = this.y + Math.sin(this.angle) * sp * dt;
    if (this.canSwim(Math.floor(nx / CFG.TILE), Math.floor(ny / CFG.TILE))) {
      this.x = nx; this.y = ny;
    }
  };

  Worm.prototype.pushHistory = function () {
    this.history.unshift({ x: this.x, y: this.y });
    if (this.history.length > 26) this.history.pop();
  };

  Worm.prototype.hit = function (dmg) {
    if (this.state === STATE.RISE || this.state === STATE.STRIKE) {
      this.hurt += dmg;
      if (this.hurt > 420) {
        this.hurt = 0;
        this.state = STATE.DIVE;
        this.timer = 0.7;
        this.meals = Math.max(0, this.meals - 1);
      }
    }
  };

  Worm.prototype.update = function (dt) {
    var world = this.world;
    this.timer -= dt;
    this.pushHistory();

    switch (this.state) {
      case STATE.DORMANT:
        if (this.timer <= 0) {
          this.meals = CFG.WORM_MEALS;
          this.state = STATE.HUNT;
          this.pickWander();
        }
        break;

      case STATE.HUNT:
        var prey = this.findPrey();
        this.target = prey;
        if (prey) {
          this.steer(prey.x, prey.y, dt, 1);
          if (U.dist(this.x, this.y, prey.x, prey.y) < CFG.WORM_EAT_RANGE * CFG.TILE) {
            this.state = STATE.RISE;
            this.riseT = 0;
            this.timer = CFG.WORM_STRIKE_TIME;
            DUNE.Sfx.play('worm', 1, world.audioDist(this.x, this.y));
            world.effects.sandBurst(this.x, this.y, 22);
          }
        } else {
          if (!this.wander || U.dist(this.x, this.y, this.wander.x, this.wander.y) < CFG.TILE * 2) {
            this.pickWander();
          }
          if (this.wander) this.steer(this.wander.x, this.wander.y, dt, 0.55);
          if (!this.onSand()) this.pickWander();
        }
        break;

      case STATE.RISE:
        this.riseT = 1 - Math.max(0, this.timer / CFG.WORM_STRIKE_TIME);
        // keep creeping onto the victim while the maw comes up
        if (this.target && this.edible(this.target)) {
          this.steer(this.target.x, this.target.y, dt, 0.35);
        }
        if (this.timer <= 0) {
          this.state = STATE.STRIKE;
          this.timer = 0.35;
          this.swallow();
        }
        break;

      case STATE.STRIKE:
        if (this.timer <= 0) { this.state = STATE.DIVE; this.timer = 0.9; }
        break;

      case STATE.DIVE:
        this.riseT = Math.max(0, this.timer / 0.9);
        if (this.timer <= 0) {
          if (this.meals <= 0) {
            this.state = STATE.DORMANT;
            this.timer = CFG.WORM_REST + this.rnd() * 18;
          } else {
            this.state = STATE.HUNT;
            this.pickWander();
          }
        }
        break;
    }
  };

  /** Anything caught in the maw is simply gone. */
  Worm.prototype.swallow = function () {
    var world = this.world;
    var r = CFG.TILE * 1.15;
    var eaten = 0;
    for (var i = world.units.length - 1; i >= 0; i--) {
      var u = world.units[i];
      if (!this.edible(u)) continue;
      if (U.dist(this.x, this.y, u.x, u.y) > r) continue;
      world.effects.sandBurst(u.x, u.y, 18);
      if (u.faction && u.faction.isPlayer) {
        world.notify(u.def.name + ' lost to Shai-Hulud!', 'bad');
      }
      u.destroy('worm');
      eaten++;
    }
    if (eaten) {
      this.meals -= eaten;
      DUNE.Sfx.play('wormeat', 1, world.audioDist(this.x, this.y));
      world.effects.sandBurst(this.x, this.y, 34);
      world.stats.wormKills += eaten;
    } else {
      // it lunged at nothing - that still counts as effort
      this.meals -= 0.5;
    }
  };

  DUNE.Worm = Worm;
})();
"}]}
